import Component from "./Component";
import {CharState, EntityTypes, TILE_SIZE} from "../Types";
import WonEngine from "../index";
import BlackFilter from "../filters/black";
import AutoTileRenderer from "../stageRenderers/AutoTileRenderer/AutoTileRenderer";

const blackFilter = new BlackFilter();

export default class SpriteRenderer extends Component {
    sprite = null
    pivotSprite: PIXI.Sprite;

    constructor(x = undefined, y = undefined, width = TILE_SIZE, height = TILE_SIZE,
                texture = PIXI.Texture.WHITE) {
        super();

        this.sprite = new PIXI.Sprite(texture);
        // this.sprite.filterArea = new PIXI.Rectangle(0, 0, TILE_SIZE, TILE_SIZE);

        // this.sprite.x = x;
        // this.sprite.y = y;
        this.sprite.width = width;
        this.sprite.height = height;


        this.pivotSprite = new PIXI.Sprite(PIXI.Texture.WHITE);
        this.pivotSprite.width = TILE_SIZE;
        this.pivotSprite.height = TILE_SIZE;
        this.pivotSprite.alpha = 0.5;


        // this.pivotSprite.renderable = false;

        this.sprite.addChild(this.pivotSprite);
    }

    setTexture(texture) {
        this.sprite.texture = texture || PIXI.Texture.WHITE;
    }

    init() {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        this.pivotSprite.parentLayer = mapToolRenderer.layers["PIVOT"];

        // if (!AutoTileRenderer.IsAutoTile(this.target.data) &&
        //     this.target.data.itemType === EntityTypes.OBJECT) {
        //     const size = this.target.data.texture.size;
        //     const yOffset = size[1] * TILE_SIZE * 0.5;
        //     this.sprite.y -= yOffset;
        //     this.pivotSprite.y += yOffset;
        //     this.sprite.width = size[0] * TILE_SIZE;
        //     this.sprite.height = size[1] * TILE_SIZE;
        // }

        this.target.addChild(this.sprite);
    }

    release() {
        this.target.removeChild(this.sprite);
    }
}
