import React, {Component, useState, useEffect, useRef} from 'react';
import request from "superagent";
import WonEngine, {RENDER_TYPE} from "../../WonEngine";
import {loadAutoTileData, saveAutoTileData} from "../../DataRequester";

const styles = {
    ToolBar: {
        border: '1px solid white',
        color: 'white',

        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: 'lightgray',
    },
    Button: {
        fontSize: 24,
        width: 70,
        height: 50,
        margin: 3,
    },
};

export default props => {
    const wonEngine = WonEngine.GetInstance();
    const {autoTileRenderer} = wonEngine.stageRenderers;

    const handleClickClear = () => {
        autoTileRenderer.clearTiles();
    };

    const handleClickInvert = () => {
        autoTileRenderer.invertTiles();
    };

    useEffect(() => {
        (async () => {
            const data = await loadAutoTileData();
            WonEngine.GetInstance().stageRenderers[RENDER_TYPE.AUTO_TILE_TOOL].LoadTiles(data);
        })();
    }, [])

    return <div style={styles.ToolBar}>
        <input style={styles.Button} type="button" value="Clear" onClick={handleClickClear.bind(this)}/>
        <input style={styles.Button} type="button" value="Invert" onClick={handleClickInvert.bind(this)}/>

        <input style={styles.Button} type="button" value="Save" onClick={saveAutoTileData.bind(this)}/>
        <input style={styles.Button} type="button" value="Load" onClick={loadAutoTileData.bind(this)}/>
    </div>
};
