import React from 'react';
import {EntityTypes} from "../../WonEngine/Types";
import CharacterImage from "../../components/CharacterImage";
import ItemImage from "../../components/ItemImage";
import SelectedMapToolIcon from "../../../www/res/icons/selectedMapToolItem.png";
import PropTypes from "prop-types";

const defaultOnClick = () => {

};

const MapToolItem = (props) => {
    const {uniqueKey, itemData, selectedItem, style, selectedListType = 0, onClick = defaultOnClick} = props;
    const itemName = itemData.name.charAt(0).toUpperCase() + itemData.name.slice(1).toLowerCase();
    const isSelected = uniqueKey === selectedItem.itemKey;

    return <div style={Object.assign({}, styles.mapToolItem, style)}
                onClick={onClick.bind(this, itemData, uniqueKey)}>
        <div style={Object.assign({}, styles.itemWrapper, isSelected && styles.selectedItem)}>
            {
                itemData.itemType === EntityTypes.CHARACTER
                    ? <CharacterImage character={itemData}/>
                    : <ItemImage item={itemData}/>
            }
            {
                isSelected && <img style={styles.selectedMapToolIcon} src={SelectedMapToolIcon}/>
            }
        </div>
        {
            selectedListType === 0 && <div style={Object.assign({}, styles.itemName, isSelected && {
                color: 'orange',
            })}>{itemName}</div>
        }
    </div>
}

// MapToolItem.propTypes = {
//     uniqueKey : PropTypes.string,
//     itemData: PropTypes.object,
//     selectedItem : PropTypes.object,
// };

export default MapToolItem;

const styles = {
    selectedMapToolIcon: {
        position: 'absolute',
    },
    selectedItem: {
        outline: '2px solid blue',
        boxSizing: 'border-box',
    },
    itemWrapper: {
        display: 'flex',
        // border: '2px solid black',
        boxSizing: 'border-box',
    },
    mapToolItem: {
        display: 'flex',
        // justifyContent: 'center',
        alignItems: 'center',
        margin: '0.2em',
        cursor: 'pointer',
    },
    itemName: {
        marginLeft: '0.2em',
        fontSize: '1.5em',
        textShadow: '2px 2px 2px white',
    },
}
