import React, {useEffect, useState} from 'react'
import MonacoEditor from 'react-monaco-editor';
import CharacterForm from "./CharacterForm";
import './CharacterTool.css';
import {defaultFormData} from "./CharacterSchemas";
import {saveCharactersData} from "../../DataRequester";
import CharacterMgr from "../../WonEngine/Managers/CharacterMgr/CharacterMgr";
import {CHARACTER_HEIGHT, CHARACTER_SHEET_HEIGHT, CHARACTER_SHEET_WIDTH, CHARACTER_WIDTH} from "./config";
import {generateSpriteSheet} from "../../hooks";
import CharacterImage from "../../components/CharacterImage";
import WonEngine from "../../WonEngine";

export default (props) => {
    const {characters, setCharacters} = props;
    const [selectedCharacterIndex, selectCharacter] = useState(-1);
    const [formData, setFormData] = useState(defaultFormData);

    useEffect(() => {
        const selectedCharacter = characters[selectedCharacterIndex];

        if (selectedCharacter) {
            setFormData({
                ...characters[selectedCharacterIndex],
            });
        }

        // // Todo refactoring
        // WonEngine.GetInstance().characters = characters;

    }, [characters, selectedCharacterIndex]);

    const handleClickSaveCharacters = async (characters) => {
        await saveCharactersData(characters.map(character => character));
    };

    const handleClickCharacter = (index) => {
        selectCharacter(index)
    };

    const toEditorValue = () => {

        return JSON.stringify(formData, null, 4);
    }

    return <div style={styles.characterTool}>
        <div style={styles.itemListView}>
            {
                characters.map((character, index) => {
                    const imageSrc = CharacterMgr.GetCharacterDataURL(character);
                    if (!imageSrc) return null;
                    return <div key={index} style={Object.assign({}, styles.characterListItem,
                        (selectedCharacterIndex === index) && styles.characterSelect)}
                                onClick={handleClickCharacter.bind(this, index)}>
                        <CharacterImage character={character}/>
                        <div style={styles.characterName}>{character.name}</div>
                    </div>
                })
            }
        </div>
        <div style={styles.characterView}>
            <div style={{
                flex: 1,
                display: 'flex',
                flexDirection: 'column',
            }}>
                <div style={styles.characterToolBar}>
                    <div style={{
                        margin: '0.2em',
                    }}>
                        <button onClick={handleClickSaveCharacters.bind(this, characters)}
                                style={styles.button}>Save
                        </button>
                        <button style={styles.button}>Load</button>
                    </div>


                </div>
                <div style={{
                    display: 'flex',
                    flex: 1,

                    flexDirection: 'row',
                }}>

                    <div style={{
                        borderRight: '1px solid darkGray',
                    }}>
                        <CharacterForm formData={formData} setFormData={setFormData}
                                       selectedCharacterIndex={selectedCharacterIndex}
                                       characters={characters} setCharacters={setCharacters}
                        />

                    </div>
                    <MonacoEditor width="800"
                        // height="600"
                                  language="json"
                                  theme="vs"
                                  value={JSON.stringify(formData, null, '\t')}
                                  options={{
                                      fontSize: 20,
                                      selectOnLineNumbers: true
                                  }}
                        // onChange={(newValue) => {
                        //     setFormData(newValue);
                        // }}
                        // editorDidMount={::this.editorDidMount}
                    />
                </div>
            </div>

        </div>
    </div>
}

const styles = {
    characterView: {
        flex: 1,
        display: 'flex',
        flexDirection: 'column',
    },
    characterToolBar: {
        borderRight: '1px solid darkGray',
        display: 'flex',
        flexDirection: 'row',
        backgroundColor: '#f6f9f8',
        borderBottom: '1px solid darkGray',
        fontSize: '2em',
        textShadow: '2px 2px 2px white',
        userSelect: 'none',
    },
    characterName: {
        display: 'flex',
        // justifyContent: 'center',
        alignItems: 'center',
        marginLeft: '0.5em',
    },
    characterImage: {
        objectFit: 'fill',
        objectPosition: '0 0',
        border: '2px solid black',
        width: `${CHARACTER_WIDTH * 1}px`,
        height: `${CHARACTER_HEIGHT * 1}px`,
        imageRendering: 'pixelated',
    },
    itemListView: {
        userSelect: "none",
        backgroundColor: 'lightgray',
        width: '250px',
        overflow: 'scroll',
    },
    button: {
        padding: '1em',
    },
    characterTool: {
        display: 'flex',
        // flex: 1,
        height: '100%',
        width: '100%',
    },
    characterListItem: {
        backgroundColor: 'white',
        margin: '0.2em',
        padding: '0.2em',
        border: '1px solid #bbb',
        // marginLeft: '0.2em',
        // fontSize: '1.5em',
        fontWeight: 'bold',
        textShadow: '2px 2px 2px #bbb',
        cursor: "pointer",

        display: 'flex',
        flexDirection: 'row',
    },
    characterSelect: {
        color: 'orange',
    }
}
