import React, {useEffect} from 'react';
import ToolTemplate from "../ToolTemplate/ToolTemplate";
import {useTextureUpdate} from "../../hooks";
import BackPackEditor from "../../jsonSchema/fields/BackPackEditor";
import {saveSkills, saveStats} from "../../DataRequester";
import {EntityTypes, TextureKeyTypes} from "../../WonEngine/Types";
import TextureSelector from "../../jsonSchema/fields/TextureSelector/TextureSelector";
import SkillSelector from "../../jsonSchema/fields/SkillSelector";
import ItemSelector from "../../jsonSchema/widgets/ItemSelector";
import CustomTypeSelector from "../../jsonSchema/widgets/CustomTypeSelector";
import ScriptEditor from "../../jsonSchema/widgets/ScriptEditor/ScriptEditor";
import IntlInput from "../../jsonSchema/widgets/IntlInput";
import OneOfSelector from "../../jsonSchema/widgets/OneOfSelector";
import ColorSelector from "../../jsonSchema/widgets/ColorSelector";
import ColorPalette from "../../jsonSchema/widgets/ColorPalette";

const DEFAULT_SCRIPT = "extends Node\\r\\n\\r\\nfunc handleOnHit():\\r\\n    pass";

const defaultFormData = {
    name: "",
    script: "",
    // script: DEFAULT_SCRIPT,
}

const StatTypes = ["NONE", "HIT",]

const widgets = {
    // SkillSelector
    ColorPalette,
    ColorSelector,
    ItemSelector,
    CustomTypeSelector,
    ScriptEditor,
    IntlInput,
    OneOfSelector,
}

const fields = {
    BackPackEditor,
    TextureSelector,
}

const dependencies = {
    "statType": {
        "oneOf": [
            {
                "properties": {
                    "statType": {
                        "enum": [
                            "NONE"
                        ],
                    },
                },
            },
            {
                "properties": {
                    "statType": {
                        "enum": [
                            "HIT"
                        ],
                    },
                    "hitType": {
                        "type": "string",
                    },
                    "hitColor": {
                        "type": "string",
                    }
                },
            },
        ],
    },
}

const itemSchema = {
    "type": "object",
    "properties": {
        "name": {
            "type": "string",
        },
        "value": {
            "type": "number",
        },
        "statType": {
            "type": "string",
            "enum": StatTypes,
            "default": StatTypes.NONE,
        },
        "script": {
            "type": "string",
        },
        "description": {
            "type": "string",
        },
    },
    dependencies
}

const uiSchema = {
    "ui:order": [
        "name",
        "description",
        "value",
        "statType",
        "hitType",
        "hitColor",
        "script",
        "*",
    ],

    "hitType": {
        "ui:widget": "CustomTypeSelector",
        "ui:options": {
            "items": [
                {
                    name: "Physical",
                    style: {
                        backgroundColor: "white",
                    }
                },
                {
                    name: "Fire",
                    style: {
                        backgroundColor: "crimson",
                    }
                },
                {
                    name: "Ice",
                    style: {
                        backgroundColor: "royalblue",
                    }
                },
                {
                    name: "Lightning",
                    style: {
                        backgroundColor: "gold",
                    }
                },
                {
                    name: "Dark",
                    style: {
                        backgroundColor: "#6a3771",
                    }
                },
            ],
        }
    },

    "statType": {
        "ui:widget": "OneOfSelector",

    },
    "script": {
        "ui:widget": "ScriptEditor",
    },

    "hitColor": {
        "ui:widget": "ColorPalette",
        "ui:options": {
            "useString": true,
            "label": false,
        },
    }
}

export default props => {
    const {items, setItems} = props;

    // useEffect(() => {
    //     setItems(items.map(item => {
    //         item.texture.textureName = "weapons";
    //         return item;
    //     }))
    // }, [])

    const handleClickSave = async () => {
        await saveStats({
            items,
        });
    }

    useTextureUpdate(items, setItems);

    return <ToolTemplate name={"statData"} items={items} setItems={setItems}
                         fields={fields} widgets={widgets}
                         itemSchema={itemSchema} uiSchema={uiSchema}
                         onClickSave={handleClickSave} defaultFormData={defaultFormData}
        // itemToolTemplate={ItemToolTemplate}
    />
}
