import {AutoTileTypes, FragmentTypeTable} from "../../Types";
import TileGrid from "../../Grid";
import GeneratedTile from "./GeneratedTile";

export default class GeneratedAutoTileView extends PIXI.Container {
    tileFragmentSelector = null;

    generatedTiles = [];
    sameFragmentMap = {};

    tileTable = [];

    constructor(texture, tileFragmentSelector) {
        super();
        // this.width = width;
        // this.height = height;
        // this.alpha = 0.5;

        this.tileFragmentSelector = tileFragmentSelector;

        this.x += 700;

        const generatedAutoTileSprite = new PIXI.Sprite(texture);
        // generatedAutoTileSprite.alpha = 0.5
        this.addChild(generatedAutoTileSprite)

        // this.addChild(generatedAutoTileView);
        //
        this.addChild(new TileGrid(16 * 8, 16 * 8, 8,
            graphics => graphics.lineStyle(0.25, 0xFFFFFF, 1)));
        this.addChild(new TileGrid(16 * 8, 16 * 8, 16,
            graphics => graphics.lineStyle(0.5, 0x000000, 1)));

        this.scale.set(6, 6);

        this.interactive = true;
        this.on('pointerdown', this.handlePointerDown.bind(this));

        this.generateAutoTiles();
        this.createSameFragmentMap();

        this.tileTable = [
            ...AutoTileTypes.AutoTileTable2,
        ];
        // for (let i = 0; i < 48; i++) {
        //     this.tileTable[i] = [];
        //     for (let j = 0; j < j; j++) {
        //         this.tileTable[i][j] = [];
        //     }
        // }
    }

    createSameFragmentMap() {
        const fragmentTypeTable = FragmentTypeTable;

        for (let i = 0; i < fragmentTypeTable.length; i++) {
            const fragmentData = fragmentTypeTable[i];
            for (let j = 0; j < fragmentData.length; j++) {
                const key = fragmentData[j];

                if (!this.sameFragmentMap[key]) {
                    this.sameFragmentMap[key] = [];
                }

                this.sameFragmentMap[key].push([i, j]);
            }
        }
    }

    replaceAllAutoTiles(coordX, coordY, selectedFragment) {
        const {fragmentType} = selectedFragment;
        if (!this.sameFragmentMap[fragmentType]) {
            return;
        }

        for (const sameFragment of this.sameFragmentMap[fragmentType]) {
            const [index, childIndex] = sameFragment;
            if (!this.generatedTiles[index]) continue;
            try {
                this.generatedTiles[index].children[childIndex].texture =
                    this.tileFragmentSelector.fragmentSprite.texture;

                this.tileTable[index][childIndex] = [this.tileFragmentSelector.selectedCoords.x, this.tileFragmentSelector.selectedCoords.y];

            } catch (e) {
                console.warn(`index : ${index} childIndex : ${childIndex} `);
            }
        }

        console.log(JSON.stringify(this.tileTable));
    }

    generateAutoTiles() {
        for (let y = 0; y < 6; y++) {
            for (let x = 0; x < 8; x++) {
                const generatedTile = new GeneratedTile(this, x, y);
                this.generatedTiles.push(generatedTile);
                this.addChild(generatedTile);
            }
        }
    }

    handlePointerDown() {
        // console.log(this.selectedFragmentCoords);
    }
}

