import React, {useEffect} from 'react';
import ToolTemplate from "../ToolTemplate/ToolTemplate";
import {useTextureUpdate} from "../../hooks";
import {saveItemData} from "../../DataRequester";
import TextureSelector from "../../jsonSchema/fields/TextureSelector/TextureSelector";
import RaritySelector from "../../jsonSchema/widgets/RaritySelector";
import AttackTypeSelector from "../../jsonSchema/widgets/AttackTypeSelector";
import ItemTypeSelector from "../../jsonSchema/widgets/ItemTypeSelector";
import ItemSelector from "../../jsonSchema/widgets/ItemSelector";
import OneOfSelector from "../../jsonSchema/widgets/OneOfSelector";
import GameItemSelector from "../../jsonSchema/fields/LootSelector";
import MaterialSelector from "../../jsonSchema/fields/MaterialSelector";

const defaultFormData = {
    itemType: "ITEM",
    materials: [],
}

const widgets = {
    AttackTypeSelector,
    RaritySelector,
    ItemTypeSelector,
    ItemSelector,
    // ItemDataSelector,
    OneOfSelector,
}

const fields = {
    TextureSelector,
    GameItemSelector,
    MaterialSelector,
}

export default props => {
    const {items, setItems} = props;

    // useEffect(() => {
    //     setItems(items.map(item => {
    //         item.texture.textureName = "weapons";
    //         return item;
    //     }))
    // }, [])

    const handleClickSave = async () => {
        await saveItemData({
            items,
        });
    }

    useTextureUpdate(items, setItems);

    return <ToolTemplate name={"TestTool"} items={items} setItems={setItems}
                         // fields={fields} widgets={widgets}
                         defaultFormData={defaultFormData}
                         itemSchema={{}} uiSchema={{}}
                         onClickSave={handleClickSave}
        // itemToolTemplate={ItemToolTemplate}
    />
}
