import Component from "./Component";
import {CONTAINER_SCALE, TILE_SIZE} from "../Types";
import {CHARACTER_WIDTH} from "../../containers/CharacterTool/config";

const FONT_SIZE = 24;

const defaultCharacterNameStyle = {
    fontSize: FONT_SIZE,
    fill: 0xFFFFFF,
    fontWeight: 'bold',
    stroke: '#000000',
    strokeThickness: 4,
    align: 'left'
}

export default class Text extends Component {
    nameText: PIXI.Text;

    constructor(text, type) {
        super();

        this.nameText = new PIXI.Text('', defaultCharacterNameStyle);
        this.nameText.scale.x /= CONTAINER_SCALE;
        this.nameText.scale.y /= CONTAINER_SCALE;
        this.nameText.text = text;
        this.nameText.style = {
            ...defaultCharacterNameStyle,
            fill: type === 0 ? 'skyblue' : 'Firebrick',
        }

        // this.nameText.x = CHARACTER_WIDTH * 0.5;
        this.nameText.anchor.set(0.5, 0.5);
        this.nameText.x += TILE_SIZE * 0.5;
        this.nameText.y = -8;
        this.nameText.visible = true;
    }

    init() {
        this.target.addChild(this.nameText);
    }

    release() {
        this.target.removeChild(this.nameText);
    }
}
