import React, { useEffect, useState } from 'react';

const parseStructuredContent = (rawContent) => {
    // 구조화된 데이터 파싱
    const channelRegex = /<\|channel\|>([^<]*)<\|message\|>([^<]*)<\|end\|>/g;
    const structured = {
        raw: rawContent,
        channels: {},
        displayText: ''
    };
    let match;
    
    while ((match = channelRegex.exec(rawContent)) !== null) {
        const [, channelName, message] = match;
        if (!structured.channels[channelName]) {
            structured.channels[channelName] = [];
        }
        structured.channels[channelName].push(message);
    }
    
    // 표시할 텍스트 결정
    if (structured.channels.final && structured.channels.final.length > 0) {
        structured.displayText = structured.channels.final.join('\n');
    } else if (Object.keys(structured.channels).length === 0) {
        // 구조화된 태그가 없으면 원본 텍스트를 표시
        structured.displayText = rawContent;
    } else {
        // 구조화된 채널은 있지만 final 채널이 없는 경우 원본 텍스트 표시
        structured.displayText = rawContent;
    }
    
    return structured;
};

const chat = async (inputText, modelId, messageHistory, onStream) => {
    // messageHistory에는 이미 현재 사용자 메시지가 포함되어 있음
    const newMessages = messageHistory;
    
    const result = await fetch("http://localhost:1234/api/v0/chat/completions", {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
        },
        body: JSON.stringify({
            model: modelId || "gemma-3-12b-it",
            messages: newMessages,
            "temperature": 0.7,
            "max_tokens": -1,
            "stream": true
        })
    });

    if (!result.ok) {
        console.error("HTTP 오류!", result.status);
        return null;
    }

    const decoder = new TextDecoder("utf-8");
    const reader = result.body.getReader();
    let textContent = "";
    let buffer = "";
    
    while (true) {
        const {value, done} = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, {stream: true});
        const lines = buffer.split("\n");
        buffer = lines.pop(); // 마지막 줄 덜 끝난 거 다시 버퍼에 보존

        for (const line of lines) {
            if (!line.trim().startsWith("data:")) continue;
            const jsonStr = line.replace("data: ", "").trim();
            if (jsonStr === "[DONE]") break;

            try {
                const data = JSON.parse(jsonStr);
                const delta = data.choices?.[0]?.delta;
                const finish = data.choices?.[0]?.finish_reason;

                if (finish === "stop") break;

                if (delta?.content) {
                    textContent += delta.content;
                    if (onStream) {
                        // 구조화된 컨텐츠 파싱하여 전달
                        const structured = parseStructuredContent(textContent);
                        onStream(structured);
                    }
                }
            } catch (e) {
                console.error("JSON 파싱 실패:", e, jsonStr);
            }
        }
    }
    
    // 최종 결과도 구조화하여 반환
    return parseStructuredContent(textContent);
};

export default function LLMTool() {
    const [models, setModels] = useState([]);
    const [selectedModel, selectModel] = useState("gemma-3-12b-it");
    const [inputText, setInputText] = useState("");
    const [responseText, setResponseText] = useState("");
    const [structuredData, setStructuredData] = useState(null);
    const [loading, setLoading] = useState(false);
    const [messages, setMessages] = useState([]);

    useEffect(() => {
        (async () => {
            const result = await fetch("http://localhost:1234/v1/models");
            if (!result.ok) {
                console.error("모델 목록 가져오기 실패", result.status);
                return;
            }

            const json = await result.json();
            setModels(json.data || []);
        })();
    }, []);

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!inputText.trim()) return;
        
        setLoading(true);
        setResponseText("");
        setStructuredData(null);
        
        // 사용자 메시지를 먼저 추가
        const userMessage = { role: "user", content: inputText };
        const updatedMessages = [...messages, userMessage];
        setMessages(updatedMessages);
        
        const result = await chat(inputText, selectedModel, updatedMessages, (structured) => {
            // 구조화된 데이터 저장
            setStructuredData(structured);
            // 화면에는 displayText만 표시
            setResponseText(structured.displayText);
        });
        
        if (result) {
            // 최종 결과도 구조화된 형태로 저장
            setStructuredData(result);
            setResponseText(result.displayText);
            
            // AI 응답을 메시지 히스토리에 추가
            const assistantMessage = { role: "assistant", content: result.displayText };
            setMessages([...updatedMessages, assistantMessage]);
            
            // 콘솔에 구조화된 JSON 출력
            console.log('Structured Response:', JSON.stringify(result, null, 2));
        }
        
        setLoading(false);
        setInputText(""); // 입력창 초기화
    };

    return (
        <div>
            <h2>LLMTool</h2>

            {/* 디버깅용 메시지 표시 */}
            <details style={{ 
                marginBottom: "20px", 
                padding: "10px", 
                backgroundColor: "#f0f0f0", 
                borderRadius: "4px",
                border: "1px solid #ddd"
            }}>
                <summary style={{ cursor: "pointer", fontWeight: "bold" }}>
                    디버그: Messages JSON (클릭하여 펼치기)
                </summary>
                <pre style={{ 
                    marginTop: "10px", 
                    padding: "10px", 
                    backgroundColor: "#fff", 
                    borderRadius: "4px",
                    overflow: "auto",
                    fontSize: "12px",
                    maxHeight: "300px"
                }}>
                    {JSON.stringify(messages, null, 2)}
                </pre>
            </details>

            <select onChange={e => selectModel(e.target.value)} value={selectedModel}>
                {models.map(model => (
                    <option key={model.id} value={model.id}>
                        {model.id}
                    </option>
                ))}
            </select>

            <div style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "10px", 
                marginTop: "20px",
                maxHeight: "400px",
                overflowY: "auto",
                backgroundColor: "#f5f5f5"
            }}>
                {messages.length === 0 ? (
                    <div style={{ color: "#999", textAlign: "center" }}>대화를 시작해보세요</div>
                ) : (
                    messages.map((msg, index) => (
                        <div key={index} style={{
                            marginBottom: "10px",
                            padding: "8px",
                            borderRadius: "6px",
                            backgroundColor: msg.role === "user" ? "#e3f2fd" : "#f0f0f0",
                            marginLeft: msg.role === "user" ? "auto" : "0",
                            marginRight: msg.role === "user" ? "0" : "auto",
                            maxWidth: "70%",
                            width: "fit-content"
                        }}>
                            <div style={{ 
                                fontWeight: "bold", 
                                marginBottom: "4px",
                                color: msg.role === "user" ? "#1976d2" : "#555"
                            }}>
                                {msg.role === "user" ? "사용자" : "AI"}
                            </div>
                            <div style={{ whiteSpace: "pre-wrap" }}>{msg.content}</div>
                        </div>
                    ))
                )}
                {loading && (
                    <div style={{
                        padding: "8px",
                        borderRadius: "6px",
                        backgroundColor: "#f0f0f0",
                        maxWidth: "70%",
                        marginBottom: "10px"
                    }}>
                        <div style={{ fontWeight: "bold", marginBottom: "4px", color: "#555" }}>AI</div>
                        <div style={{ whiteSpace: "pre-wrap" }}>
                            {responseText || "⏳ 생성 중..."}
                        </div>
                    </div>
                )}
            </div>

            <form onSubmit={handleSubmit} style={{ marginTop: "20px", display: "flex", gap: "10px" }}>
                <input
                    style={{ 
                        flex: 1,
                        padding: "10px",
                        borderRadius: "4px",
                        border: "1px solid #ccc"
                    }}
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    placeholder="메시지를 입력하세요..."
                    disabled={loading}
                />
                <button 
                    type="submit" 
                    disabled={loading}
                    style={{
                        padding: "10px 20px",
                        borderRadius: "4px",
                        backgroundColor: loading ? "#ccc" : "#1976d2",
                        color: "white",
                        border: "none",
                        cursor: loading ? "not-allowed" : "pointer"
                    }}
                >
                    {loading ? "전송 중..." : "보내기"}
                </button>
            </form>
        </div>
    );
}
