import Component from "./Component";
import WonEngine from "../index";
import {LayerTypes} from "../Types";

const historySize = 20;
const ropeSize = 100;

export default class Rope extends Component {
    points = [];
    historyX = [];
    historyY = [];
    rope = null;

    ropeTarget = null;

    constructor(x, y) {
        super();

        for (let i = 0; i < historySize; i++) {
            this.historyX.push(x);
            this.historyY.push(y);
        }
        for (let i = 0; i < ropeSize; i++) {
            this.points.push(new PIXI.Point(x, y));
        }

        const trailTexture = WonEngine.GetTexture('trail');
        // const trailTexture = PIXI.Texture.WHITE;

        this.rope = new PIXI.SimpleRope(trailTexture, this.points);
        // this.rope.blendmode = PIXI.BLEND_MODES.ADD;

    }

    setPosition(x, y) {
        for (let i = 0; i < historySize; i++) {
            this.historyX.push(x);
            this.historyY.push(y);
        }
        for (let i = 0; i < ropeSize; i++) {
            this.points.push(new PIXI.Point(x, y));
        }
    }

    init() {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const {layers, globalMousePosition} = mapToolRenderer

        layers[LayerTypes.MISSILE].addChild(this.rope);
    }

    update(x = undefined, y = undefined) {
        this.historyX.pop();
        this.historyX.unshift(x || this.target.x);
        this.historyY.pop();
        this.historyY.unshift(y || this.target.y);

        for (let i = 0; i < ropeSize; i++) {
            const p = this.points[i];
            const ix = cubicInterpolation(this.historyX, i / ropeSize * historySize);
            const iy = cubicInterpolation(this.historyY, i / ropeSize * historySize);
            p.x = ix;
            p.y = iy;
        }
    }

    release() {
        // this.target.removeChild(this.rope);
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const {layers} = mapToolRenderer;

        layers[LayerTypes.MISSILE].removeChild(this.rope);
    }
}

/**
 * Cubic interpolation based on https://github.com/osuushi/Smooth.js
 */
function clipInput(k, arr) {
    if (k < 0) k = 0;
    if (k > arr.length - 1) k = arr.length - 1;
    return arr[k];
}

function getTangent(k, factor, array) {
    return factor * (clipInput(k + 1, array) - clipInput(k - 1, array)) / 2;
}

function cubicInterpolation(array, t, tangentFactor = null) {
    if (tangentFactor == null) tangentFactor = 1;

    const k = Math.floor(t);
    const m = [getTangent(k, tangentFactor, array), getTangent(k + 1, tangentFactor, array)];
    const p = [clipInput(k, array), clipInput(k + 1, array)];
    t -= k;
    const t2 = t * t;
    const t3 = t * t2;
    return (2 * t3 - 3 * t2 + 1) * p[0] + (t3 - 2 * t2 + t) * m[0] + (-2 * t3 + 3 * t2) * p[1] + (t3 - t2) * m[1];
}
