export default (props) => {
    const {
        gameData, characters, items,
        selectedListType, setListType, mapEntities,
        unityContext,

        isUnityMounted, mountUnity
    } = props;

    const [initialized, setInitialized] = useState(false);
    const [selectedModeItem, setSelectModeItem] = useState(ActionTypes.EDIT);

    useEffect(() => {
        // updateTexture(mapEntities);
        setInitialized(true);
    }, [])


    return initialized && <div style={styles.mapTool}>
        <MapToolItems selectedListType={selectedListType} setListType={setListType}
                      gameData={gameData} characters={characters} items={items} mapEntities={mapEntities}
        />
        <div style={styles.engineView}>
            <TopToolBar selectedModeItem={selectedModeItem}
                        setSelectModeItem={setSelectModeItem}/>
            {/*<Unity*/}
            {/*    unityProvider={unityProvider}*/}
            {/*    style={{*/}
            {/*        // display: 'flex',*/}
            {/*        // height: "100%",*/}
            {/*        width: "100%",*/}
            {/*    }}*/}
            {/*/>*/}
            <EngineView renderType={RENDER_TYPE.MAP_TOOL} selectedModeItem={selectedModeItem}
                        unityContext={unityContext}
                        isUnityMounted={isUnityMounted}
                        mountUnity={mountUnity}
            >
                {/*{*/}
                {/*    (selectedModeItem === ActionTypes.PLAY ||*/}
                {/*        selectedModeItem === ActionTypes.MONITOR) &&*/}
                {/*    <WeaponSelector items={items}/>*/}
                {/*}*/}
            </EngineView>
        </div>
        {/*<Inspector/>*/}
    </div>
}

