import React, {useEffect, useState} from 'react';
import Select, {components} from 'react-select'
import WonEngine from "../../WonEngine";

const StopClickEvent = (e) => {
    e.stopPropagation();
}

const keyProperty = "name";

const toOptionItem = (itemData) => {
    return ({
        value: itemData[keyProperty],
        label: itemData.name,
    });
}

const toFormItem = (value) => {
    return {
        name: value,
        rate: 100,
        count: 1,
    };
};

const getItemData = key => WonEngine.GetInstance().items.find(item => item[keyProperty] === key);

const getLoots = (formData) => formData.map(formItem => {
    const loot = getItemData(formItem.name);
    if (!loot) {
        return null;
    }
    return toOptionItem(loot);
}).filter(loot => loot);

const getGameItems = () => WonEngine.GetInstance().items.map(item => toOptionItem(item));

const CustomOption = ({innerProps, isDisabled}) => {
    return !isDisabled ? (
        <div {...innerProps}>{/* your component internals */}</div>
    ) : null;
}
const Control = ({children, ...props}) => (
    <components.Control {...props}>
        {/*<div style={{*/}
        {/*    display: 'flex',*/}
        {/*    flexDirection: 'column'*/}
        {/*}}>{children}</div>*/}
        {children}
    </components.Control>
);


const MultiValueContainer = ({data, selectProps, children, ...props}) => {
    const containerProps = {
        ...props,
        data: {
            ...data,
            label: `${data.label}_1`,
        }
    };
    return (
        <components.MultiValueContainer{...containerProps} >
            {/*{children}*/}
            <div style={{
                display: 'flex',
                flex: 1,
            }}>
                {children[0]}
                <div style={{display: 'flex', width: '4em'}}>
                    <input type="number"/>
                    <div>%</div>
                </div>
                <div style={{display: 'flex', width: '4em'}}>
                    <input type="number"/>
                    <div>%</div>
                </div>
                {children[1]}
            </div>
        </components.MultiValueContainer>
    )
}


export default (props) => {
    const {
        name,
        formData = [],
        onChange
    } = props;
    const [gameItems, setGameItems] = useState([]);
    const [loots, setLoots] = useState([]);

    useEffect(() => {
        setGameItems(getGameItems());
    }, [])

    // Set loots
    useEffect(() => {
        // if (typeof formData == "object" && !Array.isArray(formData)) {
        // }
        setLoots(getLoots(formData));

    }, [formData]);

    const handleOnChange = (selectedOptions, actionMeta) => {
        const newFormData = selectedOptions.map(selectedOption => toFormItem(selectedOption.value));
        onChange(newFormData);
    };

    return <div style={styles.LootSelector}>
        <div className={"control-label"}>{name}</div>
        <Select style={styles.select}
            // components={{Option: CustomOption}}
                components={{
                    Control,
                    // MultiValueContainer
                }}
                isMulti options={gameItems} value={loots} onChange={handleOnChange}/>
    </div>
}


const styles = {
    select: {
        width: '3em',
    },
    lootItemWrapper: {
        display: 'flex',
    },
    lootItem: {
        margin: 0,
        padding: 0,
        width: '40px',
        height: '100%',
        boxSizing: 'border-box',
    },
    button: {
        padding: "1em",
    },
    LootSelector: {}
};
