import React from 'react';

const styles = {
    loadingMessageWrapper: {
        display: 'flex',
        width: '100%',
        height: '100%',
        alignItems: 'center',
        justifyContent: 'center',

        position:'absolute',
    },
    loadingMessage: {

        padding: '1em',
        position: "absolute",
        fontSize: '2em',
        fontWeight: 'bold',
        color: 'white',
        backgroundColor: '#363d4a',
        userSelect: 'none',
        pointerEvents: 'none',
    },

    gaugeWrapper: {
        boxSizing: 'border-box',
        marginTop: '0.5em',
        border: '3px solid #797e85',
        width: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        flexFlow: 'column',
    },

    gauge: {
        backgroundColor: '#797e85',
        height: '1em',
        alignSelf: 'flex-start',
    },

    label: {
        fontSize: '1em',
        position: 'absolute',
        alignSelf: 'center',
    }
};

export default (props) => {
    const {loadingProgression} = props;
    return <div style={styles.loadingMessageWrapper}>
        <div style={styles.loadingMessage}>
            Loading Unity WebGL Player.
            <div style={styles.gaugeWrapper}>
                <div style={Object.assign({}, styles.gauge, {
                    width: `${loadingProgression * 100}%`,
                })}>
                </div>
                <div style={styles.label}>
                    {Math.floor(loadingProgression * 100)}%
                </div>
            </div>
        </div>
    </div>
}
