import React from 'react';

export default (props) => {
    const {
        onClick = () => {
        }, style, src, selected = false
    } = props;
    return <img style={Object.assign({}, style, styles.default, selected && styles.selected)}
                onClick={onClick} src={src}/>
}

const styles = {
    default: {
        width: '32px',
        height: '32px',
        filter: 'drop-shadow(1px 1px 1px #000000)',
        // filter: 'invert(40%) drop-shadow(1px 1px 1px #000000)',
    },
    selected: {
        filter: `invert(51%) sepia(42%) saturate(3799%) hue-rotate(160deg) brightness(93%) contrast(101%) drop-shadow(1px 1px 1px #000000)`,
    }
}
