import React, {useState} from 'react';
import {SketchPicker} from 'react-color'

export default (props) => {
    const {value = "#FF0000", onChange} = props;
    // const [color, setColor] = useState("#FF0000");
    const [isShowingColorPicker, showColorPicker] = useState(false);
    // const handleChangeComplete = (color) => {
    //     this.setState({background: color.hex});
    // };

    const handleChangeComplete = (color) => {
        onChange(color.hex)
    }

    return <div style={{
        userSelect: "auto",
    }}>
        <div style={{
            backgroundColor: value,
            width: '100px',
            height: "50px",
            border: '3px solid black',
        }} onClick={() => showColorPicker(!isShowingColorPicker)}/>
        {/*Todo userSelect 버그 수정.*/}
        {
            isShowingColorPicker && <SketchPicker
                color={value}
                onChangeComplete={handleChangeComplete.bind(this)}
            />
        }
    </div>
}
