import WonEngine from "../../index";
import {
    CameraTargetTypes,
    CharState,
    CONTAINER_SCALE,
    EntityTypes, ItemTypes,
    MAX_TILE_HEIGHT,
    MAX_TILE_WIDTH,
    TILE_SIZE
} from "../../Types";
import Manager from "../Manager";
import {CHARACTER_WIDTH, CHARACTER_HEIGHT} from "../../../containers/CharacterTool/config";
import Character from "../../entities/Character";
import SpriteRenderer from "../../components/SpriteRenderer";
import {Key} from "../../stageRenderers/MapToolRenderer";
import Movement from "../../components/Movement";
import Weapon from "../../components/Weapon";
import Rope from "../../components/Rope";
import ObserverData from "../../components/ObserverData";

const OBSERVER_DATA = {
    "itemType": "CHARACTER",
    "name": "Observer",
    "type": 0,
    "base": 0,
    "head": 12,
    "face": 4,
    "eyes": 0,
    "body": 4,
    "hair": 0,
    "suit": 6,
    "item": 0,
    "index": 11
}

export default class CharacterMgr extends Manager {

    entities: Set<Character> = new Set();
    characterTextures: any = {};
    characterFrameTextures: any = {};


    observer: Character = null;

    movementPos = new PIXI.Point();
    cameraTarget = null;


    getTexture(textureId) {
        return new PIXI.Texture(this.characterTextures[textureId].texture,
            new PIXI.Rectangle(0, 0, CHARACTER_WIDTH, CHARACTER_HEIGHT));
    }

    getObserver() {
        if (!this.observer) {
            const observerData = new ObserverData();
            this.observer = this.add(OBSERVER_DATA, MAX_TILE_WIDTH * 0.5, MAX_TILE_HEIGHT * 0.5);
            this.observer.addComponent(observerData);
            this.observer.init();
        }
        return this.observer;
    }

    getHero() {
        for (const character of this.entities) {
            if (character.characterData.type === 0) {
                return character
            }
        }

        return null;
    }

    generateFrameTextures(resources) {
        const loader = PIXI.Loader.shared;

        for (const [key, resource] of Object.entries(resources)) {
            if (!this.characterFrameTextures[key]) {
                const baseTexture = loader.resources[key].texture;
                for (let i = 0; i < 4; i++) {

                    // @ts-ignore
                    this.characterFrameTextures[`${key}_idle_${i}`] = new PIXI.Texture(baseTexture,
                        new PIXI.Rectangle(i * 16, 24, 16, 24));
                    // @ts-ignore
                    this.characterFrameTextures[`${key}_run_${i}`] = new PIXI.Texture(baseTexture,
                        new PIXI.Rectangle(i * 16, 2 * 24, 16, 24));
                }
            }
        }
    }

    add(characterData, coordX, coordY) {
        const {entityMgr} = this.wonEngine.managers;
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const entity = entityMgr.getEntity(characterData.itemType, coordX, coordY);

        if (entity) return;

        // Todo Remove Character.
        if (characterData.index === 0) {
            return;
        }

        // const characterTexture = this.getTexture(characterData.textureId);
        const character = new Character(characterData, coordX, coordY);

        entityMgr.setEntity(characterData.itemType, character, coordX, coordY);

        return character;
    }

    remove(coordX, coordY) {
        const {entityMgr} = this.wonEngine.managers;

        entityMgr.removeEntity(EntityTypes.CHARACTER, coordX, coordY);
    }

    static GetCharacterDataURL(character) {
        return character.dataURL;
    }

    setTarget(targetType = undefined) {
        switch (targetType) {
            case CameraTargetTypes.HERO:
                this.cameraTarget = this.getHero();
                break;
            case CameraTargetTypes.OBSERVER:
                this.cameraTarget = this.getObserver();
                break;
            default:
                this.cameraTarget = null;
                break;
        }
    }

    keyFrame() {
        const {characterMgr} = WonEngine.GetInstance().managers;

        // if (!this.cameraTarget) {
        //     this.cameraTarget = characterMgr.getHero() || characterMgr.getObserver();
        // }

        const newKeySpeed = 1;
        const movement = this.movementPos;
        movement.set(0, 0);

        if (Key.isDown(Key.W)) {
            movement.y -= newKeySpeed;
        }
        if (Key.isDown(Key.S)) {
            movement.y += newKeySpeed;
        }
        if (Key.isDown(Key.A)) {
            movement.x -= newKeySpeed;
        }
        if (Key.isDown(Key.D)) {
            movement.x += newKeySpeed;
        }

        if (this.cameraTarget) {
            this.cameraTarget.state = CharState.STOP;
            this.cameraTarget.getComponent(Movement).move(movement);
        }
    }

    update() {
        const {hero} = this.wonEngine;

        const f = parseInt(String((Date.now() / 110))) % 4;

        // this.keyFrame();
        if (hero) {
            hero.update();
        }

        for (const entity of this.entities) {
            const sprite = entity.getComponent(SpriteRenderer).sprite;
            switch (entity.state) {
                case CharState.STOP:
                    sprite.texture = this.characterFrameTextures[`${entity.data.id}_idle_${f}`];
                    break;
                case CharState.IDLE:
                    sprite.texture = this.characterFrameTextures[`${entity.data.id}_idle_${f}`];
                    break;
                case CharState.RUN:
                    sprite.texture = this.characterFrameTextures[`${entity.data.id}_run_${f}`];
                    break;
            }

            // entity.update();
        }
    }
}
