// import {Layer} from "pixi-layers";
import {StageRenderer} from "../StageRenderer";
import WonEngine, {RENDER_TYPE} from "../index";
import {
    DrawTypes,
    fragTileSize,
    EntityTypes,
    TerrainTypes,
    CONTAINER_SCALE,
    ActionTypes,
    MAX_TILE_WIDTH, MAX_TILE_HEIGHT, MAP_TOOL_SCALE, TILE_SIZE, LayerTypes
} from "../Types";
import Entity from "../Entity";
import AutoTileRenderer from "./AutoTileRenderer/AutoTileRenderer";
import AutoTileGenerator from "./AutoTileRenderer/AutoTileGenerator";
import {EditAction} from "./userActions/EditAction";
import {PlayAction} from "./userActions/PlayAction";
import Rectangle from "../geom/Rectangle";
import TileMap from "../TileMap";
import ShadowFilter, {SHADOW_DIST} from "../filters/shadow";
import SpriteRenderer from "../components/SpriteRenderer";
import {OnlineAction} from "./userActions/OnlineAction";
import BlackFilter from "../filters/black";
import Grid from "../Grid";
import {SelectionHelper} from "../SelectionHelper";
// import {ItemTypes} from "app/res/database.js";
const keySpeed = 20;

export const DEFAULT_WHEEL_SCALE = 4;

export const Key = {
    _pressed: {},
    LEFT: 65,
    UP: 87,
    RIGHT: 68,
    DOWN: 83,
    SPACE: 32,
    SHIFT: 16,

    W: 87,
    S: 83,
    A: 65,
    D: 68,
    E: 69,

    isDown: function (keyCode) {
        return this._pressed[keyCode];
    },

    onKeydown: function (event) {
        this._pressed[event.keyCode] = true;
    },

    onKeyup: function (event) {
        this._pressed[event.keyCode] && delete this._pressed[event.keyCode];
    },
};


export default class MapToolRenderer extends StageRenderer {
    graphics: PIXI.Graphics = new PIXI.Graphics();
    container: PIXI.Container = new PIXI.Container();
    tileHover: PIXI.Sprite = new PIXI.Sprite(PIXI.Texture.WHITE);
    globalMousePosition: PIXI.Point = new PIXI.Point();

    tileMap: TileMap = new TileMap(
        TILE_SIZE * MAX_TILE_WIDTH,
        TILE_SIZE * MAX_TILE_HEIGHT);

    debugText: PIXI.Text = new PIXI.Text('', {
        fontSize: 18,
        fill: 0xFFFFFF,
        fontWeight: 'bold',
        stroke: '#000000',
        strokeThickness: 2,
        align: 'left'
    });

    SelectionHelper = new SelectionHelper();

    wheelValue = 4;
    lastFPSUpdateTime = 0;
    cachedFPS = 0;
    cachedFPSText = 'FPS : 0';

    selectedAction = ActionTypes.EDIT;
    selectionGraphic = new PIXI.Graphics();

    userActions: any = {
        [ActionTypes.EDIT]: new EditAction,
        [ActionTypes.PLAY]: new PlayAction,
        [ActionTypes.MONITOR]: new OnlineAction,
    };

    hero: Entity = null;
    selectedLayerName = 'ALL';

    filters = [
        new ShadowFilter(),
    ];

    public selectedItem: any = null;

    layers: { [key: string]: PIXI.Container } = {
        TILE: new PIXI.Container,
        OBJECT: new PIXI.Container,
        ITEM: new PIXI.Container,
        CHARACTER: new PIXI.Container,
        MISSILE: new PIXI.Container,
        SHADOW: new PIXI.Container,
        TOOL: new PIXI.Container,
        PIVOT: new PIXI.display.Layer(),
        SELECTION: new PIXI.display.Layer(),

    };
    drawType: string = DrawTypes.PEN;

    constructor() {
        super();
    }

    getEntitiesByLayer(layerType) {

    }

    exportAutoTileData() {
        const data = {
            keys: [],
            values: [],
        };
        return data;
    }

    selectLayer(selectedLayerType = null) {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const layers = mapToolRenderer.layers;

        let layerName = selectedLayerType || LayerTypes.ALL;

        if (selectedLayerType === LayerTypes.OLD) {
            layerName = this.selectedLayerName;
        }

        if (layerName === LayerTypes.ALL) {
            for (const [key, layer] of Object.entries(layers)) {
                layer['alpha'] = 1;
            }
            return;
        }

        for (const [key, layer] of Object.entries(layers)) {
            layer['alpha'] = 0.7;

            if (key === layerName) {
                layer['alpha'] = 1;
                this.selectedLayerName = layerName;
            }
        }

    }

    selectItem(itemData) {
        this.selectedItem = itemData;
        const {autoTileRenderer} = WonEngine.GetInstance().stageRenderers;

        if (AutoTileRenderer.IsAutoTile(itemData)) {
            const textureIndex = AutoTileRenderer.GetAutoTileMapIndex(itemData);
            autoTileRenderer.setRenderingBitTextures(textureIndex);
        }

        this.selectLayer(itemData.itemType);
    }

    onKeyDown(e) {
        Key.onKeydown(e);
    }

    onKeyUp(e) {
        Key.onKeyup(e);
    }

    _onWheel() {

    }

    setScale(value) {
        const newScaleValue = this.wheelValue + Math.sign(value * -1);

        if (newScaleValue <= DEFAULT_WHEEL_SCALE - 5 ||
            newScaleValue >= DEFAULT_WHEEL_SCALE + 5) {
            return;
        }

        this.wheelValue = newScaleValue;
        this.container.scale.set(newScaleValue, newScaleValue);

        this.filters[0].setShadowDist(newScaleValue * SHADOW_DIST);
        // this.layers['SHADOW'].filters[0].setShadowDist(newScaleValue * SHADOW_DIST);
    }

    onWheel(e) {
        this.setScale(e.deltaY);
    }

    onPointerDown(event) {
        this.userActions[this.selectedAction].onPointerDown &&
        this.userActions[this.selectedAction].onPointerDown(event);

        this.drawType === DrawTypes.SELECTION && this.SelectionHelper.handlePointerDown(event);
    }

    onPointerUp(event) {
        this.userActions[this.selectedAction].onPointerUp &&
        this.userActions[this.selectedAction].onPointerUp(event);

        this.drawType === DrawTypes.SELECTION && this.SelectionHelper.handlePointerUp(event);
    }

    onPointerMove(event) {
        this.userActions[this.selectedAction].onPointerMove &&
        this.userActions[this.selectedAction].onPointerMove(event);

        this.drawType === DrawTypes.SELECTION && this.SelectionHelper.handlePointerMove(event);
    }

    handlePointerMove(e) {
        this.globalMousePosition = e.data.global;
    }

    generateDefaultTiles(container) {
        const baseContainer = new PIXI.Container();
        const texture = WonEngine.GetTexture("overworld", new PIXI.Rectangle(0, 0, TILE_SIZE, TILE_SIZE));

        for (let y = 0; y < MAX_TILE_HEIGHT; y++) {
            for (let x = 0; x < MAX_TILE_WIDTH; x++) {
                const sprite = new PIXI.Sprite(texture);
                sprite.x = x * TILE_SIZE;
                sprite.y = y * TILE_SIZE;
                sprite.width = TILE_SIZE;
                sprite.height = TILE_SIZE;
                baseContainer.addChild(sprite);
            }
        }
        container.addChild(baseContainer);
    }

    _init() {
        const {renderer, autoTileGenerator} = WonEngine.GetInstance();
        // this._onKeyDown = this.onKeyDown.bind(this);
        // this._onKeyUp = this.onKeyUp.bind(this);
        this._onWheel = this.onWheel.bind(this);

        window.addEventListener('keydown', this.onKeyDown);
        window.addEventListener('keyup', this.onKeyUp);
        window.addEventListener('wheel', this._onWheel);

        // document.addEventListener('contextmenu', event => event.preventDefault());


        this.stage.interactive = true;
        this.stage.hitArea = new PIXI.Rectangle(0, 0,
            renderer.width,
            renderer.height,
        );

        this.stage.on('pointerdown', (e) => {
            // console.log('pointerdown');
            this.onPointerDown(e);
        });
        this.stage.on('pointerup', (e) => {
            // console.log('pointerup');
            this.onPointerUp(e);
        });
        this.stage.on('pointermove', (e) => {
            // console.log('pointermove');
            this.onPointerMove(e);
        });
        this.container.interactive = true;
        this.container.on('pointermove', this.handlePointerMove.bind(this));

        const viewElement = WonEngine.GetInstance().renderer.view;

        const lineSize = 5;


        // this.tileHover.visible = false;
        this.tileHover.tint = 0x0000FF;
        this.tileHover.width = TILE_SIZE;
        this.tileHover.height = TILE_SIZE;

        this.generateDefaultTiles(this.tileMap);

        for (let [key, layer] of Object.entries(this.layers)) {
            this.tileMap.addChild(layer);
        }

        // this.layers["PIVOT"].filterArea = new PIXI.Rectangle(-500, -500,
        //     renderer.width + 500,
        //     renderer.height + 500,
        // );
        // this.layers["PIVOT"].filters = [new BlackFilter()];


        this.layers['SHADOW'].filterArea = new PIXI.Rectangle(-500, -500,
            renderer.width + SHADOW_DIST + 500,
            renderer.height + SHADOW_DIST + 500,
        );
        this.layers['SHADOW'].filters = this.filters;

        this.container.addChild(this.tileMap);

        this.graphics.lineStyle(lineSize, 0x00FF00, 1);
        this.graphics.moveTo(0, 0);
        this.graphics.lineTo(1000, 0);

        this.graphics.lineStyle(lineSize, 0x00FF00, 1);
        this.graphics.moveTo(0, 0);
        this.graphics.lineTo(0, 1000);

        this.stage.addChild(this.graphics);
        this.stage.addChild(this.container);
        this.stage.addChild(this.debugText);

        this.selectionGraphic.visible = false;
        this.stage.addChild(this.selectionGraphic);

        const grid = new Grid(
            MAX_TILE_WIDTH * TILE_SIZE,
            MAX_TILE_HEIGHT * TILE_SIZE,
            TILE_SIZE * 10);
        this.container.addChild(grid);
        // this.layers["TOOL"].addChild(grid);

        const XYaxis = new PIXI.Graphics();

        XYaxis.lineStyle(5, 0x00FFFF, 1);
        XYaxis.moveTo(0, 0);
        XYaxis.lineTo(100, 0);
        XYaxis.moveTo(0, 0);
        XYaxis.lineTo(0, 100);

        this.container.pivot = new PIXI.Point(
            TILE_SIZE * MAX_TILE_WIDTH * 0.5,
            TILE_SIZE * MAX_TILE_HEIGHT * 0.5,
        );

        this.container.scale.set(4, 4);


        this.container.x = renderer.width * 0.5;
        this.container.y = renderer.height * 0.5;


        this.SelectionHelper.init(this.stage);
    }

    _load() {
        this.setScale(this.wheelValue);
        // this.filters[0].setShadowDist(newScaleValue * SHADOW_DIST);
    }

    keyFrame() {
        const newKeySpeed = keySpeed;
        if (Key.isDown(Key.W)) {
            this.container.y += newKeySpeed;
        }
        if (Key.isDown(Key.S)) {
            this.container.y -= newKeySpeed;
        }
        if (Key.isDown(Key.A)) {
            this.container.x += newKeySpeed;
        }
        if (Key.isDown(Key.D)) {
            this.container.x -= newKeySpeed;
        }
    }

    renderItem(tileCoordX, tileCoordY) {
        const wonEngine = WonEngine.GetInstance();
        const {itemMgr, entityMgr} = wonEngine.managers;

        if (this.selectedItem.index === 0) {
            entityMgr.removeEntity(this.selectedItem.itemType, tileCoordX, tileCoordY);
            return;
        }

        if (this.selectedItem.itemType === "ITEM") {
            itemMgr.add(this.selectedItem, tileCoordX, tileCoordY);
        } else {
            this.tileMap.paintTile(tileCoordX, tileCoordY);
        }
    }

    renderDebugText(globalMousePosition) {
        const {hero} = WonEngine.GetInstance();
        const {weaponMgr} = WonEngine.GetInstance().managers;
        const {mapToolRenderer, autoTileRenderer} = WonEngine.GetInstance().stageRenderers;
        const mousePosition = this.tileMap.toLocal(globalMousePosition);
        // const mousePosition = this.tileMapContainer.toLocal(globalMousePosition);
        const isDownedTileMapContainer = this.tileMap.isDownedTileMapContainer

        const tileCoordX = Math.floor(mousePosition.x / TILE_SIZE);
        const tileCoordY = Math.floor(mousePosition.y / TILE_SIZE);

        // 전체 디버그 텍스트 생성 (FPS 제외)
        let newText = this.cachedFPSText;
        newText += `\ntilePos : ${mousePosition.x} ${mousePosition.y}`;
        newText += `\nSelected drawType : ${this.drawType}`;
        newText += `\nCamera Pos : ${Math.floor(mapToolRenderer.container.x)} ${Math.floor(mapToolRenderer.container.y)}`;
        newText += `\nCoords : ${tileCoordX} ${tileCoordY}`;
        newText += `\nglobalMousePosition : ${globalMousePosition.x} ${globalMousePosition.y}`;
        newText += `\nradian : ${weaponMgr.radian}`;

        // newText += `\nCoords : ${this.coords.x} ${this.coords.y}`;
        // newText += `\nisDownedContainer : ${this.isDownedContainer} `;
        newText += `\nisDownedTileMapContainer : ${isDownedTileMapContainer}`;
        newText += `\nwheelValue : ${mapToolRenderer.wheelValue} `;
        newText += `\nuserAction : ${this.selectedAction} `;

        if (hero) {
            newText += `\nhero pos : ${hero.x} ${hero.y} `;
        }

        newText += `\ntile count : ${mapToolRenderer.layers[EntityTypes.TILE].children.length} `;
        newText += `\nobject count : ${mapToolRenderer.layers[EntityTypes.OBJECT].children.length} `;
        newText += `\ncharacter count : ${mapToolRenderer.layers[EntityTypes.CHARACTER].children.length} `;
        newText += `\nmissile count : ${mapToolRenderer.layers[EntityTypes.MISSILE].children.length} `;

        // 텍스트가 변경된 경우에만 업데이트
        if (this.debugText.text !== newText) {
            this.debugText.text = newText;
        }
    }

    selectDrawItem(selectedDrawItem) {
        this.drawType = selectedDrawItem;
    }

    clear() {
        const {entityMgr} = this.wonEngine.managers;

        for (const [layerName, layerContainer] of Object.entries(this.layers)) {
            entityMgr.entityMap[layerName] = {};
            layerContainer.removeChildren(0, layerContainer.children.length);
        }
    }

    paintItems(tileCoordX, tileCoordY) {
        const {entityMgr} = WonEngine.GetInstance().managers;

        const directions = [[0, -1], [-1, 0], [1, 0], [0, 1]];
        const coordBounds = new PIXI.Rectangle().copyFrom(this.tileMap.bounds);

        coordBounds.width = Math.floor(coordBounds.width / TILE_SIZE);
        coordBounds.height = Math.floor(coordBounds.height / TILE_SIZE);

        const visitedNodes = {};
        let timeCount = 0;
        let loop = 0;
        const paintNeighbors = (coordX, coordY) => {
            for (const direction of directions) {
                loop++;
                if (loop > 10000) {
                    console.log(`loop[${loop}] > 5000`);
                    return;
                }

                const newCoordX = coordX + direction[0];
                const newCoordY = coordY + direction[1];

                if (!coordBounds.contains(newCoordX, newCoordY)) {
                    continue;
                }

                if (!!visitedNodes[`${newCoordX}_${newCoordY}`]) {
                    continue;
                }

                let shouldExit = entityMgr.getEntity(this.selectedItem.itemType, newCoordX, newCoordY);

                if (this.selectedItem.index === 0) {
                    shouldExit = !shouldExit
                }

                if (shouldExit) {
                    visitedNodes[`${newCoordX}_${newCoordY}`] = true;
                    continue;
                }
                visitedNodes[`${newCoordX}_${newCoordY}`] = true;

                this.renderItem(newCoordX, newCoordY);
                paintNeighbors(newCoordX, newCoordY);
            }
        }

        return paintNeighbors(tileCoordX, tileCoordY);
    }

    render() {
        this.keyFrame();

        // FPS를 1초마다 갱신
        const currentTime = Date.now();
        if (currentTime - this.lastFPSUpdateTime >= 1000) {
            this.cachedFPS = Math.floor(PIXI.Ticker.shared.FPS);
            this.cachedFPSText = `FPS : ${this.cachedFPS}`;
            this.lastFPSUpdateTime = currentTime;
        }

        const userAction = this.userActions[this.selectedAction];

        if (!userAction.initialized) {
            userAction.init();
            userAction.initialized = true;
        }

        userAction.render();

        this.renderDebugText(this.globalMousePosition);
    }
}
