import {EntityTypes, ItemSubTypes, ItemTypes, TextureKeyTypes} from "../../WonEngine/Types";
import {textureSchema} from "../TileTool/TileToolSchemas";
import ItemSelector from "../../jsonSchema/widgets/ItemSelector";

export const defaultFormData = {
    rarity: 0,
    damage: 0,
    throwingDamage: 0,
    throwingRange: 0,
    description: "",
};

export const itemSchema = {
    "type": "object",
    "properties": {
        "name": {
            "type": "string"
        },
        "texture": {
            "type": "object",
            "properties": {
                "coords": {
                    "type": "array"
                },
                "size": {
                    "type": "array",
                },
                "affectCoordsList": {
                    "type": "array"
                },
            }
        },
        "description": {
            "type": "string",
        },
        "materials": {
            "type": "array",
        },
        "ItemCategory": {
            "type": "string"
        },
        "rarity": {
            "type": "number",
        },
        "attackType": {
            "type": "string"
        },
        "damage": {
            "type": "number",
        },
        "throwingDamage": {
            "type": "number",
        },
        "attackSpeed": {
            "type": "number",
        },
    },

    // "subType": {
    //     "type": "string",
    //     "enum": [
    //         ItemSubTypes.EQUIPMENT,
    //         ItemSubTypes.ITEM_BOX,
    //     ],
    //     "default": ItemSubTypes.EQUIPMENT,
    // },

    // "dependencies": {
    //     "subType": {
    //         "oneOf": [
    //             {
    //                 "properties": {
    //
    //                 },
    //             },
    //         ]
    //     },
    // },
};

export const uiSchema = {
    "ui:order": [
        "texture",
        "affectCoordsList",
        "name",
        "description",
        "subType",
        "*",
        "materials",
    ],
    "affectCoordsList": {
        "ui:field": "ItemEffectEditor",
        // "ui:options": {
        //     label: false,
        // }
    },
    "ItemCategory": {
        "ui:widget": "ItemSelector",
        "ui:options": {
            items: [
                {
                    name: "Equipment",
                },
                {
                    name: "Quest",
                },
                {
                    name: "Placement",
                },
            ],
        }
    },
    "materials": {
        "ui:field": "MaterialSelector",
    },
    "attackType": {
        "ui:widget": "AttackTypeSelector",
        "ui:options": {
            label: false,
        }
    },
    "rarity": {
        "ui:widget": "RaritySelector",
        "ui:options": {
            label: false,
        }
    },
    "texture": {
        "ui:field": "TextureSelector",
        "ui:options": {
            "textureKeyType": TextureKeyTypes.ITEM,
            "textureName": "weapons",
            "useTextureEffectEditor": false,
        }
    }
};
