import React, { useState, useEffect } from 'react';

const CHZZK_API_BASE = 'https://api.chzzk.naver.com';
const CHZZK_AUTH_BASE = 'https://chzzk.naver.com/account-interlock';

export default function Chzzk() {
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [tokens, setTokens] = useState({
        accessToken: null,
        refreshToken: null,
        expiresIn: null
    });
    const [clientConfig, setClientConfig] = useState({
        clientId: '',
        clientSecret: '',
        redirectUri: 'http://localhost:3000/chzzk/callback'
    });

    useEffect(() => {
        // 저장된 토큰 확인
        const savedTokens = localStorage.getItem('chzzk_tokens');
        if (savedTokens) {
            const parsedTokens = JSON.parse(savedTokens);
            setTokens(parsedTokens);
            setIsAuthenticated(true);
        }

        // URL에서 인증 코드 확인 (콜백 처리)
        const urlParams = new URLSearchParams(window.location.search);
        const code = urlParams.get('code');
        const state = urlParams.get('state');
        
        if (code && state) {
            handleAuthCallback(code, state);
        }
    }, []);

    const generateState = () => {
        return Math.random().toString(36).substring(2, 15) + 
               Math.random().toString(36).substring(2, 15);
    };

    const initiateAuth = () => {
        if (!clientConfig.clientId) {
            alert('Client ID를 입력해주세요.');
            return;
        }

        const state = generateState();
        localStorage.setItem('chzzk_auth_state', state);

        const authUrl = new URL(CHZZK_AUTH_BASE);
        authUrl.searchParams.append('clientId', clientConfig.clientId);
        authUrl.searchParams.append('redirectUri', clientConfig.redirectUri);
        authUrl.searchParams.append('state', state);

        window.location.href = authUrl.toString();
    };

    const handleAuthCallback = async (code, state) => {
        const savedState = localStorage.getItem('chzzk_auth_state');
        
        if (state !== savedState) {
            alert('State 값이 일치하지 않습니다.');
            return;
        }

        try {
            const response = await fetch(`${CHZZK_API_BASE}/auth/v1/token`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    grantType: 'authorization_code',
                    clientId: clientConfig.clientId,
                    clientSecret: clientConfig.clientSecret,
                    code: code,
                    state: state
                })
            });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            const tokenData = await response.json();
            
            setTokens({
                accessToken: tokenData.accessToken,
                refreshToken: tokenData.refreshToken,
                expiresIn: tokenData.expiresIn
            });
            
            localStorage.setItem('chzzk_tokens', JSON.stringify(tokenData));
            localStorage.removeItem('chzzk_auth_state');
            setIsAuthenticated(true);

            // URL에서 code, state 파라미터 제거
            window.history.replaceState({}, document.title, window.location.pathname);
            
        } catch (error) {
            console.error('토큰 발급 실패:', error);
            alert('토큰 발급에 실패했습니다.');
        }
    };

    const refreshToken = async () => {
        if (!tokens.refreshToken) {
            alert('Refresh Token이 없습니다.');
            return;
        }

        try {
            const response = await fetch(`${CHZZK_API_BASE}/auth/v1/token`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    grantType: 'refresh_token',
                    refreshToken: tokens.refreshToken,
                    clientId: clientConfig.clientId,
                    clientSecret: clientConfig.clientSecret
                })
            });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            const tokenData = await response.json();
            
            setTokens({
                accessToken: tokenData.accessToken,
                refreshToken: tokenData.refreshToken,
                expiresIn: tokenData.expiresIn
            });
            
            localStorage.setItem('chzzk_tokens', JSON.stringify(tokenData));
            
        } catch (error) {
            console.error('토큰 갱신 실패:', error);
            alert('토큰 갱신에 실패했습니다.');
        }
    };

    const revokeToken = async () => {
        try {
            const response = await fetch(`${CHZZK_API_BASE}/auth/v1/token/revoke`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    clientId: clientConfig.clientId,
                    clientSecret: clientConfig.clientSecret,
                    token: tokens.accessToken,
                    tokenTypeHint: 'access_token'
                })
            });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            // 로컬 상태 초기화
            setTokens({
                accessToken: null,
                refreshToken: null,
                expiresIn: null
            });
            localStorage.removeItem('chzzk_tokens');
            setIsAuthenticated(false);
            
        } catch (error) {
            console.error('토큰 삭제 실패:', error);
            alert('토큰 삭제에 실패했습니다.');
        }
    };

    return (
        <div style={{ padding: '20px', maxWidth: '600px' }}>
            <h2>치지직 OAuth 인증</h2>
            
            {/* 클라이언트 설정 */}
            <div style={{ marginBottom: '20px', padding: '15px', border: '1px solid #ddd', borderRadius: '5px' }}>
                <h3>클라이언트 설정</h3>
                <div style={{ marginBottom: '10px' }}>
                    <label style={{ display: 'block', marginBottom: '5px' }}>Client ID:</label>
                    <input
                        type="text"
                        value={clientConfig.clientId}
                        onChange={(e) => setClientConfig({...clientConfig, clientId: e.target.value})}
                        style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
                        placeholder="fefb6bbb-00c2-497c-afc2-XXXXXXXXXXXX"
                    />
                </div>
                <div style={{ marginBottom: '10px' }}>
                    <label style={{ display: 'block', marginBottom: '5px' }}>Client Secret:</label>
                    <input
                        type="password"
                        value={clientConfig.clientSecret}
                        onChange={(e) => setClientConfig({...clientConfig, clientSecret: e.target.value})}
                        style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
                        placeholder="VeIMuc9XGle7PSxIVYNwPpI2OEk_9gXoW_XXXXXXXXX"
                    />
                </div>
                <div style={{ marginBottom: '10px' }}>
                    <label style={{ display: 'block', marginBottom: '5px' }}>Redirect URI:</label>
                    <input
                        type="text"
                        value={clientConfig.redirectUri}
                        onChange={(e) => setClientConfig({...clientConfig, redirectUri: e.target.value})}
                        style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
                    />
                </div>
            </div>

            {/* 인증 상태 */}
            <div style={{ marginBottom: '20px', padding: '15px', border: '1px solid #ddd', borderRadius: '5px' }}>
                <h3>인증 상태</h3>
                <p>상태: {isAuthenticated ? '✅ 인증됨' : '❌ 미인증'}</p>
                
                {tokens.accessToken && (
                    <div>
                        <p><strong>Access Token:</strong> {tokens.accessToken.substring(0, 20)}...</p>
                        <p><strong>Expires In:</strong> {tokens.expiresIn}초</p>
                    </div>
                )}
            </div>

            {/* 액션 버튼들 */}
            <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                {!isAuthenticated ? (
                    <button
                        onClick={initiateAuth}
                        style={{
                            padding: '10px 20px',
                            backgroundColor: '#00C73C',
                            color: 'white',
                            border: 'none',
                            borderRadius: '4px',
                            cursor: 'pointer'
                        }}
                    >
                        치지직 로그인
                    </button>
                ) : (
                    <>
                        <button
                            onClick={refreshToken}
                            style={{
                                padding: '10px 20px',
                                backgroundColor: '#007bff',
                                color: 'white',
                                border: 'none',
                                borderRadius: '4px',
                                cursor: 'pointer'
                            }}
                        >
                            토큰 갱신
                        </button>
                        <button
                            onClick={revokeToken}
                            style={{
                                padding: '10px 20px',
                                backgroundColor: '#dc3545',
                                color: 'white',
                                border: 'none',
                                borderRadius: '4px',
                                cursor: 'pointer'
                            }}
                        >
                            로그아웃
                        </button>
                    </>
                )}
            </div>

            {/* 개발자 정보 */}
            <div style={{ marginTop: '30px', padding: '15px', backgroundColor: '#f8f9fa', borderRadius: '5px' }}>
                <h4>사용법</h4>
                <ol>
                    <li>치지직 개발자 센터에서 애플리케이션을 등록하고 Client ID와 Client Secret을 발급받으세요.</li>
                    <li>위의 설정 영역에 Client ID와 Client Secret을 입력하세요.</li>
                    <li>Redirect URI가 애플리케이션 등록 시 설정한 URL과 일치하는지 확인하세요.</li>
                    <li>"치지직 로그인" 버튼을 클릭하여 인증을 시작하세요.</li>
                    <li>인증 완료 후 토큰 갱신 및 로그아웃 기능을 사용할 수 있습니다.</li>
                </ol>
            </div>
        </div>
    );
}
