import React, {useEffect, useState} from 'react';
import WonEngine from "../../WonEngine";
import {TextureKeyTypes} from "../../WonEngine/Types";
import {Rarities} from "../../jsonSchema/widgets/RaritySelector";

const DEFAULT_CATEGORY = "Default";

export const getToolItemTexture = (itemData) => {
    // const wonEngine = WonEngine.GetInstance();
    // const {textureMgr} = wonEngine.managers;
    // const texture = textureMgr.getByTextureInfo(itemData.texture);
    // return wonEngine.extractToBase64(texture);

    try {
        const wonEngine = WonEngine.GetInstance();
        const {textureMgr} = wonEngine.managers;
        const texture = textureMgr.getByTextureInfo(itemData.texture);

        // console.log(itemData.texture)
        return wonEngine.extractToBase64(texture, itemData.texture);
    } catch (e) {
        return null;
    }
}

export default (props) => {
    const {
        name,
        items, selectedItemKey, setSelectedItemKey,
        filteredItems, onClickSelectItem, setFilteredItems
    } = props;

    const [filteringItem, setFilteringItem] = useState("");

    const [categoryDataMap, setCategoryDataMap] = useState({});
    const [isLoaded, setLoad] = useState(false);

    // Todo filteredItems가 바꼇을때 깜박임 제거.
    useEffect(() => {
        if (!isLoaded && Object.keys(filteredItems).length > 0) {
            const newCategoryDataMap = {};
            Object.entries(filteredItems).forEach(([categoryKey, value]) => {
                newCategoryDataMap[categoryKey] = true;
            });
            setCategoryDataMap(newCategoryDataMap);
            setLoad(true);
        }

    }, [filteredItems, isLoaded])

    const getTotalItemCount = () => {
        let totalCount = 0;
        Object.keys(filteredItems).map(key => totalCount += filteredItems[key].length);
        return totalCount
    }
    const handleClickCategoryData = (categoryKey) => {

        setCategoryDataMap({
            ...categoryDataMap,
            [categoryKey]: !categoryDataMap[categoryKey]
        });
    }

    const handleFilteringItemChange = (e) => {
        setFilteringItem(e.target.value);
    };

    const renderFilteredItems = (categoryKey, items) => {
        if (!categoryDataMap[categoryKey]) return null;

        const newItems = items.map(([itemIndex, itemData], index) => {

            var a = 0;

            // Todo 임시방편 input에서 text가 없을떄 undefined가 나오는 문제 해결.
            if (!(itemData.name || "").includes(filteringItem)) return;

            // if (filteringItem.length > 0) {
            //     // 대소문자 무시.
            //     if (itemData.name.toLowerCase().includes(filteringItem.toLowerCase())) return
            // }

            const key = itemData.id;
            const itemTexture = getToolItemTexture(itemData);
            const selected = (selectedItemKey === key);
            const rarityData = Rarities[itemData.rarity];
            let itemName = itemData.name;

            if (name === "cardTool") {
                itemName = `${itemData.name} [${itemData.cost}]`;
            }

            return <div key={key} style={Object.assign({},
                styles.listItem, selected && styles.selectedItem,
                rarityData && {
                    backgroundColor: rarityData.color,
                })}
                        onClick={onClickSelectItem.bind(this, key)}>
                {itemTexture && <div style={styles.itemTextureWrapper}>
                    <img style={Object.assign({}, styles.itemTexture, styles.itemImage)}
                         src={itemTexture}/>
                </div>}
                <div style={styles.name}>{itemName}</div>
            </div>
        })

        return newItems;
    }

    return <div style={styles.itemListView}>
        <div style={{
            position: 'relative',
            display: 'flex',
            // flex: 1,
            // width: '100%',
            // height: '100%',
        }}>
            <input style={{
                width: '100%',
                height: '3em',
                boxSizing: 'border-box',
            }} type="text" value={filteringItem} onChange={handleFilteringItemChange.bind(this)}
                   placeholder={"Search..."}/>
        </div>
        <div style={Object.assign({}, styles.categoryKey, {
            borderBottom: '1px dotted black',
        })}>
            {`Total Count : ${getTotalItemCount()} `}
            <div onClick={() => {
                // const newCategoryDataMap = categoryDataMap.map((item, index) => true)

                // setCategoryDataMap(newCategoryDataMap);
            }}>[+]
            </div>
            <div onClick={() => {
                // const newCategoryDataMap = categoryDataMap.map((item, index) => false)

                // setCategoryDataMap(newCategoryDataMap);
            }}>[-]
            </div>
        </div>
        <div style={styles.itemListWrapper}>
            {
                Object.entries(filteredItems).map(([categoryKey, value]) => <div key={categoryKey}>
                    <div style={styles.categoryKey} onClick={handleClickCategoryData.bind(this, categoryKey)}>
                        <div>{categoryKey}</div>
                        <div style={{
                            marginLeft: '0.5em',
                            cursor: 'pointer',
                        }}>{
                            categoryDataMap[categoryKey] ? '[-]' : '[+]'
                        }
                        </div>
                    </div>
                    {renderFilteredItems(categoryKey, value)}
                </div>)

            }
        </div>
    </div>
}

const styles = {
    itemImage: {
        backgroundColor: 'white',
        objectFit: 'fill',
        width: '100%',
        height: '100%',
    },
    categoryKey: {
        cursor: 'pointer',
        display: 'flex',
        alignItems: 'center',
        paddingLeft: '0.5em',

        backgroundColor: 'lightGray',
        textShadow: '2px 2px 2px white',
        fontWeight: 'bold',
    },
    itemTextureWrapper: {
        border: '2px solid black',
        width: '36px',
        height: '36px',
        // display: 'flex',
        // alignItems: 'center',
        // justifyContent: "center",
    },
    itemTexture: {
        // flex: 1,
        imageRendering: 'pixelated',
    },
    name: {
        display: 'flex',
        alignItems: 'center',
        marginLeft: '0.5em',
    },
    itemListView: {
        position: 'relative',

        display: 'flex',
        flexDirection: 'column',

        boxSizing: 'border-box',
        // border: '5px solid green',
        userSelect: "none",
        width: '250px',
        // height : ''
        // flex: '1',
        height: '900px',
        // height: '100%',

    },
    itemListWrapper: {
        flexDirection: 'column',
        backgroundColor: 'lightgray',
        // backgroundColor: 'skyblue',
        // border: '5px solid yellow',

        overflow: 'scroll',
        overflowX: 'hidden',
        // height: '750px',
        // position: 'relative',
        // height: '100%',
        display: "flex",
        flex: "1",
    },
    listItem: {
        backgroundColor: 'white',
        margin: '0.2em',
        padding: '0.2em',
        border: '1px solid #bbb',
        fontWeight: 'bold',
        textShadow: '2px 2px 2px #bbb',
        cursor: "pointer",
        display: 'flex',
    },
    selectedItem: {
        color: ' orange',
    }
}
