import React, {useState, useEffect} from 'react';
import Editor from "../components/Editor";
import EngineView from "../components/EngineView";
import WonEngine, {RENDER_TYPE} from "../WonEngine";
// const autoTileLength = new Array(autoTileBase.length).fill({});

const fontStyle = {
    fontSize: '1.5em',
    fontWeight: 'bold',
    textShadow: '2px 2px 2px white',
};

export default () => {
    const [selectedItemIndex, setSelectItem] = useState(0);

    useEffect(() => {
        const {autoTileGenerator} = WonEngine.GetInstance();

        autoTileGenerator.selectAutoTile(0);
    }, [])

    const handleClickAutoTile = (index) => {
        const {autoTileGenerator} = WonEngine.GetInstance();

        setSelectItem(index);
        autoTileGenerator.selectAutoTile(index);
    }

    return <div style={styles.autoTileEditor}>
        <div style={{
            backgroundColor: 'lightgray',
        }}>
            {/*{*/}
            {/*    autoTileBase.map((autoTile, index) => {*/}
            {/*        const itemKey = `autoTile ${index}`;*/}
            {/*        return <div key={itemKey} style={{*/}
            {/*            ...fontStyle,*/}
            {/*            color: index === selectedItemIndex ? 'orange' : 'black',*/}
            {/*            cursor: 'pointer',*/}
            {/*            margin: '0.3em',*/}
            {/*        }} onClick={handleClickAutoTile.bind(this, index)}>{autoTile.textureName}</div>*/}
            {/*    })*/}
            {/*}*/}
        </div>
        <div style={{
            width: '100%',
            display: 'flex',
            flexDirection: 'column',
        }}>
            <Editor/>
            <EngineView
                // selectedItem={autoTileBase[selectedItemIndex]}
                renderType={RENDER_TYPE.AUTO_TILE_TOOL}
                selectedModeItem="EDIT"
            />
        </div>

    </div>
}

const styles = {
    autoTileEditor: {
        display: 'flex',
        height: '100%',
        userSelect: 'none',
    }
}
