import React, {useEffect, useState} from 'react';

import AutoTileEditor from "./AutoTileEditor";
import MapTool from "./MapTool/MapTool";
import EffectTool from "./EffectTool";
import CharacterTool from "./CharacterTool/CharacterTool";
import WonEngine from "../WonEngine";
import {updateCharacterTextures, updateTexture, useEngineInit} from "../hooks";
import {productionMode} from "../config";
import ItemTool from "./ItemTool/ItemTool";
import {GetGameDatabase, loadAutoTileData, loadCharacters, loadDatabase, loadItemData, loadTileData} from "../DataRequester";
import CanvasRenderer from "./CharacterTool/CanvasRenderer";
import Cookies from 'js-cookie'
import TileTool from "./TileTool/TileTool";
import PhysicTool from "./PhysicTool/PhysicTool";
import TopMenu from "../components/TopMenu";
import {ToastContainer, toast} from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import TestTool from "./TestTool/TestTool";

import PlayGround from "./PlayGround";
import {Unity, UnityContext, useUnityContext} from "react-unity-webgl";
import CardTool from "./CardTool/CardTool";
import PlayerDataTool from "./PlayerDataTool/PlayerDataTool";
import SkillTool from "./SkillTool/SkillTool";
import StatTool from "./StatTool/StatTool";
import LoadingMessage from "../components/LoadingMessage";
import ResourceTool from "./ResourceTool/ResourceTool";
import FantasyDuel from "./FantasyDuel/FantasyDuel";
import LLMTool from "./LLMTool/LLMTool";
import Chzzk from "./Chzzk/Chzzk";
import Claude from "./Claude/Claude";


const menuItems = {
    MapTool: 'MapTool',
    ItemTool: 'ItemTool',
    TileTool: 'TileTool',
    CardTool: 'CardTool',
    PlayerDataTool: 'PlayerDataTool',
    SkillTool: 'SkillTool',
    StatTool: 'StatTool',
    ResourceTool: 'ResourceTool',
    FantasyDuel: 'FantasyDuel',

    Claude : 'Claude',
    TestTool: 'TestTool',
    CharacterTool: 'CharacterTool',
    PhysicTool: 'PhysicTool',
    EffectTool: 'EffectTool',
    AutoTileTool: "AutoTileTool",
    PlayGround: "PlayGround",
    LLMTool: "LLMTool",
    Chzzk: "Chzzk",

};

const generateCharacterState = (characters) => characters.map(character => ({
    ...character,
    // textureId: character.textureId || null,
    dataURL: character.dataURL || null,
}));

export default () => {
    const [database, setDatabase] = useState(null);
    const [currentMenuItem, setCurrentMenuItem] = useState(menuItems.MapTool);

    const [characters, setCharacters] = useState([]);
    const [mapEntities, setMapEntities] = useState([]);
    const [items, setItems] = useState([]);
    const [cards, setCards] = useState([]);
    const [playerDataList, setPlayerDataList] = useState([]);
    const [skills, setSkills] = useState([]);
    const [stats, setStats] = useState([]);

    const [isLoaded, setLoaded] = useState(false);
    const [selectedListType, setListType] = useState(1);
    const wonEngine = WonEngine.GetInstance();

    const [isUnityMounted, mountUnity] = useState(false);
    const unityContext = useUnityContext({
        dataUrl: "webglBuild/Build/webglBuild.data",
        frameworkUrl: "webglBuild/Build/webglBuild.framework.js",
        loaderUrl: "webglBuild/Build/webglBuild.loader.js",
        codeUrl: "webglBuild/Build/webglBuild.wasm",

        streamingAssetsUrl: "webglBuild/StreamingAssets",
        companyName: "DefaultCompany",
        productName: "FantasyWorld",
        productVersion: "1.0",
        // cacheControl: handleCacheControl,
    });


    useEffect(() => {
        if (currentMenuItem === menuItems.MapTool) {
        }
    }, [currentMenuItem]);

    useEffect(() => {
        (async () => {
            const showToast = false;

            const {
                autoTileData,
                database,
                characters,
                items,
                mapEntities,
                cards,
                playerDataList,
                skills,
                stats
            } = await GetGameDatabase(showToast);

            if (!wonEngine) {
                const wonEngine = new WonEngine();
                await wonEngine.loadResources();

                const canvasRenderer = new CanvasRenderer();
                await canvasRenderer.init();

                canvasRenderer.run();

                // generate character texture.
                const updatedCharacters = await updateCharacterTextures(characters)

                wonEngine.init({
                    width: document.documentElement.clientWidth,
                    height: document.documentElement.clientHeight,
                    autoTileData,
                    database,

                    tiles: mapEntities.filter(item => item.itemType === "TILE"),
                    objects: mapEntities.filter(item => item.itemType === "OBJECT"),
                    items,
                    characters: updatedCharacters,
                    cards,
                    skills,
                    stats
                });
                wonEngine.render();

                setDatabase(database);
                setCharacters(generateCharacterState(updatedCharacters));
                setItems(items);
                setMapEntities(mapEntities);
                setCards(cards);
                setPlayerDataList(playerDataList)
                setSkills(skills)
                setStats(stats)

                updateTexture(mapEntities);

                const mergedItems = [
                    ...updatedCharacters,
                    ...items,
                    ...mapEntities
                ];

                wonEngine.addUUID(mergedItems);

                // set cookie;
                const cookies = Cookies.get();
                if (cookies['currentMenuItem']) {
                    setCurrentMenuItem(cookies['currentMenuItem']);
                }
                if (cookies['selectedListType']) {
                    setListType(Number(cookies['selectedListType']));
                }

                if (!isLoaded) {
                    wonEngine.loadData();
                }

                setLoaded(true);
            }
        })()
    }, [])

    useEffect(() => {
        if (!wonEngine) return;

        (async () => {
            const newCharacters = await updateCharacterTextures(characters);
            if (newCharacters) {
                setCharacters(newCharacters);
            }
        })()
    }, [wonEngine, characters])

    const updateData = (property, value) => {
        if (!wonEngine) return;
        wonEngine[property] = value;
    };

    useEffect(() => {
        updateData('characters', characters);
        updateData('items', items);
        updateData('cards', cards);
        updateData('skills', skills);
        updateData('stats', stats);
    }, [characters, items, cards, skills, stats]);

    useEffect(() => {
        if (!wonEngine) return;
        wonEngine.tiles = mapEntities.filter(item => item.itemType === "TILE");
        wonEngine.objects = mapEntities.filter(item => item.itemType === "OBJECT");
    }, [mapEntities])

    if (!isLoaded) {
        return <div style={styles.loadingWrapper}>
            {
                productionMode && <span>[production build]</span>
            }
            <div>Loading database...</div>
        </div>;
    }


    const components = {
        [menuItems.MapTool]: <MapTool key={menuItems.MapTool}
                                      selectedListType={selectedListType} setListType={setListType}
                                      gameData={database.gameData}
                                      characters={characters}
                                      items={items} mapEntities={mapEntities}
                                      unityContext={unityContext}
                                      isUnityMounted={isUnityMounted}
                                      mountUnity={mountUnity}
        />,
        [menuItems.TileTool]: <TileTool key={menuItems.TileTool} database={database}
                                        items={mapEntities} setItems={setMapEntities}
        />,
        [menuItems.ItemTool]: <ItemTool key={menuItems.ItemTool}
                                        items={items} setItems={setItems}/>,
        [menuItems.CharacterTool]: <CharacterTool key={menuItems.CharacterTool}
                                                  characters={characters} setCharacters={setCharacters}/>,
        [menuItems.StatTool]: <StatTool key={menuItems.StatTool}
                                        items={stats} setItems={setStats}
        />,
        [menuItems.CardTool]: <CardTool key={menuItems.ItemTool}
                                        items={cards} setItems={setCards}/>,
        [menuItems.SkillTool]: <SkillTool key={menuItems.SkillTool}
                                          items={skills} setItems={setSkills}
        />,
        [menuItems.PlayerDataTool]: <PlayerDataTool key={menuItems.PlayerDataTool}
                                                    items={playerDataList} setItems={setPlayerDataList}
        />,
        // [menuItems.LLMTool]: <LLMTool key={menuItems.LLMTool}
        //                                  items={playerDataList} setItems={setPlayerDataList}
        // />,

        [menuItems.AutoTileTool]: <AutoTileEditor key={menuItems.AutoTileTool}
                                      // items={playerDataList} setItems={setPlayerDataList}
        />,
        // [menuItems.Claude]: <Claude key={menuItems.Claude}
        //     // items={playerDataList} setItems={setPlayerDataList}
        // />,
        //
        // [menuItems.Chzzk]: <Chzzk key={menuItems.LLMTool}
        //                               // items={playerDataList} setItems={setPlayerDataList}
        // />,





        // [menuItems.ResourceTool]: <ResourceTool key={menuItems.ResourceTool}
        // />,
        // [menuItems.FantasyDuel]: <FantasyDuel key={menuItems.FantasyDuel}
        // />,
    };

    let isUnityPlayerLoading = isUnityMounted && unityContext.loadingProgression !== 1;

    // let isUnityPlayerLoading = true
    const loadingProgression = unityContext.loadingProgression;
    // const loadingProgression = 0.5;

    // return <div style={{
    //     height : '100vh',
    //     border: '5px solid blue',
    //     boxSizing: 'border-box',
    // }}>
    //
    // </div>

    return <div style={styles.app}>
        <TopMenu components={components}
                 currentMenuItem={currentMenuItem}
                 setCurrentMenuItem={setCurrentMenuItem}
                 unityContext={unityContext}
                 isUnityMounted={isUnityMounted}
                 mountUnity={mountUnity}
        />
        <div style={isUnityPlayerLoading ? {
            ...styles.toolWrapper,
            ...styles.disabledUserAction
        } : styles.toolWrapper}>

            {
                components[currentMenuItem]
            }
        </div>
        {
            isUnityPlayerLoading && <LoadingMessage loadingProgression={loadingProgression}/>
        }
    </div>
}

const styles = {
    disabledUserAction: {
        userSelect: 'none',
        pointerEvents: 'none',
        filter: 'grayscale(100%)',
    },

    loadingWrapper: {
        width: '100%',
        height: '100%',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center'
    },

    toolWrapper: {
        // border: "5px solid blue",
        // position: "absolute",
        // height: '800px',

        // position: 'relative',
        boxSizing: 'border-box',
        display: 'flex',
        flexDirection: "column",

        // flex: 1,

        // height : '850px',
        // border: '5px solid red',

        // width: '100%',
        height: '100%'
    },

    app: {
        overflowY: 'hidden',
        position: 'relative',
        display: 'flex',
        flexDirection: "column",
        height: '100vh',
        // width: '100vw',
        flex: 1,
        // position: 'absolute',
        // width: '100%',
        // overflowY: 'hidden',
        // height: '95vh',
        // boxShadow: 'border-box',
        // border: '5px solid blue',
        // boxSizing: 'border-box',
    }
}

