import WonEngine from "./index";
import {EntityTypes} from "./Types";

export class SelectionHelper {

    selectionGraphic = new PIXI.Graphics();
    startedPos: PIXI.Point = new PIXI.Point();
    endPos: PIXI.Point = new PIXI.Point();
    rect: PIXI.Rectangle = new PIXI.Rectangle();

    isMoving = false;

    constructor() {
    }

    _getSelectionRect(): PIXI.Rectangle {
        const xMin = Math.min(this.startedPos.x, this.endPos.x);
        const yMin = Math.min(this.startedPos.y, this.endPos.y);
        const xMax = Math.max(this.startedPos.x, this.endPos.x);
        const yMax = Math.max(this.startedPos.y, this.endPos.y);

        this.rect.x = xMin;
        this.rect.y = yMin;
        this.rect.width = xMax - xMin;
        this.rect.height = yMax - yMin;

        return this.rect;
    }

    _drawSelectionGraphic() {
        this._getSelectionRect();
        this.selectionGraphic.clear();
        this.selectionGraphic.lineStyle(5, 0xFFFFFF, 1);
        this.selectionGraphic.drawRect(this.rect.x, this.rect.y, this.rect.width, this.rect.height);
    }

    onSelectionEnded() {
        const objects = WonEngine.GetInstance().managers.entityMgr.entityMap[EntityTypes.OBJECT];

        const selectedEntities = [];

        for (let [kay, entity] of Object.entries(objects)) {
            // if (this.rect.contains(entity.x, entity.y)) {
            //     selectedEntities.push(entity);
            // }
            if (this.rect.contains((entity as any).x, (entity as any).y)) {
                selectedEntities.push(entity);
            }
        }
    }

    init(container) {
        container.addChild(this.selectionGraphic);
    }

    handlePointerDown(event) {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        this.startedPos = event.data.getLocalPosition(mapToolRenderer.stage);
        this.endPos = event.data.getLocalPosition(mapToolRenderer.stage);
        // this.endPos.set(1, 1);
        this._drawSelectionGraphic();

        this.selectionGraphic.visible = true;
        this.isMoving = true;
    }

    handlePointerUp(event) {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        this.endPos = event.data.getLocalPosition(mapToolRenderer.stage);

        this.selectionGraphic.visible = false;
        this.isMoving = false;

        this.onSelectionEnded && this.onSelectionEnded();
    }

    handlePointerMove(event) {
        if (!this.isMoving) return;

        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        this.endPos = event.data.getLocalPosition(mapToolRenderer.stage);

        this._drawSelectionGraphic();
    }
}
