export const requestData = async (showToast = true, API, data) => {
    // if (productionMode) {
    //     return localData[API];
    // }
    let response;

    if (showToast) {
        response = await toast.promise(
            request.post(`${SERVER_URL}\\${API}`).send(data || {}),
            {
                pending: 'Promise is pending',
                success: `PostRequest[${API}] successfully`,
                error: 'Promise rejected 🤯'
            });
    } else {
        response = await request.post(`${SERVER_URL}\\${API}`).send(data || {});
    }

    if (response.status === 200) {
        console.log(`PostRequest[${API}] successfully`);
        return response?.body?.result || null;
    }
}

