export const GetGameDatabase = async (showToast, dataTypes = null) => {
    const defaultTypes = ['autoTileData', 'database', 'characters', 'items', 'mapEntities', 'cards', 'playerDataList', 'skills', 'stats'];
    const typesToLoad = dataTypes || defaultTypes;
    const result = {};
    const _productionMode = productionMode

    if (1) {
        if (typesToLoad.includes('autoTileData')) result.autoTileData = autoTileData;
        if (typesToLoad.includes('database')) result.database = database;
        if (typesToLoad.includes('characters')) result.characters = characterData.items;
        if (typesToLoad.includes('items')) result.items = itemData.items;
        if (typesToLoad.includes('mapEntities')) result.mapEntities = mapEntities.items;
        if (typesToLoad.includes('cards')) result.cards = cards.items;

        if (typesToLoad.includes('playerDataList')) result.playerDataList = playerDataList;
        if (typesToLoad.includes('skills')) result.skills = skills;
        if (typesToLoad.includes('stats')) result.stats = stats.items;

        return result;
    }

    if (typesToLoad.includes('autoTileData')) result.autoTileData = await loadAutoTileData(showToast);
    if (typesToLoad.includes('database')) result.database = await loadDatabase(showToast);
    if (typesToLoad.includes('characters')) result.characters = (await loadCharacters(showToast)).items;
    if (typesToLoad.includes('items')) result.items = (await loadItemData(showToast)).items;
    if (typesToLoad.includes('mapEntities')) result.mapEntities = (await loadTileData(showToast)).items;
    if (typesToLoad.includes('cards')) result.cards = (await loadCardData(showToast)).items;
    if (typesToLoad.includes('playerDataList')) result.playerDataList = await loadPlayerDataList(showToast);
    if (typesToLoad.includes('skills')) result.skills = await loadSkills(showToast);
    if (typesToLoad.includes('stats')) result.stats = (await loadStats(showToast)).items;

    return result;
};
