import React from 'react';
import {AttackTypes} from "../../WonEngine/Types";

const attackItems = [
    {
        name: 'slash',
        value: AttackTypes.SLASH,
    },
    {
        name: 'stab',
        value: AttackTypes.STAB,
    },
    {
        name: 'shoot',
        value: AttackTypes.SHOOT,
    },
    {
        name: 'magic',
        value: AttackTypes.MAGIC,
    },
];

export default (props) => {
    const {label, value, onChange} = props;
    return <div>
        <div className={"control-label"}>{label}</div>
        <div style={styles.container}>
            {
                attackItems.map((attackItem, index) =>
                    <div key={attackItem.name}
                         style={Object.assign({}, styles.item, value === attackItem.value && styles.selectedItem)}
                         onClick={() => onChange(attackItem.value)}>
                        {attackItem.name}
                    </div>)
            }
        </div>
    </div>
}

const styles = {
    container: {
        display: 'flex',
        flexDirection: 'row',
        cursor: 'pointer',
        // userSelect: 'none',
    },
    item: {
        userSelect: 'none',
        width: '100px',
        height: '40px',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',

        backgroundColor: 'lightGray',
        opacity: 0.3,
        textShadow: '2px 2px 2px white',
        fontWeight: 'bold',
    },
    selectedItem: {
        opacity: 1,
        outline: '2px solid black',
        color: 'orange',
    }
};
