import {CharState, TILE_SIZE, UNIT_SIZE} from "../Types";
import Entity from "../Entity";
import SpriteRenderer from "../components/SpriteRenderer";
import Movement from "../components/Movement";
import Text from "../components/Text";

import {CHARACTER_HEIGHT, CHARACTER_WIDTH} from "../../containers/CharacterTool/config";
import Weapon from "../components/Weapon";
import Gage from "../components/Gage";
import Rope from "../components/Rope";
import WonEngine from "../index";

export default class Character extends Entity {
    textureId = -1;
    state = CharState.STOP;
    characterData;
    equipments = {};

    constructor(data, coordX, coordY) {
        super({data, coordX, coordY});

        this.textureId = data.textureId;
        this.id = data.id;
        this.characterData = data;
        this.equipments = {};

        this.x = coordX * TILE_SIZE;
        this.y = coordY * TILE_SIZE;

        var coordsString = new Text(`${coordX}_${coordY}`, data.type);
        coordsString.nameText.y = -16;

        this.addComponent(
            // CharacterMgr Update에서 sprite를 변경해주고 있다.
            new SpriteRenderer(coordX, coordY, CHARACTER_WIDTH, CHARACTER_HEIGHT),
            new Movement(),
            new Text(data.name, data.type),
            coordsString,
            new Weapon(),
            // new Gage(),
            // new Rope(0, 0),
        );

        // this.addComponent(new Attack(coordX, coordY));

        // this.pivot.set(16 * 0.5, 32 * 0.5);
        this.getComponent(SpriteRenderer).sprite.anchor.set(0.5, 0.5);
        this.getComponent(SpriteRenderer).sprite.x += TILE_SIZE * 0.5;

        // this.getComponent(SpriteRenderer).sprite.y += CHARACTER_HEIGHT * 0.5;

        this.init();
    }

    update() {

        const {weaponMgr} = WonEngine.GetInstance().managers;
        const weapon = this.getComponent(Weapon);
        const rope = this.getComponent(Rope);

        const weaponData = weaponMgr.getWeaponData();
        if (weaponData) {
            weapon.update();

            // const px = Math.cos(weaponMgr.radian) * weaponData.texture.size[1] * UNIT_SIZE;
            // const py = Math.sin(weaponMgr.radian) * weaponData.texture.size[1] * UNIT_SIZE;
            const px = Math.cos(weapon.sprite.rotation) * weaponData.texture.size[1] * UNIT_SIZE;
            const py = Math.sin(weapon.sprite.rotation) * weaponData.texture.size[1] * UNIT_SIZE;
            rope && rope.update(
                this.x + weapon.sprite.x - px,
                this.y + weapon.sprite.y - py,
            );
        }
    }
}
