import {v4 as uuidv4} from 'uuid';
import WonEngine from "./index";

interface CustomRenderer {
    _init();

    _load(props: {});
}

export class StageRenderer implements CustomRenderer {
    wonEngine: any;
    stage: PIXI.display.Stage;
    isLoaded: boolean = false;
    uid: string;
    isActive: boolean = false;

    constructor() {
        this.stage = new PIXI.display.Stage();
        this.uid = uuidv4();
        this.wonEngine = WonEngine.GetInstance();
    }

    start() {

    }

    _init() {

    }

    init() {
        this._init();
    }

    _load(props: {}) {
    }

    load(props: {} = {}) {
        if (this.isLoaded) {
            return;
        }

        if (this._load) {
            this._load(props);
        }

        this.isLoaded = true;
    }

    render() {

    }
}
