import React, {useEffect, useState} from 'react';
import Select from 'react-select';
import WonEngine from "../../WonEngine";
import ItemDataSelect, {getItems} from "../../components/ItemDataSelect";

const createOptions = (items) => items.map(skill => ({
    value: skill.id,
    label: skill.name,
}));

export default (props) => {
    const {name, formData = [], onChange} = props;
    const {itemType = "default"} = props["uiSchema"]["ui:options"];
    const [options, setOptions] = useState([]);

    useEffect(() => {
        const wonEngine = WonEngine.GetInstance();
        const defaultOptions = createOptions(getItems(itemType) || []);

        setOptions(defaultOptions);

    }, [])

    return <div>
        <div className={"control-label"}>{name}</div>
        {/*<div>{JSON.stringify(formData)}</div>*/}
        <ItemDataSelect
            itemType={itemType}
            isMulti={true}
            styles={{
                control: (baseStyles, state) => ({
                    ...baseStyles,
                    // width: '200px',
                    // borderColor: state.isFocused ? 'grey' : 'red',
                }),
                multiValue: (styles, {data, isDisabled, isFocused, isSelected}) => ({
                    display: 'flex',
                    border: '11px solid blue',
                })
            }}
            // defaultValue={}
            value={formData}
            onChange={onChange}
            options={options}
        />
    </div>
}
