import React, {useEffect, useState} from 'react';
import WonEngine, {RENDER_TYPE} from "../../WonEngine";
import {loadDatabase, requestData, requestDataWidthToast, saveDatabase} from "../../DataRequester";
import {ActionTypes, DrawTypes, MAP_TOOL_SCALE} from "../../WonEngine/Types";
import {ToastContainer, toast} from 'react-toastify';

import PenIcon from '/www/res/icons/pen.png';
import PaintIcon from '/www/res/icons/paint.png';
import RectIcon from '/www/res/icons/rect.png';
import SelectionIcon from '/www/res/icons/selection.png';

import Icon from "../../components/Icon";
import EditIcon from '/www/res/icons/edit.png';
import PlayIcon from '/www/res/icons/play.png';
import MonitorIcon from '/www/res/icons/monitor.png';

const toolBarItems = {
    [DrawTypes.PEN]: {
        name: 'Pen',
        icon: PenIcon,
    },
    [DrawTypes.PAINT]: {
        name: 'Paint',
        icon: PaintIcon,
    },
    [DrawTypes.RECT]: {
        name: 'RECT',
        icon: RectIcon,
    },
    [DrawTypes.SELECTION]: {
        name: 'SELECTION',
        icon: SelectionIcon,
    }
}

const playModeItems = {
    [ActionTypes.EDIT]: {
        name: 'edit',
        icon: EditIcon,
    },
    [ActionTypes.PLAY]: {
        name: 'play',
        icon: PlayIcon,
    },
    // [ActionTypes.MONITOR]: {
    //     name: 'online',
    //     icon: MonitorIcon,
    // },
}

const ItemWrapper = props => <div style={styles.toolBarWrapper}>{props.children}</div>;


export default props => {
    const {selectedModeItem, setSelectModeItem} = props;
    const [selectedItem, setSelectItem] = useState('');

    useEffect(() => {
        setSelectItem(DrawTypes.PEN);
        setSelectModeItem(ActionTypes.EDIT);
        WonEngine.GetInstance().stageRenderers.mapToolRenderer.selectDrawItem(DrawTypes.PEN);
        // setSelectItem(DrawTypes.PEN);
    }, [])

    useEffect(() => {
        const wonEngine = WonEngine.GetInstance();
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;


        // if (selectedModeItem === ActionTypes.EDIT) {
        //     mapToolRenderer.clear();
        //     (async () => {
        //         const database = await loadDatabase();
        //         WonEngine.GetInstance().loadData(database);
        //     })();
        // }


        wonEngine.changeUserAction(selectedModeItem);
    }, [selectedModeItem])

    const handleClickSave = async () => {

        // const data = WonEngine.GetInstance().saveData();
        // return await requestData(`save/Database`, data);
        await saveDatabase();
    }

    const handleClickLoad = async () => {
        const database = await loadDatabase();
        WonEngine.GetInstance().loadData(database);
    }

    const handleClickSaveUnity = async () => {
        const data = WonEngine.GetInstance().saveData();

        let newData = {
            keys: [],
            values: [],
        };

        Object.entries(data).forEach(([key, values]) => {
            newData.keys.push(key);

            values.forEach((value) => {
                newData.values.push(value);
            });
        })

        const response = await request.post(`http://localhost:5000/save/unity/database`)
            // .withCredentials()
            .send(data);
        if (response.status === 200) {
            console.log('Save autoTile successfully');
        }
    }


    const handleClickDrawItem = (selectedDrawItem) => {
        setSelectItem(selectedDrawItem);
        WonEngine.GetInstance().stageRenderers.mapToolRenderer.selectDrawItem(selectedDrawItem);
    }

    const handleClickSplitTexture = async () => {
        const wonEngine = WonEngine.GetInstance();

        let i = 0;
        for (const generatedAutoTileSprite of wonEngine.autoTileGenerator.generatedAutoTileSprites) {
            const base64 = wonEngine.renderer.extract.base64(generatedAutoTileSprite, 'image/png');
            await requestData('save/texture', {i: i++, base64});
        }
    }

    const handleClickClearMap = () => {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        mapToolRenderer.clear();
    }

    const handleClickModeItem = (item) => {
        // const selectedModeItem = item === 'EDIT' ? RENDER_TYPE.MAP_TOOL : RENDER_TYPE.PLAY;
        const {characterMgr} = WonEngine.GetInstance().managers;

        if (item === ActionTypes.PLAY && !characterMgr.getHero()) {
            toast.error("Hero is not found.", {});
            return;
        }

        setSelectModeItem(item);
    };

    return <div style={styles.ToolBar}>
        <ItemWrapper>
            {
                Object.entries(toolBarItems).map(([key, toolBarItem]) =>
                    <Icon key={key} style={styles.icon}
                          selected={selectedItem === key} src={toolBarItem.icon}
                          onClick={handleClickDrawItem.bind(this, key)}
                    />)
            }
        </ItemWrapper>
        <ItemWrapper>
            {
                Object.entries(playModeItems).map(([key, item]) =>
                    <Icon key={item.name} style={styles.icon} src={item.icon}
                          onClick={handleClickModeItem.bind(this, key)} selected={selectedModeItem === key}/>
                )
            }
        </ItemWrapper>
        <div style={styles.group}>
            <button onClick={handleClickSave.bind(this)}>Save</button>
            <button onClick={handleClickLoad.bind(this)}>Load</button>
        </div>
        <div style={styles.group}>
            <button onClick={handleClickSplitTexture.bind(this)}>Save SplitTexture</button>
            <button onClick={handleClickClearMap.bind(this)}>Clear Map</button>
        </div>
    </div>
}

const styles = {
    group: {
        margin: '0.2em',
        boxShadow: '1px 1px 1px white',
        display: 'flex',
        flexDirection: 'row',
    },
    icon: {
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        cursor: 'pointer',
        margin: '0.3em',
    },
    toolBarWrapper: {
        margin: '0.2em',
        border: '2px solid black',
        boxShadow: '1px 1px 1px white',
        display: 'flex',
        flexDirection: 'row',
    },
    Button: {
        cursor: 'pointer',
        marginRight: '0.2em',
    },

    ToolBar: {
        display: 'flex',
        flexDirection: 'row',
        backgroundColor: '#f6f9f8',
        borderBottom: '1px solid darkGray',
        // backgroundColor: 'darkkhaki',
        fontSize: '2em',
        textShadow: '2px 2px 2px white',
        userSelect: 'none',
    },

}
