import {TextureSelectMode} from "../../jsonSchema/fields/TextureSelector/TextureSelector";
import {EntityTypes, TextureKeyTypes} from "../../WonEngine/Types";

export const textureSchema = {

    "type": "object",
    "properties": {
        "textureName": "string",
        "coords": {
            "type": "array"
        },
        "size": {
            "type": "array",
        },
    }
}

const dependencies = {
    "itemType": {
        "oneOf": [
            {
                "properties": {
                    "itemType": {
                        "enum": [
                            EntityTypes.TILE
                        ],
                    },
                    // "loots": {
                    //     "type": "array",
                    // },
                },
            },
            {
                "properties": {
                    "itemType": {
                        "enum": [
                            EntityTypes.OBJECT
                        ],
                    },
                    "loots": {
                        "type": "array",
                    },
                    // "craftItems": {
                    //     "type": "array",
                    // },
                },
            },
        ],
    },
    "tileType": {
        "oneOf": [
            {
                "properties": {
                    "tileType": {
                        "enum": [
                            "TILE"
                        ],
                    },
                    "texture": {
                        "textureName": "overworld",
                        ...textureSchema,
                    },
                },
            },
            {
                "properties": {
                    "tileType": {
                        "enum": [
                            "AUTO_TILE",
                        ],
                    },
                    "texture": {
                        ...textureSchema,
                        "textureName": "3x3AutoTiles",
                        "selectMode": TextureSelectMode.DEFAULT,
                    }
                }
            },
        ],
    }
}

export const itemSchema = {
    "type": "object",
    "properties": {
        "name": {
            "type": "string"
        },
        "hasShadow": {
            "type": "boolean",
        },
        "hasLighting": {
            "type": "boolean",
        },
        "description" : {
            "type" : "string"
        },
        // "loots": {
        //     "type": "array",
        // },
        "itemType": {
            "type": "string",
            "enum": [
                EntityTypes.TILE,
                EntityTypes.OBJECT,
            ],
            "default": EntityTypes.TILE,
        },
        "tileType": {
            "type": "string",
            "enum": [
                "TILE",
                "AUTO_TILE",
            ],
            "default": "TILE",
        },
    },

    dependencies,
};

export const uiSchema = {
    "ui:order": [
        "texture",
        "name",
        "description",
        "itemType",
        "tileType",
        "*"
        // "foo"
    ],
    "loots": {
        "ui:field": "GameItemSelector",
    },
    // "craftItems": {
    //     "ui:field": "GameItemSelector",
    // },
    "itemType": {
        "ui:widget": "OneOfSelector",
    },
    "tileType": {
        "ui:widget": "OneOfSelector",
    },
    "texture": {
        "ui:field": "TextureSelector",
        "ui:options": {
            // "textureKeyType": TextureKeyTypes.TILE,
            "textureKeyType": TextureKeyTypes.ITEM,
        }
    },
}
