import Manager from "./Manager";
import Tile from "../entities/Tile";
import SpriteRenderer from "../components/SpriteRenderer";
import Entity from "../Entity";

export default class EntityMgr extends Manager {
    entities: any[] = [];
    entityMap: any = {
        [EntityTypes.TILE]: {},
        [EntityTypes.OBJECT]: {},
        [EntityTypes.CHARACTER]: {},
        [EntityTypes.ITEM]: {},
    };

    entityMapById: any = {}

    oldEntityMap: any = {};

    constructor() {
        super();
        this.entities = []
    }

    getEntityDataById(id) {
        return this.entityMapById[id];
    }

    update() {

    }

    addEntity(entityData, coordX, coordY) {
        // const {tileMap} = this.wonEngine.
        // const entity = new Tile(PIXI.Texture.WHITE);
        // entity.x = coordX * TILE_SIZE;
        // entity.y = coordY * TILE_SIZE;
        // entity.width = TILE_SIZE;
        // entity.height = TILE_SIZE;
        // entity.index = selectedItem.index;
        // entity.terrainType = selectedItem.terrainType;
        // entity.data = selectedItem;

        // this.addChild(tile);
        // this.setEntity(entityType, tile, coordX, coordY);
    }

    getEntity(type, coordX, coordY) {
        return this.entityMap[type][`${coordX}_${coordY}`] || null;
    }

    removeEntity(type, coordX, coordY) {
        const {characterMgr, roomMgr} = this.wonEngine.managers;
        const {mapToolRenderer, autoTileRenderer} = this.wonEngine.stageRenderers;
        const parentContainer = mapToolRenderer.layers[type] || mapToolRenderer.tileMap;
        // const parentContainer : PIXI.Container = entity.parent;
        const entity = this.getEntity(type, coordX, coordY);
        if (entity) {
            parentContainer.removeChild(entity);

            if (AutoTileRenderer.IsAutoTile(entity.data)) {
                mapToolRenderer.tileMap.applyNeighbors(null, mapToolRenderer.selectedItem.itemType, coordX, coordY);
            }

            switch (entity.type) {
                case EntityTypes.OBJECT:

                    break;
                case EntityTypes.CHARACTER:
                    characterMgr.entities.delete(entity);
                    break;
            }

            this.entityMap[type][`${coordX}_${coordY}`] = null;
            delete this.entityMap[type][`${coordX}_${coordY}`];

            entity.release && entity.release();

            if (entity.data.itemType === EntityTypes.OBJECT) {
                roomMgr.setDirty(true);
            }
        }
    }

    // Entity가 존재하면 덮어씌운다.
    setEntity(type, entity, coordX, coordY) {
        const {characterMgr} = this.wonEngine.managers;
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const entityKey = `${coordX}_${coordY}`;

        if (!this.entityMap[type][entityKey]) {
            this.entityMap[type][entityKey] = entity;
            if (type === EntityTypes.CHARACTER) {
                characterMgr.entities.add(entity);
            }
        }

        switch (entity.type) {
            case EntityTypes.OBJECT:
                // mapToolRenderer.layers['SHADOW']
                break;
            case EntityTypes.CHARACTER:
                break;
        }

        mapToolRenderer.layers[type].addChild(entity);
    }

    deleteEntity(entity) {
    }
}
