import React, {useEffect, useRef, useState} from 'react';
import request from "superagent";
import {productionMode, SERVER_URL} from "../../config";

let _setSoundEffectList = [];


export default (props) => {
    const {value, showing = false, onChange} = props
    const audioRef = useRef(null);
    const containerRef = useRef(null);
    const [selectedSoundEffectIndex, setSelectedSoundEffectIndex] = useState(-1)
    const [soundEffectList, setSoundEffectList] = useState([])
    const [filterText, setFilterText] = useState("")
    const [isShowResources, showResources] = useState(showing)

    const handleKeyDown = (e) => {
        // Up
        if (e.keyCode === 38) {
            if (selectedSoundEffectIndex > 0) {
                setSelectedSoundEffectIndex(selectedSoundEffectIndex - 1);
            } else {
                setSelectedSoundEffectIndex(soundEffectList.length - 1);

            }
        }

        // Down
        if (e.keyCode === 40) {
            if (selectedSoundEffectIndex < soundEffectList.length - 1)
                setSelectedSoundEffectIndex(selectedSoundEffectIndex + 1);
            else {
                setSelectedSoundEffectIndex(0);
            }
        }

        if (e.keyCode === 32) {
            if (audioRef.current) {
                audioRef.current.play();
            }
        }

        e.preventDefault();
    };

    const getAudioPath = (selectedSoundEffect) => {
        const foundItem = soundEffectList.find(soundEffect => soundEffect.name === selectedSoundEffect);

        if (foundItem)
            return `${SERVER_URL}\\${foundItem.path}`;
        return null;
    }

    useEffect(() => {
        (async () => {
            if (soundEffectList.length <= 0) {
                const response = await request.post(`${SERVER_URL}\\${"load\\sound\\list"}`);

                // soundEffectList = response.body.result;

                // setSoundEffectList(response.body.result.slice(0, 10));
                setSoundEffectList(response.body.result);
            }
        })()

        return () => {

        }
    }, [])

    useEffect(() => {
        const foundItemIndex = soundEffectList.findIndex(soundEffect => soundEffect.name === value);

        if (foundItemIndex !== -1) {
            setSelectedSoundEffectIndex(foundItemIndex);
        } else {
            setSelectedSoundEffectIndex(-1);
        }
    }, [value])

    async function playAudio(path) {
        try {
            const fullPath = getAudioPath(selectedSoundEffectIndex)

            const response = await fetch(fullPath);
            const data = await response.arrayBuffer();

            const audioContext = new (window.AudioContext || window.webkitAudioContext)();
            const audioBuffer = await audioContext.decodeAudioData(data);

            const source = audioContext.createBufferSource();
            source.buffer = audioBuffer;

            source.connect(audioContext.destination);

            source.start();
        } catch (error) {
            console.error('오디오 파일 가져오기 및 재생 중 오류 발생:', error);
        }
    }

    useEffect(() => {
        if (!soundEffectList[selectedSoundEffectIndex]) return;

        try {
            // Todo 렉 해결
            // onChange(soundEffectList[selectedSoundEffectIndex].name)

            const audioPath = soundEffectList[selectedSoundEffectIndex].path
                .replace(/\\/g, "/")
                .replace(/ /g, "%20")

            // <audio> 요소에 대한 참조를 사용하여 <source> 요소의 src 속성을 변경
            audioRef.current.querySelector("source").src = `${SERVER_URL}\\${audioPath}`;

            // 오디오를 다시 로드
            audioRef.current.load();
        } catch (e) {
            console.warn(e);
        }
    }, [selectedSoundEffectIndex]);

    const handleOnSelect = (index) => {
        setSelectedSoundEffectIndex(index)
    }

    // const handleOnClick = async () => {
    //     const response = await request.post(`${SERVER_URL}\\${"load\\sound\\list"}`);
    //
    //     const soundEffectList = response.body.result;
    //
    //     setSoundEffectList(soundEffectList);
    // }


    return <div style={{
        display: 'flex',
        flexDirection: 'column',
    }}>
        <div>
            <div style={{
                userSelect: 'none',
                fontSize: '1.5em',
                cursor: 'pointer',
            }}>
                {soundEffectList[selectedSoundEffectIndex] && <div>
                    {soundEffectList[selectedSoundEffectIndex].name}
                    <button style={{
                        padding: '0.3em',
                    }} onClick={() => setSelectedSoundEffectIndex(-1)}>Clear
                    </button>
                </div>}
            </div>
            <button style={{
                padding: '0.3em',
            }} onClick={() => showResources(!isShowResources)}>{
                !isShowResources ? "show Resources" : "hide Resource"
            }
            </button>
        </div>

        {
            isShowResources &&
            <div style={{
                top: "50%",
                left: "50%",
                transform: `translate(-50%, -50%)`,
                position: 'absolute',
                border: '1px solid gray',
                borderRadius: '5px',
                // display: 'flex',
                flexDirection: 'column',
                width: '400px',
                height: '400px',
                zIndex: "999",

                backgroundColor: 'white',
                padding: '1em',
            }}>
                <div>total : {soundEffectList.length}</div>
                <div tabIndex="0" ref={containerRef} onKeyDown={handleKeyDown.bind(this)} style={{
                    backgroundColor: 'white',
                    overflowY: 'auto',
                }}>
                    <div style={{
                        cursor: 'pointer',
                        userSelect: 'none',
                        height: '300px',
                    }}>
                        {soundEffectList.map((soundEffect, soundEffectIndex) => {

                            if (!soundEffect.name.includes(filterText)) return;

                            return <div style={Object.assign({}, soundEffectIndex === selectedSoundEffectIndex && {
                                backgroundColor: 'orange',
                            })} key={soundEffect.name} onClick={handleOnSelect.bind(this, soundEffectIndex)}>
                                {soundEffect.name}
                            </div>
                        })}
                    </div>
                </div>
                <input style={{
                    height: '2em',
                    display: 'flex',
                    width: '100%',
                }} type="text" placeholder={"Search..."} value={filterText}
                       onChange={e => setFilterText(e.target.value)}/>
                <audio style={{
                    // display: 'flex',
                    width: '100%',
                    // boxSizing: 'border-box',
                }} ref={audioRef} controls>
                    <source src={""} type="audio/wav"/>
                    Your browser does not support the audio element.
                </audio>
                {/*<button onClick={handleOnClick}>SearchFiles</button>*/}
                {/*<button onClick={handleOnPlay}>Play</button>*/}
            </div>
        }

    </div>
}
