import CanvasRenderer from "./containers/CharacterTool/CanvasRenderer";

export const generateDataURL = (character) => {
    const canvasRenderer = CanvasRenderer.GetInstance();
    const {base, head, face, eyes, body, hair, suit, item} = character;

    canvasRenderer.renderAll(0, {
        preAnimation: 'no',
        partState: {base, head, face},
        paletteState: {eyes, body, hair, suit, item},
    }, canvasRenderer.tempCanvas);

    return canvasRenderer.tempCanvas.toDataURL();
}

export const addResources = (resources) => {
    return new Promise((resolve) => {
        const loader = PIXI.Loader.shared;

        for (const [key, resource] of Object.entries(resources)) {
            if (!PIXI.Loader.shared.resources[key]) {
                loader.add(key, resource);
            }
        }

        loader.load(() => {
            for (const attr in resources) {
                if (!loader.resources[attr].texture) continue;
                loader.resources[attr].texture.baseTexture.scaleMode = PIXI.SCALE_MODES.NEAREST;
            }

            resolve(true);
        })
    })
}
