import {DrawTypes, AUTO_TILE_RENDERING_SIZE, TILE_SIZE, EntityTypes} from "../../Types";
import WonEngine from "../../index";
import ActionBase from "./ActionBase";

export class EditAction extends ActionBase {

    entityShadow: PIXI.Sprite;
    textureShadow: PIXI.Sprite;

    constructor() {
        super();
        this.entityShadow = new PIXI.Sprite();
        this.textureShadow = new PIXI.Sprite();
    }

    onPointerDown() {

    }

    onPointerUp() {

    }

    init() {
        const {mapToolRenderer, autoTileRenderer} = WonEngine.GetInstance().stageRenderers;
        const {layers} = WonEngine.GetInstance();
        this.entityShadow.texture = PIXI.Texture.WHITE;
        this.entityShadow.alpha = 0.5;
        this.entityShadow.interactive = false;

        this.entityShadow.addChild(this.textureShadow);

        mapToolRenderer.layers["TOOL"].addChild(this.entityShadow);
        // mapToolRenderer.container.addChild(this.entityShadow);
    }

    render() {
        const {characterMgr, textureMgr} = WonEngine.GetInstance().managers;
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const tileMap = mapToolRenderer.tileMap;
        const selectedItemData = mapToolRenderer.selectedItem;

        const mousePosition = tileMap.toLocal(mapToolRenderer.globalMousePosition);
        const tileCoordX = Math.floor(mousePosition.x / TILE_SIZE);
        const tileCoordY = Math.floor(mousePosition.y / TILE_SIZE);

        this.entityShadow.x = tileCoordX * TILE_SIZE;
        this.entityShadow.y = tileCoordY * TILE_SIZE;

        // Paint map entity shadow
        if (selectedItemData) {
            if (selectedItemData.tileType !== "AUTO_TILE" &&
                selectedItemData.itemType !== EntityTypes.CHARACTER &&
                selectedItemData.itemType !== EntityTypes.ITEM) {

                // this.textureShadow.visible = true;
                const texture = textureMgr.getTextureByData(selectedItemData);
                this.textureShadow.texture = texture;

                if (selectedItemData.texture) {
                    const yOffset = (selectedItemData.texture.size[1] - 1) * TILE_SIZE;
                    this.textureShadow.y = -yOffset;
                }


            } else {
                this.textureShadow.texture = PIXI.Texture.EMPTY;
            }
        }

        if (tileMap.isDownedTileMapContainer) {
            if (!tileMap.bounds.contains(mousePosition.x, mousePosition.y)) {
                return;
            }

            if (mapToolRenderer.selectedItem) {
                switch (mapToolRenderer.drawType) {
                    case DrawTypes.PEN:
                        if (mapToolRenderer.selectedItem.itemType === EntityTypes.CHARACTER) {
                            if (mapToolRenderer.selectedItem.index === 0) {
                                characterMgr.remove(tileCoordX, tileCoordY);
                            } else {
                                characterMgr.add(mapToolRenderer.selectedItem, tileCoordX, tileCoordY);
                            }
                        } else {
                            mapToolRenderer.renderItem(tileCoordX, tileCoordY);
                        }
                        break;
                    case DrawTypes.PAINT:
                        mapToolRenderer.renderItem(tileCoordX, tileCoordY);
                        mapToolRenderer.paintItems(tileCoordX, tileCoordY);
                        break;
                    case DrawTypes.RECT:
                        break;
                    case DrawTypes.SELECTION:
                    default:
                        break;
                }
            }
        }
    }
}
