import {BitDirections, CONTAINER_SCALE} from "../../Types";

class BitTile extends PIXI.Sprite {
    constructor() {
        super(PIXI.Texture.WHITE);
    }

    update() {

    }
}

class AutoTile extends PIXI.Container {
    mapCoordX: number;
    mapCoordY: number;

    bitTiles: Object = {};
    bit = 0;

    textGraphic = new PIXI.Text('', {
        fontSize: 16,
        fill: 0xFFFFFF,
        fontWeight: 'bold',
        stroke: '#000000',
        strokeThickness: 3,
        align: 'left'
    });

    constructor(x, y, tileSize) {
        super();

        this.x = x * tileSize;
        this.y = y * tileSize;

        // this.textGraphic.visible = false;
        this.textGraphic.text = `${this.bit}`;
        this.textGraphic.scale.x /= CONTAINER_SCALE * 3;
        this.textGraphic.scale.y /= CONTAINER_SCALE * 3;
        this.addChild(this.textGraphic);
    }

    clearMask() {
        for (let y = 0; y < 3; y++) {
            for (let x = 0; x < 3; x++) {
                this.bit = 0;
                const bitTile = this.getBitTile(x, y);
                bitTile.alpha = 0;
            }
        }
        this.textGraphic.text = '0';
    }

    invertMask() {
        for (let y = 0; y < 3; y++) {
            for (let x = 0; x < 3; x++) {
                this.bitMask(x, y);
            }
        }
    }

    bitMask(x: number, y: number, value: number = undefined) {
        // 가운데타일 비활성화.
        if (x === 1 && y === 1) {
            return;
        }

        const bitTile = this.getBitTile(x, y);
        const bitTileMask = value ? value : !(this.bit & BitDirections[`${x}_${y}`].bit);

        if (bitTileMask) {
            this.bit |= BitDirections[`${x}_${y}`].bit;
            bitTile.alpha = 0.5;
        } else {
            this.bit &= ~BitDirections[`${x}_${y}`].bit;
            bitTile.alpha = 0;
        }

        this.textGraphic.text = `${this.bit}`;
    }

    setBitTile = (x: number, y: number, newBitTile) => {
        this.bitTiles[`${x}_${y}`] = newBitTile;
    };
    getBitTile = (x: number, y: number) => this.bitTiles[`${x}_${y}`];
}

export default AutoTile;
