import WonEngine from "../../index";

export default class AutoTileGenerator {
    generatedAutoTileTextures: any[] = [];
    generatedAutoTileSprites: any[] = [];

    constructor() {
    }

    setFragment(baseTextureName, offsetX, offsetY, tileWidth, tileHeight,
                container, mapCoordArray, x, y) {
        const fragmentWidth = tileWidth * 0.5;
        const fragmentHeight = tileHeight * 0.5;
        const fragmentTexture = WonEngine.GetTexture(baseTextureName, new PIXI.Rectangle(
            offsetX + mapCoordArray[0] * fragmentWidth,
            offsetY + mapCoordArray[1] * fragmentHeight,
            fragmentWidth, fragmentHeight
        ));

        const fragSprite = new PIXI.Sprite(fragmentTexture);
        fragSprite.x = x;
        fragSprite.y = y;
        container.addChild(fragSprite);
    }

    selectAutoTile(index) {
        const {autoTileRenderer} = WonEngine.GetInstance().stageRenderers;
        const {autoTileGenerator} = WonEngine.GetInstance();
        let i = 0;
        for (const generatedAutoTileSprite of autoTileGenerator.generatedAutoTileSprites) {
            generatedAutoTileSprite.visible = i++ === index;
        }

        autoTileRenderer.autoTileEditSprite.texture = this.generatedAutoTileTextures[index];
    }

    generateAutoTileTextures(autoTileTable, textureName, textureCount, offsetX, offsetY) {
        const {renderer} = WonEngine.GetInstance();
        const generatedAutoTileTextures = [];

        for (let i = 0; i < textureCount + 1; i++) {
            const offsetCoordX = i * offsetX;
            const offsetCoordY = i * offsetY;


            const generatedAutoTileContainer = this.generateAutoTileContainer(
                autoTileTable, textureName, offsetCoordX, offsetCoordY, 16, 16);

            // GenerateTexture.
            const generatedAutoTileTexture = renderer.generateTexture(generatedAutoTileContainer,
                null, PIXI.SCALE_MODES.NEAREST);

            generatedAutoTileTextures.push(generatedAutoTileTexture);
        }

        return generatedAutoTileTextures;
    }

    generateAutoTileContainer(tileTable, baseTextureName, offsetX, offsetY, tileWidth = 8, tileHeight = 8) {
        const halfTileWidth = tileWidth * 0.5;
        const halfTileHeight = tileHeight * 0.5;
        const generatedAutoTiles: PIXI.Container[] = [];

        for (let i = 0; i < tileTable.length; i++) {
            const autoTileContainer = new PIXI.Container();
            // autoTileContainer.scale.set(CONTAINER_SCALE, CONTAINER_SCALE)
            this.setFragment(baseTextureName, offsetX, offsetY, tileWidth, tileHeight, autoTileContainer, tileTable[i][0], 0, 0);
            this.setFragment(baseTextureName, offsetX, offsetY, tileWidth, tileHeight, autoTileContainer, tileTable[i][2], 0, halfTileHeight);
            this.setFragment(baseTextureName, offsetX, offsetY, tileWidth, tileHeight, autoTileContainer, tileTable[i][3], halfTileWidth, halfTileHeight);
            this.setFragment(baseTextureName, offsetX, offsetY, tileWidth, tileHeight, autoTileContainer, tileTable[i][1], halfTileWidth, 0);
            generatedAutoTiles.push(autoTileContainer);
        }

        const dummyTextureIndex = 6 * 8;
        const dummyTexture = WonEngine.GetInstance().generateTexture(generatedAutoTiles[dummyTextureIndex]);

        // fill dummy tiles.
        const dummyData = new Array(15).fill(null).map(() => {
            const dummySprite = new PIXI.Sprite(dummyTexture);
            dummySprite.width = tileWidth;
            dummySprite.height = tileHeight;
            return dummySprite;
        });
        generatedAutoTiles.push(...dummyData);

        const resultContainer = new PIXI.Container();

        const scaledSize = 16;
        for (let i = 0; i < generatedAutoTiles.length; i++) {
            generatedAutoTiles[i].x = (i % 8) * scaledSize;
            generatedAutoTiles[i].y = Math.floor(i / 8) * scaledSize;
            resultContainer.addChild(generatedAutoTiles[i]);
        }

        return resultContainer;
    }
}
