import React, {useEffect, useLayoutEffect, useRef} from 'react';
import Form from "@rjsf/core";
import validator from "@rjsf/validator-ajv6";
import CanvasRenderer, {CANVAS_HEIGHT, CANVAS_SCALE, CANVAS_WIDTH} from "./CanvasRenderer";
import AnimationToolBar from "./AnimationToolBar";
import {defaultFormData, schema, uiSchema, widgets} from "./CharacterSchemas";
import {EntityTypes} from "../../WonEngine/Types";
import {v4 as uuidv4} from 'uuid';
import {generateSpriteSheet} from "../../hooks";
import {CHARACTER_SHEET_HEIGHT, CHARACTER_SHEET_WIDTH} from "./config";

const getDefaultName = (index) => `character ${index}`;

export default (props) => {
    const {
        characters, setCharacters,
        selectedCharacterIndex,
        formData, setFormData,
    } = props;
    const canvasContainerRef = useRef(null);
    const isSelected = selectedCharacterIndex !== -1;

    useEffect(() => {
        const canvasRenderer = CanvasRenderer.GetInstance();

        Object.assign(canvasRenderer.canvas.style, styles.canvas, {
            width: `${CANVAS_WIDTH * CANVAS_SCALE}px`,
            height: `${CANVAS_HEIGHT * CANVAS_SCALE}px`,
        })

        canvasContainerRef.current.appendChild(canvasRenderer.canvas);

        let shouldUpdate = false;
        const newCharacters = characters.map(character => {
            if (!character.id) {
                character.id = uuidv4();
                shouldUpdate = true;
            }
            return character;
        })

        shouldUpdate && setCharacters(newCharacters);

        // set default form data.
        setFormData({
            ...formData,
            name: getDefaultName(characters.length),
        });
    }, []);

    useEffect(() => {
        const {base, head, face, eyes, body, hair, suit, item} = formData;

        CanvasRenderer.GetInstance().changePart({
            base, head, face,
        });

        CanvasRenderer.GetInstance().changePalette({
            eyes, body, hair, suit, item,
        });

    }, [formData]);

    const handleSubmit = ({formData}) => {

        const newCharacter = {
            ...formData,
            index: characters.length + 1,
            id: uuidv4(),
        };

        delete newCharacter["dataURL"];

        const newCharacters = [
            ...characters,
            newCharacter,
        ];
        setCharacters(newCharacters);

        // setFormData({
        //     ...defaultFormData,
        //     name: getDefaultName(characters.length + 1),
        // });
    }

    const handleClickDelete = () => {
        characters.splice(selectedCharacterIndex, 1);
        setCharacters([...characters]);
    };

    const handleClickUpdate = () => {
        characters[selectedCharacterIndex] = formData;
        setCharacters([...characters]);
    };

    return <div style={styles.characterForm}>
        <div style={{
            marginRight : '1em',
        }}>
            <div ref={canvasContainerRef}/>
            <img src={generateSpriteSheet(characters[selectedCharacterIndex])} style={{
                border: '1px solid black',
                imageRendering: 'pixelated',
                width: CHARACTER_SHEET_WIDTH * 4,
                height: CHARACTER_SHEET_HEIGHT * 4,
            }}/>
        </div>
        <div>
            <AnimationToolBar setFormData={setFormData} formData={formData}/>
            <Form showErrorList={false} autoComplete="off" formData={formData}
                  schema={schema} uiSchema={uiSchema} widgets={widgets}
                  validator={validator}
                  onChange={e => setFormData(e.formData)} onSubmit={handleSubmit.bind(this)}>
                <div style={styles.submitButtonWrapper}>
                    <button style={styles.formButton} type="submit">Add Character</button>
                    {
                        isSelected && <button style={styles.formButton} type="reset"
                                              onClick={handleClickUpdate.bind(this)}>Update Character</button>}
                    {
                        isSelected && <button style={styles.formButton} type="reset"
                                              onClick={handleClickDelete.bind(this)}>Delete Character</button>
                    }
                </div>
            </Form>
        </div>
    </div>
}

const styles = {
    characterForm: {
        display: 'flex',
        flexDirection: 'row',
        margin: "1em",
        userSelect: "none",
    },
    canvas: {
        imageRendering: 'pixelated',
        margin: "0.3em",
        border: '1px solid black',
    },
    formButton: {
        width: '150px',
        padding: "1em",
    },
    submitButtonWrapper: {
        marginTop: '1em',
        display: 'flex',
    }
}
