export const generateSpriteSheet = (character) => {
    if (!character) return;

    const canvasRenderer = CanvasRenderer.GetInstance();
    const ctx = spriteSheetCanvas.getContext('2d');
    const {base, head, face, eyes, body, hair, suit, item} = character;

    spriteSheetCanvas.getContext('2d').clearRect(0, 0,
        spriteSheetCanvas.width,
        spriteSheetCanvas.height);

    ctx.drawImage(canvasRenderer.tempCanvas,
        spriteSheetCanvas.width,
        spriteSheetCanvas.height);

    for (let i = 0; i < animations.length; i++) {
        for (let j = 0; j < animations[i].maxFrame; j++) {
            canvasRenderer.renderAll(j, {
                preAnimation: animations[i].name,
                partState: {base, head, face},
                paletteState: {eyes, body, hair, suit, item},
            }, canvasRenderer.tempCanvas);

            ctx.drawImage(canvasRenderer.tempCanvas, j * CHARACTER_WIDTH, i * CHARACTER_HEIGHT);
        }
    }

    return spriteSheetCanvas.toDataURL();
}

export const updateCharacterTextures = async (characters) => {
    if (!characters.length) {
        return;
    }

    const {characterMgr} = WonEngine.GetInstance().managers;
    const loader = PIXI.Loader.shared;
    const resources = {};
    const newCharacters = characters.map((character) => {
        if (!loader.resources[character.id]) {
            const dataURL = generateSpriteSheet(character);
            // const textureId = PIXI.utils.uid();

            resources[character.id] = dataURL;

            return ({
                ...character,
                dataURL,
            })
        }

        return character;
    })

    // 업데이트할 캐릭터가 없으면 무한루프를 막는다.
    if (Object.keys(resources).length <= 0) {
        return;
    }

    await addResources(resources);
    characterMgr.generateFrameTextures(resources);

    for (const [key, value] of Object.entries(resources)) {
        const texture = loader.resources[key];
        characterMgr.characterTextures[key] = texture;
    }

    return newCharacters;
};

const defaultTextureData = {
    "textureName": "overworld",
    "coords": [
        0,
        0
    ],
    "size": [
        1,
        1
    ]
};

export const updateTexture = (items) => {
    const wonEngine = WonEngine.GetInstance();
    const {textureMgr} = wonEngine.managers;

    let shouldUpdate = false;
    for (const item of items) {
        const {textureName, size, coords} = item.texture || defaultTextureData;
        const textureKey = `${textureName}_${coords[0]}_${coords[1]}_${size[0]}_${size[1]}`;

        if (textureMgr.get(TextureKeyTypes.ITEM, textureKey)) continue;

        let texture;
        if (item.tileType === "AUTO_TILE") {
            texture = WonEngine.GetTexture(textureName,
                new PIXI.Rectangle(
                    (coords[0] * 16) + 3 * 16, (coords[1] * 16) + 2 * 16,
                    16, 16,
                ));
        } else {
            texture = WonEngine.GetTexture(textureName,
                new PIXI.Rectangle(
                    coords[0] * 16, coords[1] * 16,
                    size[0] * 16, size[1] * 16
                ));
        }


        textureMgr.add(TextureKeyTypes.ITEM, textureKey, texture);
        // textureMgr.add(TextureKeyTypes.ITEM, textureKey, wonEngine.extractToBase64(texture));
        shouldUpdate = true;
    }
    return shouldUpdate;
};

export const useTextureUpdate = (items, setItems) => {
    useEffect(() => {
        const shouldUpdate = updateTexture(items);

        // if (shouldUpdate) {
        //     setItems([...items]);
        // }

    }, [items])
};

export const useFilterItems = (items, category, setFilteredItems) => {
    // Filter items.
    useEffect(() => {
        if (category) {
            // Filter category.
            const newFilteredItems = {};
            for (const [index, item] of items.entries()) {
                let categoryKey = item[category.key];

                if (category.list.includes(categoryKey)) {
                    // 가테코리가 없으면 가테코리 생성.
                    if (!newFilteredItems[categoryKey]) {
                        newFilteredItems[categoryKey] = [];
                    }

                    if (newFilteredItems[categoryKey]) {
                        newFilteredItems[categoryKey].push([index, item]);
                    }
                } else {
                    // Todo 가테코리가 없으면 Default에 생성.
                    let defaultCategoryKey = category.list[0];
                    newFilteredItems[defaultCategoryKey].push([index, item]);
                }
            }

            setFilteredItems(newFilteredItems);
        } else {
            // Default category.
            setFilteredItems({
                Default: items.map((item, index) => {
                    return ([index, item]);
                }),
            });
        }

    }, [items, category]);
};
