import TileMap from "../../TileMap";
import {
    BitDirections,
    bitTileSize,
    CONTAINER_SCALE,
    MAX_TILE_HEIGHT, MAX_TILE_WIDTH,
    TerrainTypes,
    AUTO_TILE_RENDERING_SIZE, TILE_SIZE, AutoTileTypes, TileTypes
} from "../../Types";
import TileGrid from "../../Grid";
import AutoTile from "./AutoTile";
import WonEngine, {RENDER_TYPE} from "../../index";
import {StageRenderer} from "../../StageRenderer";
import AutoTileGenerator from "./AutoTileGenerator";
import TileFragmentSelector from "./TileFragmentSelector";
import GeneratedAutoTileView from "./GeneratedAutoTileView";


export default class AutoTileRenderer extends StageRenderer {
    graphics: PIXI.Graphics = new PIXI.Graphics();
    container: PIXI.Container = new PIXI.Container();
    bitTileContainer: PIXI.Container = new PIXI.Container();
    autoTilePaletteContainer: PIXI.Container = new PIXI.Container();


    bitTiles: Object = {};
    autoTiles: Object = {};
    fragments: Object = {};
    autoTileTextures = {};
    coords: PIXI.Point = new PIXI.Point();
    autoTileEditSprite: PIXI.Sprite = new PIXI.Sprite();

    maxTileCoordX: number;
    maxTileCoordY: number;

    isDownedContainer = false;
    paintedTiles = [];
    autoTileData = [];
    mainTexture: PIXI.Texture;

    // splitTileTextureMap을 담은 리스트.
    splitTileTextureList: any[] = [];
    // 현재 렌더링 되고있는 splitTileTextureMap.
    renderingBitTextures = null;

    constructor() {
        super();
    }

    static IsAutoTile(entity) {
        // if (!entity?.tileType) {
        //     console.dir(entity);
        // }
        return entity?.tileType === "AUTO_TILE"
        // return entity?.terrainType === TerrainTypes.WALL;
    }

    static GetAutoTileMapIndex(itemData) {
        const {texture} = itemData;
        let autoTileIndex;

        if (texture) {
            autoTileIndex = Math.floor(texture.coords[1] / 3);
        }

        // if (texture) {
        //     autoTileIndex = Math.floor(texture.coords[1] / 3);
        // } else {
        //     autoTileIndex = itemData.autoTileIndex;
        // }


        return autoTileIndex;
    }

    setRenderingBitTextures(index) {
        if (this.splitTileTextureList[index]) {
            this.renderingBitTextures = this.splitTileTextureList[index];
        }
    }

    clearTiles() {
        for (let y = 0; y < this.maxTileCoordY; y++) {
            for (let x = 0; x < this.maxTileCoordX; x++) {
                const autoTile = this.autoTiles[`${x}_${y}`];
                if (autoTile) {
                    autoTile.clearMask();
                }
            }
        }
    }

    invertTiles() {
        for (let y = 0; y < this.maxTileCoordY; y++) {
            for (let x = 0; x < this.maxTileCoordX; x++) {
                const autoTile = this.autoTiles[`${x}_${y}`];
                if (autoTile) {
                    autoTile.invertMask();
                }
            }
        }
        this.paintedTiles = [];
    }

    LoadTiles() {
        const {autoTileGenerator, autoTileData} = WonEngine.GetInstance();
        const newData = {};

        for (let i = 0; i < autoTileData.keys.length; i++) {
            newData[autoTileData.keys[i]] = autoTileData.values[i];
        }

        // 비트 활성화.
        for (const [key, autoTileBitValue] of Object.entries(newData)) {
            const autoTile = this.autoTiles[key];

            if (autoTile) {
                for (let y = 0; y < 3; y++) {
                    for (let x = 0; x < 3; x++) {
                        if (Number(autoTileBitValue) & BitDirections[`${x}_${y}`].bit) {
                            autoTile.bitMask(x, y, 1);
                        }
                    }
                }
            }
        }

        // 비트타일 Rectangle 렌더링.
        for (const [key, autoTile] of Object.entries(this.autoTiles)) {
            this.bitTiles[`${autoTile.bit}`] = autoTile;

            const bitTile = this.bitTiles[`${autoTile.bit}`];

            if (!this.autoTileTextures[`${autoTile.bit}`]) {
                this.autoTileTextures[`${autoTile.bit}`] = new PIXI.Texture(this.mainTexture.baseTexture,
                    new PIXI.Rectangle(
                        bitTile.mapCoordX * AUTO_TILE_RENDERING_SIZE,
                        bitTile.mapCoordY * AUTO_TILE_RENDERING_SIZE,
                        AUTO_TILE_RENDERING_SIZE, AUTO_TILE_RENDERING_SIZE))
            }
        }

        // generated 된 텍스쳐를 개별저장한다.
        for (let k = 0; k < autoTileGenerator.generatedAutoTileTextures.length; k++) {
            const splitTileTextureMap = [];

            for (const [key, autoTile] of Object.entries(this.autoTiles)) {
                this.bitTiles[`${autoTile.bit}`] = autoTile;
                const bitTile = this.bitTiles[`${autoTile.bit}`];

                const srcRect = new PIXI.Rectangle(
                    bitTile.mapCoordX * TILE_SIZE,
                    bitTile.mapCoordY * TILE_SIZE,
                    TILE_SIZE, TILE_SIZE);

                splitTileTextureMap[`${autoTile.bit}`] = new PIXI.Texture(autoTileGenerator.generatedAutoTileTextures[k], srcRect)

            }

            this.splitTileTextureList.push(splitTileTextureMap);
        }

        this.renderingBitTextures = this.splitTileTextureList[0];
    }


    loadMainTexture(textureName: string) {
        const loader = PIXI.Loader.shared;
        this.mainTexture = loader.resources[textureName].texture

        this.maxTileCoordX = this.mainTexture.width / AUTO_TILE_RENDERING_SIZE;
        this.maxTileCoordY = this.mainTexture.height / AUTO_TILE_RENDERING_SIZE;

        return this.mainTexture;
    }

    initAutoTiles() {
        if (Object.keys(this.autoTiles).length > 0) return;

        const _bitTileSize = 8 / 3;

        for (let y = 0; y < this.maxTileCoordY; y++) {
            this.autoTileData[y] = [];
            for (let x = 0; x < this.maxTileCoordX; x++) {
                const autoTile = new AutoTile(x, y, 8);
                autoTile.mapCoordX = x;
                autoTile.mapCoordY = y;

                this.autoTiles[`${x}_${y}`] = autoTile;
                // Add BitTile.
                for (let ty = 0; ty < 3; ty++) {
                    for (let tx = 0; tx < 3; tx++) {
                        const bitTile = new PIXI.Sprite(PIXI.Texture.WHITE);

                        bitTile.x = tx * _bitTileSize;
                        bitTile.y = ty * _bitTileSize;
                        bitTile.width = _bitTileSize;
                        bitTile.height = _bitTileSize;
                        bitTile.alpha = 0;
                        bitTile.tint = 0x0000FF;
                        autoTile.addChild(bitTile);
                        autoTile.setBitTile(tx, ty, bitTile);
                    }
                }

                // this.container.addChild(autoTile);
                // this.stage.addChild(autoTile);

                // this.autoTilePaletteContainer.addChild(autoTile);
            }
        }
    }

    handlePointerDown() {
        console.log('pointerdown');
    }

    init() {
        const {autoTileGenerator} = this.wonEngine;

        const generatedAutoTileTextures = [
            ...autoTileGenerator.generateAutoTileTextures(AutoTileTypes.AutoTileTable2, "3x3AutoTiles", 5, 0, TILE_SIZE * 3),
            ...autoTileGenerator.generateAutoTileTextures(AutoTileTypes.AutoTileTable, "16x16autoTile", 3, TILE_SIZE * 2, 0)
        ];

        for (const generatedAutoTileTexture of generatedAutoTileTextures) {
            // Create Sprite.
            const generatedAutoTiles = new PIXI.Sprite(generatedAutoTileTexture);
            // generatedAutoTiles.scale.set(CONTAINER_SCALE, CONTAINER_SCALE);
            // generatedAutoTiles.y = 200;

            autoTileGenerator.generatedAutoTileTextures.push(generatedAutoTileTexture);
            autoTileGenerator.generatedAutoTileSprites.push(generatedAutoTiles);
        }

        this.mainTexture = autoTileGenerator.generatedAutoTileTextures[0];
        this.maxTileCoordX = this.mainTexture.width / TILE_SIZE;
        this.maxTileCoordY = this.mainTexture.height / TILE_SIZE;

        this.initAutoTiles();
        this.LoadTiles();
    }

    _load(props: any) {
        const {selectedItem} = props;
        let texture = this.mainTexture;
        // const autoTileEditTextureWidth = 8 * AUTO_TILE_RENDERING_SIZE;
        // const autoTileEditTextureHeight = 8 * AUTO_TILE_RENDERING_SIZE;

        // Add MinimizedAutoTiles.
        const tileFragmentSelector = new TileFragmentSelector("3x3AutoTiles");
        const generatedAutoTileView = new GeneratedAutoTileView(texture, tileFragmentSelector);

        this.stage.addChild(generatedAutoTileView);
        tileFragmentSelector.attach(this.stage);
    }

    renderBitTiles(globalMousePosition) {
        if (this.isDownedContainer) {
            const key = `${this.coords.x}_${this.coords.y}`;
            const autoTile = this.autoTiles[key];

            if (autoTile) {
                const autoTileLocalPos = autoTile.toLocal(globalMousePosition);
                const bitTileCoordX = Math.floor(autoTileLocalPos.x / bitTileSize);
                const bitTileCoordY = Math.floor(autoTileLocalPos.y / bitTileSize);
                const bitTile = autoTile.getBitTile(bitTileCoordX, bitTileCoordY);

                const paintedTileKey = `${this.coords.x}_${this.coords.y}_${bitTileCoordX}_${bitTileCoordY}`;
                if (bitTile && !this.paintedTiles[paintedTileKey]) {
                    autoTile.bitMask(bitTileCoordX, bitTileCoordY);
                    this.paintedTiles[paintedTileKey] = bitTile;
                }
            }
        }
    }

    render() {
        const globalMousePosition = WonEngine.GetInstance().renderer.plugins.interaction.mouse.global;
        // toLocal로 가져오면 컨테이너가 scale되었더라도 원래포지션을 가져온다.
        // const mousePosition = this.tileMapContainer.toGlobal(globalMousePosition)

        // const mousePosition = this.tileMapContainer.toLocal(globalMousePosition);

        // mousePosition.x = Math.floor(mousePosition.x);
        // mousePosition.y = Math.floor(mousePosition.y);

        // this.coords.x = Math.floor(mousePosition.x / AUTO_TILE_RENDERING_SIZE);
        // this.coords.y = Math.floor(mousePosition.y / AUTO_TILE_RENDERING_SIZE);

        // this.renderBitTiles(globalMousePosition);
        // this.renderTileMapContainer(globalMousePosition);
        // this.renderDebugText(globalMousePosition);
    }
}
