import React, {useEffect} from 'react';
import ToolTemplate from "../ToolTemplate/ToolTemplate";
import {useTextureUpdate} from "../../hooks";
import BackPackEditor from "../../jsonSchema/fields/BackPackEditor";
import {saveSkills} from "../../DataRequester";
import {CardTypes, TextureKeyTypes} from "../../WonEngine/Types";
import TextureSelector from "../../jsonSchema/fields/TextureSelector/TextureSelector";
import SkillSelector from "../../jsonSchema/fields/SkillSelector";
import ItemSelector from "../../jsonSchema/widgets/ItemSelector";
import SkillTypeSelector from "../../jsonSchema/widgets/CustomTypeSelector";
import ScriptEditor from "../../jsonSchema/widgets/ScriptEditor/ScriptEditor";
import IntlInput, {DefaultOptions, generateDefaultInputValue} from "../../jsonSchema/widgets/IntlInput";

const DEFAULT_SKILL_FORM_DATA = {
    "name_kr": "아이템 한국어 이름",
    "name_en": "item english name",
    "desc_kr": "한국어 설명",
    "desc_en": "English description",
}

const defaultFormData = {
    name: "",
    script: "",
    localizedText: DEFAULT_SKILL_FORM_DATA,
    entityType: "NONE",
}

const widgets = {
    // SkillSelector
    ItemSelector,
    SkillTypeSelector,
    ScriptEditor,
}

const fields = {
    BackPackEditor,
    TextureSelector,
    IntlInput

}

const EntityType = [
    {
        name: "NONE",
    },
    {
        name: "STACK",
    },
    {
        name: "SKILL",
    },
    {
        name: "EFFECT",
    },
]

const itemSchema = {
    "type": "object",
    "properties": {
        "name": {
            "type": "string"
        },
        "script": {
            "type": "string"
        },
        "localizedText": {
            "type": "object",
        },
        "entityType": {
            "type": "string",
        },
        "skillType": {
            "type": "string",
        },
        "texture": {
            "type": "object",
            "properties": {
                "coords": {
                    "type": "array"
                },
                "size": {
                    "type": "array",
                },
                // "affectCoordsList": {
                //     "type": "array"
                // },
            }
        },
    }
}

const uiSchema = {
    "ui:order": [
        "texture",
        "name",
        "entityType",
        "skillType",
        "localizedText",
        "script",
    ],
    "script": {
        "ui:widget": "ScriptEditor",
    },
    "localizedText": {
        "ui:field": "IntlInput",
    },
    "entityType": {
        "ui:widget": "SkillTypeSelector",
        "ui:options": {
            "items": EntityType,
        }
    },
    "skillType": {
        "ui:widget": "SkillTypeSelector",
        "ui:options": {
            "items": [
                {
                    name: "ACTIVE",
                },
                {
                    name: "PASSIVE",
                }
            ],
        }
    },

    "texture": {
        "ui:field": "TextureSelector",
        "ui:options": {
            "textureKeyType": TextureKeyTypes.ITEM,
            // "textureName": "weapons",
            "textureName": "skill-icons",
            // "useTextureEffectEditor": true,
        }
    }
}

export default props => {
    const {items, setItems} = props;

    useEffect(() => {
        // (async () => {
        //
        //     const newItems = items.map(item => {
        //         if (!item.localizedText) {
        //             item.localizedText = {
        //                 ...DEFAULT_SKILL_FORM_DATA,
        //             }
        //         }
        //
        //         return item;
        //     })
        //     await saveSkills(newItems);
        //
        // })()
    }, [])

    const handleClickSave = async () => {

        const newItems = items.map(item => {
            if (item.description) {
                delete item.description;
            }

            return item;
        })

        await saveSkills(newItems);

        // await saveSkills({
        //     items,
        // });
    }

    useTextureUpdate(items, setItems);

    return <ToolTemplate name={"skillData"} items={items} setItems={setItems}
                         fields={fields} widgets={widgets}

                         category={{
                             // key: "tier",
                             // list: [
                             //     0,
                             //     1,
                             //     2,
                             //     3,
                             // ],

                             key: "entityType",
                             list: EntityType.map(
                                 item => item.name
                             ),

                             // key: "skillType",
                             // list: [
                             //     "ACTIVE",
                             //     "PASSIVE",
                             // ],
                         }}

                         itemSchema={itemSchema} uiSchema={uiSchema}
                         onClickSave={handleClickSave} defaultFormData={defaultFormData}
        // itemToolTemplate={ItemToolTemplate}
    />
}
