import React from 'react';

export default (props) => {
    const {label, value, onChange, options} = props;
    const {enumOptions} = options;

    const handleClick = (option) => {
        onChange(option.value)
    };

    return <div style={styles.OneOfSelector}>
        {/*{*/}
        {/*    label && <div style={styles.label}>{label}</div>*/}
        {/*}*/}
        <div style={styles.itemWrapper}>
            {enumOptions.map(option =>
                <div key={option.value} style={Object.assign({}, styles.item,
                    option.value === value && styles.itemSelect)}
                     onClick={handleClick.bind(this, option)}>
                    {option.label}
                </div>)}
        </div>
    </div>
}

const styles = {
    OneOfSelector: {
        userSelect: 'none',
        marginTop: '0.5em',
        // display: 'flex',
        // flexDirection: 'column',
        // margin: '1em 0 1em',
    },
    itemWrapper: {
        display: 'flex',
        flexDirection: 'row',
    },
    itemSelector: {
        userSelect: 'none',
        display: 'flex',
        flexDirection: 'column',
        margin: '1em 0 1em',
    },
    label: {
        marginBottom: "0.5em",
    },
    item: {
        width: '100px',
        height: '40px',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        cursor: 'pointer',

        backgroundColor: 'lightGray',
        opacity: 0.3,
        textShadow: '2px 2px 2px white',
        fontWeight: 'bold',

        padding: '0.5em',
        boxSizing: 'border-box',
        margin: "-1px 0 0 -1px",
        border: '1px solid black',
    },
    itemSelect: {
        opacity: 1,
        outline: '2px solid black',
        color: 'orange',
        zIndex: 1,
    }
}
