export default class Rectangle extends PIXI.Rectangle {
    constructor(x = 0, y = 0, width = 0, height = 0) {
        super(x, y, width, height);

        // this.edges = [
        //     new Line(x, y, x + width, height),
        //     new Line(x + width, y, x + width, y + height),
        //     new Line(x + width, y + height, x, y + height),
        //     new Line(x, y + height, x, y),
        //
        // ];
    }

    // hasEdge(edge) {
    //     for (const edge2 of this.edges) {
    //         if (edge2.equals(edge)) {
    //             return true;
    //         }
    //     }
    //     return false;
    // }

    set(x, y, width, height) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
    }

    contains(x, y) {
        const points = [
            {x: this.x, y: this.y},
            {x: this.x + this.width, y: this.y},
            {x: this.x + this.width, y: this.y + this.height},
            {x: this.x, y: this.y + this.height},
        ];
        let inside = false;

        for (let i = -1, j = points.length - 1; ++i < points.length; j = i) {
            const ix = points[i].x;
            const iy = points[i].y;

            const jx = points[j].x;
            const jy = points[j].y;

            if (((iy <= y && y < jy) || (jy <= y && y < iy)) && (x < (jx - ix) * (y - iy) / (jy - iy) + ix)) {
                inside = !inside;
            }
        }

        return inside;
    }

    intersect(rectangle) {
        if (this.width <= 0 || this.height <= 0 || rectangle.width <= 0 || rectangle.height <= 0) {
            return false;
        }

        return !(
            this.right < rectangle.x ||
            this.bottom < rectangle.y ||
            this.x > rectangle.right ||
            this.y > rectangle.bottom);
    }
}
