import TileGrid from "../../Grid";
import WonEngine from "../../index";
import GameObject from "../../GameObject";

export default class TileFragmentSelector extends GameObject {
    textureName: string = null;
    fragmentSprite: PIXI.Sprite = new PIXI.Sprite(PIXI.Texture.WHITE);
    selectedCoords: PIXI.Point = new PIXI.Point();

    constructor(textureName) {
        super(WonEngine.GetTexture(textureName));

        this.textureName = textureName;

        const innerGrid = new TileGrid(16 * 5, 16 * 3, 16 / 2,
            graphics => graphics.lineStyle(0.5, 0xFFFFFF, 1));
        const outerGrid = new TileGrid(16 * 5, 16 * 3, 16,
            graphics => graphics.lineStyle(0.5, 0x000000, 1));
        this.addChild(innerGrid)
        this.addChild(outerGrid)

        this.scale.set(7, 7);

        this.interactive = true;

        this.hitArea = new PIXI.Rectangle(0, 0, 16 * 5, 16 * 3);

        this.on('pointermove', this.handlePointerMove);
        this.on('pointerdown', this.handlePointerDown);

        this.fragmentSprite.scale = new PIXI.Point(4, 4);
        const fragmentSize = 32;
        this.fragmentSprite.width = fragmentSize;
        this.fragmentSprite.height = fragmentSize;
    }

    attach(parent) {
        parent.addChild(this);
        parent.addChild(this.fragmentSprite);
    }

    handlePointerMove(e) {
        const globalPos = e.data.global;
        this.fragmentSprite.position.copyFrom(globalPos);
    }

    handlePointerDown(e) {
        const baseTexture = WonEngine.GetTexture(this.textureName).baseTexture;
        const mousePos = this.toLocal(e.data.global);

        this.selectedCoords.set(
            Math.floor(mousePos.x / 8),
            Math.floor(mousePos.y / 8)
        );

        this.fragmentSprite.texture = new PIXI.Texture(baseTexture, new PIXI.Rectangle(
            this.selectedCoords.x * 8, this.selectedCoords.y * 8, 8, 8
        ));

        this.fragmentSprite.width = 32;
        this.fragmentSprite.height = 32;
    }

    update() {
    }
}
