import React from 'react';
import {AttackTypes, CardTypes, ItemTypes} from "../../WonEngine/Types";

export default (props) => {
    const {label, value, onChange} = props;
    return <div>
        <div style={{
            display: 'flex',
            flexDirection: 'row',
            cursor: 'pointer',
            // userSelect: 'none',
        }}>
            {
                Object.entries(CardTypes).map(([key, value]) => ({
                    name: value,
                    value,
                })).map((itemType, index) =>
                    <div key={itemType.name} style={Object.assign({}, styles.name,
                        value === itemType.value && styles.selected)} onClick={() => onChange(itemType.value)}>
                        {itemType.name.charAt(0).toUpperCase() + itemType.name.slice(1).toLowerCase()}
                    </div>)
            }
        </div>
    </div>
}

const styles = {
    name: {
        userSelect: 'none',
        width: '75px',
        height: '40px',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: 'lightGray',
        opacity: 0.3,
        textShadow: '2px 2px 2px white',
        fontWeight: 'bold',
        // fontSize: "0.7em",
    },
    selected: {
        opacity: 1,
        outline: '2px solid black',
        color: 'orange',
    }
}
