import ColorPalette from "../../jsonSchema/widgets/ColorPalette";
import {PARTS_CONFIG} from "./config";
import ItemSelector from "../../jsonSchema/widgets/ItemSelector";
import {EntityTypes} from "../../WonEngine/Types";

export const schema = {
    // "title": "Character",
    // "description": "My description",
    "type": "object",
    "properties": {
        "name": {
            "type": "string"
        },

        "type": {
            "type": "number"
        },

        base: {
            type: "integer",
            maximum: PARTS_CONFIG.base.max,
        },
        head: {
            type: "integer",
            maximum: PARTS_CONFIG.head.max,
        },
        face: {
            type: "integer",
            maximum: PARTS_CONFIG.face.max,
        },

        eyes: {type: "number"},
        body: {type: "number"},
        hair: {type: "number"},
        suit: {type: "number"},
        item: {type: "number"},
    },

    "required": ["name"]
};
export const paletteSchema = {
    "ui:widget": "ColorPalette",
    "ui:options": {
        label: false,
    }
};

export const uiSchema = {
    type: {
        "ui:widget": "ItemSelector",
        "ui:options": {
            items: [
                {
                    name: 'Hero',
                    style: {
                        backgroundColor: 'skyblue',
                    }
                },
                {
                    name: 'Enemy',
                    style: {
                        backgroundColor: 'Firebrick',
                    }
                }
            ],
            label: false,
        }
    },

    base: {
        "ui:widget": "range",
    },
    head: {
        "ui:widget": "range",
    },
    face: {
        "ui:widget": "range",
    },

    eyes: paletteSchema,
    body: paletteSchema,
    hair: paletteSchema,
    suit: paletteSchema,
    item: paletteSchema,
}
export const defaultFormData = {
    itemType: EntityTypes.CHARACTER,
    name: "",
    type: 0,
    base: 0,
    head: 0,
    face: 0,

    eyes: 0,
    body: 0,
    hair: 0,
    suit: 0,
    item: 0,
};
export const widgets = {
    ColorPalette,
    ItemSelector,
};
