import React, {useEffect, useRef, useState} from "react";
import Select from 'react-select';
import AddStatComponent from "./StatEditor/AddStatComponent";

export default props => {
    const {formData, onChange} = props;
    const [options, setOptions] = useState(null);
    const [partOptions, setPartOptions] = useState(null);

    const [selectedOption, setSelectedOption] = useState(null);

    const [selectedPartOption, setSelectedPartOption] = useState(null);
    // const [createdParts, setCreatedParts] = useState({});


    useEffect(() => {
        const newPartOption = ["WEAPON", "SPELL", "ARMOR"].map(part => ({
            value: part,
            label: part,
        }))
        setPartOptions(newPartOption);
    }, [])

    const handleAddPart = (selectedPartOption) => {
        console.log(selectedPartOption);

        onChange({
            ...formData,
            [selectedPartOption.value]: []
        });
    }

    const handleRemoveCreatedPart = (removedCreatedPart) => {
        console.log(removedCreatedPart)

        const newCreatedPart = {...formData};

        delete newCreatedPart[removedCreatedPart];

        // let {removedCreatedPart, ...newCreatedPart} = createdParts;

        onChange(newCreatedPart);
    }

    const handleOnChangeStatComponent = (createdPart, newFormData) => {
        onChange({
            ...formData,

            [createdPart]: [
                ...newFormData,
            ]
        });
    }

    // if (!formData) {
    //     return null;
    // }

    return formData && <div style={{
        display: 'flex',
        flexDirection: 'column',
    }}>
        <div className={"control-label"}>SocketStat</div>
        <div style={{
            display: 'flex',
            flexDirection: 'column',
        }}>
            {
                Object.keys(formData).length > 0 && Object.entries(formData).map(([createdPart]) => {
                    // console.log(createdPart);
                    return <div key={createdPart}>
                        <div>
                            {createdPart}
                            <button style={styles.Button}
                                    onClick={handleRemoveCreatedPart.bind(this, createdPart)}>Remove
                            </button>
                        </div>
                        <AddStatComponent formData={formData[createdPart]} socketPart={createdPart}
                                          onChange={handleOnChangeStatComponent.bind(this, createdPart)}/>
                    </div>

                })
            }
        </div>

        <div style={{
            marginTop: '1em',
            display: 'flex',
        }}>
            <Select
                styles={{
                    control: (baseStyles, state) => ({
                        ...baseStyles,
                        width: '200px',
                        // borderColor: state.isFocused ? 'grey' : 'red',
                    }),
                }}
                // defaultValue={selectedOption}
                onChange={(e) => setSelectedPartOption(e)}
                // options={options}
                options={partOptions}
            />

            <button style={styles.Button} onClick={handleAddPart.bind(this, selectedPartOption)}>
                Add part
            </button>
        </div>
    </div>
}

const styles = {
    Button: {
        // userSelect: 'none',
        marginLeft: '1em',
        // height: '3em',
        // width: '150px',
        // height: '70px',
    },
    statLabel: {
        fontSize: "1.2em",
        margin: '0.3em',
        cursor: 'pointer',
        userSelect: 'none',
        padding: '0.3em',
        width: '150px',
        borderBottom: '1px dotted black',
    },
    selectedStatLabel: {
        backgroundColor: 'orange'
    }
}
