import {CardTypes, EntityTypes, ItemSubTypes, ItemTypes, TextureKeyTypes} from "../../WonEngine/Types";
import {textureSchema} from "../TileTool/TileToolSchemas";
import TypeSelector from "../../jsonSchema/widgets/TypeSelector";
import {DEFAULT_FORM_DATA} from "../../jsonSchema/widgets/IntlInput";

export const defaultFormData = {
    tier: 0,
    cost: 0,
    rarity: 0,
    damage: 0,
    throwingDamage: 0,
    throwingRange: 0,
    localizedText: DEFAULT_FORM_DATA,
    socketStats: {},
    materials: [],
};

const defaultProps = {
    "skills": {
        "type": "array"
    },

    "localizedText": {
        "type": "object",
    },
    "cost": {
        "type": "number",
        "minimum": 0,
        "maximum": 30,
    },
    "rarity": {
        "type": "number",
    },
    "canTrigger": {
        "type": "boolean"
    },
    "soundEffect": {
        "type": "string",
    },
    "materials": {
        "type": "array",
    },
    "attackEffect": {
        "type": "string",
        "enum": [
            "1", "2", "3"
        ]
    }
}

const dependencies = {
    "cardType": {
        "oneOf": [
            /*            {
                            "properties": {
                                "cardType": {
                                    "enum": [
                                        CardTypes.BAG
                                    ],
                                },
                                ...defaultProps,
                            },
                        },*/
            {
                "properties": {
                    "cardType": {
                        "enum": [
                            CardTypes.Gem
                        ],
                    },
                    "socketStats": {
                        "type": "object",
                    },
                    ...defaultProps,
                },
            },
            {
                "properties": {
                    "cardType": {
                        "enum": Object.entries(CardTypes).map(([key]) => key)
                            .filter(key => key !== CardTypes.Gem),
                    },
                    "stats": {
                        "type": "array",
                    },
                    ...defaultProps,
                },
            },
        ],
    },
}


export const itemSchema = {
    "type": "object",
    "properties": {
        "name": {
            "type": "string"
        },
        "texture": {
            "type": "object",
            "properties": {
                "coords": {
                    "type": "array"
                },
                "size": {
                    "type": "array",
                },
                "affectCoordsList": {
                    "type": "array"
                },
            }
        },
        "tier": {
            "type": "number",
        },
        "cardType": {
            "type": "string",
        },
        "castingCost": {
            "type": "number",
        },
        "attackSpeed": {
            "type": "number",
        },

    },
    dependencies
};

console.log(itemSchema)

export const uiSchema = {
    "ui:order": [
        "texture",
        "name",
        "attackEffect",

        "localizedText",
        "cardType",
        // "canTrigger",
        "cost",
        "materials",
        "stats",
        "socketStats",
        "castingCost",
        "soundEffect",
        "script",
        "skills",
        "attackSpeed",
        "affectCoordsList",
        "subType",
        "*",
    ],
    "attackEffect": {
        "ui:widget": "AttackEffectSelector"
    },
    // "name": {
    //     "ui:widget": "IntlInput",
    // },

    "localizedText": {
        "ui:field": "IntlInput",
    },

    "soundEffect": {
        "ui:widget": "SoundEffectSelector"
    },
    "cardType": {
        "ui:widget": "TypeSelector"
    },
    "socketStats": {
        "ui:field": "SocketStatEditor"
    },
    "stats": {
        "ui:field": "StatEditor"
    },
    "skills": {
        "ui:field": "SkillSelector",
        "ui:options": {
            "itemType": "Skill"
        }
    },
    "affectCoordsList": {
        "ui:field": "ItemEffectEditor",
    },
    "materials": {
        "ui:field": "MaterialSelector",
        "ui:options": {
            "itemType": "Card"
        }
    },
    "cost": {
        "ui:widget": "range"
    },
    "castingCost": {
        "ui:widget": "range"
    },
    "rarity": {
        "ui:widget": "RaritySelector",
        "ui:options": {
            label: false,
        }
    },
    "texture": {
        "ui:field": "TextureSelector",
        "ui:options": {
            "textureKeyType": TextureKeyTypes.ITEM,
            "textureName": "weapons",
            "useTextureEffectEditor": true,
            "tintColor": true,
        }
    }
};
