import Manager from "./Manager";
import Tile from "../entities/Tile";
import Item from "../entities/Item";
import {EntityTypes, TILE_SIZE, UNIT_SIZE} from "../Types";
import WonEngine from "../index";
import SpriteRenderer from "../components/SpriteRenderer";


export default class ItemMgr extends Manager {

    generateTexture(itemData) {
        const generatedTexture = WonEngine.GetTexture(itemData.texture.textureName,
            new PIXI.Rectangle(itemData.texture.coords[0] * UNIT_SIZE, itemData.texture.coords[1] * UNIT_SIZE,
                itemData.texture.size[0] * 16, itemData.texture.size[1] * 16))

        return generatedTexture;
    }

    add(itemData, coordX, coordY) {
        const {entityMgr} = this.wonEngine.managers;
        const {size} = itemData.texture;

        const item = new Item(itemData, coordX, coordY, size[0] * 16, size[1] * 16);
        const entity = entityMgr.getEntity(itemData.itemType, coordX, coordY);
        if (entity) return null;

        item.getComponent(SpriteRenderer).sprite.rotation = Math.PI * 0.5;
        entityMgr.setEntity(EntityTypes.ITEM, item, coordX, coordY);

        const texture = this.generateTexture(itemData);
        item.getComponent(SpriteRenderer).setTexture(texture);

        const sr = item.getComponent(SpriteRenderer);
        sr.sprite.anchor.set(0.5, 0.5);
        sr.sprite.position.x += TILE_SIZE * 0.5;
        sr.sprite.position.y += TILE_SIZE * 0.5;
        return item;
    }

    remove() {

    }
}
