import React, {useCallback, useEffect, useRef} from 'react';
import TileGrid from "../../../WonEngine/Grid";
import WonEngine from "../../../WonEngine";

const MAX_WIDTH = 10, MAX_HEIGHT = 10;
const TILE_SIZE = 16;
const STAGE_WIDTH = MAX_WIDTH * TILE_SIZE;
const STAGE_HEIGHT = MAX_HEIGHT * TILE_SIZE
const STAGE_SCALE = 2;

const MOUSE_RIGHT_BUTTON = 0
const MOUSE_LEFT_BUTTON = 2

class EffectRect extends PIXI.Sprite {
    constructor(coordX = 0, coordY = 0, type = 0) {
        super(PIXI.Texture.WHITE);

        this.width = TILE_SIZE;
        this.height = TILE_SIZE;
        this.position.set(coordX * TILE_SIZE, coordY * TILE_SIZE);
        this.interactive = true;
        this.buttonMode = true;
        this.type = type
        this.alpha = 0.5


        if (type === 2) this.tint = 0x00FF00;
        if (type === 0) this.tint = 0x0000FF;

        this.on('pointerdown', (e) => {
            const removedEffectCoords = new PIXI.Point(
                this.position.x / TILE_SIZE,
                this.position.y / TILE_SIZE
            );

            const itemEffectEditorEngine = ItemEffectEditorEngine.GetInstance();

            const parent = this.parent;
            if (parent) {
                parent.removeChild(this);
            }

            this.destroy();

            if (itemEffectEditorEngine) {
                removedEffectCoords.x -= itemEffectEditorEngine.sprite.x / TILE_SIZE;
                removedEffectCoords.y -= itemEffectEditorEngine.sprite.y / TILE_SIZE;
                itemEffectEditorEngine.render();
                itemEffectEditorEngine.onEffectRemoved(removedEffectCoords, type);
            }
            e.stopPropagation();
        });
    }
}

let _itemEffectEditorEngine = null;

class ItemEffectEditorEngine {
    renderer
    stage
    grid
    sprite
    isInitialized = false
    effectContainer = new PIXI.Container();
    onPointerDown = () => {
    }


    static GetInstance() {
        return _itemEffectEditorEngine;
    }

    constructor() {
        PIXI.utils.skipHello()

        this.renderer = new PIXI.Renderer({
            width: MAX_WIDTH * TILE_SIZE * STAGE_SCALE,
            height: MAX_HEIGHT * TILE_SIZE * STAGE_SCALE,
            backgroundColor: 0x1099bb,
            antialias: false,
            // roundPixels: true,
            // view,
        });
        this.stage = new PIXI.Container()
        _itemEffectEditorEngine = this;
    }

    clearEffectList() {
        this.effectContainer.removeChildren().forEach(child => child.destroy());
    }

    getSpriteCoords() {
        return new PIXI.Point(
            Math.floor(this.sprite.x / TILE_SIZE),
            Math.floor(this.sprite.y / TILE_SIZE)
        );
    }

    loadEffectCoordsList(effectDataList = [], type) {

        if (effectDataList.length === 0) return

        const spriteCoords = new PIXI.Point(
            Math.floor(this.sprite.x / TILE_SIZE),
            Math.floor(this.sprite.y / TILE_SIZE)
        )

        for (const effectData of effectDataList) {
            const effectRect = new EffectRect(
                effectData.x + spriteCoords.x,
                effectData.y + spriteCoords.y,
                type
            );
            this.effectContainer.addChild(effectRect);
        }
    }

    GetTileCoordsFromMouse(e) {
        const newPosition = e.data.getLocalPosition(this.stage);
        const coords = new PIXI.Point(
            Math.floor(newPosition.x / TILE_SIZE),
            Math.floor(newPosition.y / TILE_SIZE)
        )

    }

    addEffectRect(coords, type) {
        const newSprite = new EffectRect(coords.x, coords.y, type);
        this.effectContainer.addChild(newSprite);
        this.render();
    }

    init() {

        const grid = new TileGrid(STAGE_WIDTH, STAGE_HEIGHT, TILE_SIZE,
            // graphics => graphics.lineStyle(0.5, 0xFFFFFF, 0.3)
        );

        const texture = PIXI.Loader.shared.resources["weapons"].texture;
        this.sprite = new PIXI.Sprite(PIXI.Texture.EMPTY);

        this.sprite.x = Math.floor((MAX_WIDTH - 1) / 2) * TILE_SIZE;
        this.sprite.y = Math.floor((MAX_HEIGHT - 1) / 2) * TILE_SIZE;

        this.stage.addChild(this.sprite)
        this.stage.addChild(grid)
        this.stage.scale.set(STAGE_SCALE, STAGE_SCALE)

        this.stage.hitArea = new PIXI.Rectangle(0, 0, STAGE_WIDTH, STAGE_HEIGHT);

        this.stage.interactive = true;

        this.stage.on('pointerdown', e => {
            const button = e.data.button;
            const newPosition = e.data.getLocalPosition(this.stage);
            const coords = new PIXI.Point(
                Math.floor(newPosition.x / TILE_SIZE),
                Math.floor(newPosition.y / TILE_SIZE)
            )


            const newSprite = new EffectRect(coords.x, coords.y, button);
            this.effectContainer.addChild(newSprite);

            this.render();

            if (this.onPointerDown) {
                const convertedCoords = new PIXI.Point()
                this.sprite.position.copyTo(convertedCoords);

                convertedCoords.x /= TILE_SIZE;
                convertedCoords.y /= TILE_SIZE;

                this.onPointerDown(new PIXI.Point(
                    coords.x - convertedCoords.x,
                    coords.y - convertedCoords.y,
                ), button);
            }
        });

        this.stage.addChild(this.effectContainer);
        this.renderer.render(this.stage)

        this.isInitialized = true;
    }

    render() {
        this.renderer.render(this.stage);
    }


}

const itemEffectEditorEngine = new ItemEffectEditorEngine();
export default (props) => {
    const {onChange, textureData, textureKeyType} = props;
    const {coords, size, cells, affectCoordsList} = textureData;
    const canvasWrapperRef = useRef(null);

    const onPointDown = (coords, button) => {
        const newAffectCoordsList = [...(affectCoordsList || [])];
        const newCells = [...(cells || [])];

        if (button === 0) {
            newAffectCoordsList.push(coords)
        } else if (button === 2) {
            newCells.push(coords)
        }

        onChange({
            ...textureData,
            affectCoordsList: newAffectCoordsList,
            cells: newCells,
        });
    }

    const onEffectRemoved = (removedItemCoords, type) => {
        const newAffectCoordsList = [
            ...affectCoordsList || [],
        ];
        const newCells = [
            ...cells || [],
        ];

        const removeElementByCoords = (elementList, coords) => {
            let foundElementIndex = elementList.findIndex((ele) =>
                ele.x === coords.x && ele.y === coords.y)

            if (foundElementIndex !== -1) {
                elementList.splice(foundElementIndex, 1);
            }
        }

        if (type === MOUSE_LEFT_BUTTON) {
            removeElementByCoords(newAffectCoordsList, removedItemCoords)

        } else if (type === MOUSE_RIGHT_BUTTON) {
            removeElementByCoords(newCells, removedItemCoords)
        }

        onChange({
            ...textureData,
            affectCoordsList: newAffectCoordsList,
            cells: newCells,
        });
    }

    const handleClickClear = () => {
        itemEffectEditorEngine.clearEffectList();

        onChange({
            ...textureData,
            affectCoordsList: [],
            cells: [],
        });
    }

    const handleClickRegenerateCells = () => {
        itemEffectEditorEngine.clearEffectList();
        itemEffectEditorEngine.loadEffectCoordsList(affectCoordsList, 2);

        const spriteCoords = itemEffectEditorEngine.getSpriteCoords();

        let newCells = []

        for (let y = 0; y < size[1]; y++) {
            for (let x = 0; x < size[0]; x++) {
                itemEffectEditorEngine.addEffectRect(new PIXI.Point(
                    x + spriteCoords.x,
                    y + spriteCoords.y
                ), 0)
                newCells.push(new PIXI.Point(x, y,));
            }
        }

        onChange({
            ...textureData,
            cells: newCells,
        });
    }

    useEffect(() => {
        itemEffectEditorEngine.clearEffectList();
        itemEffectEditorEngine.loadEffectCoordsList(affectCoordsList, 2);
    }, [coords, size]);

    useEffect(() => {
        // 마우스 오른쪽 컨텍스트 메뉴 안뜨게하기.
        canvasWrapperRef.current.addEventListener('contextmenu', function (e) {
            e.preventDefault();
        }, false);

        if (!itemEffectEditorEngine.isInitialized) {
            itemEffectEditorEngine.init()
        }
        canvasWrapperRef.current.appendChild(itemEffectEditorEngine.renderer.view);
    }, [])

    useEffect(() => {
        if (itemEffectEditorEngine.isInitialized) {
            itemEffectEditorEngine.clearEffectList();
            itemEffectEditorEngine.loadEffectCoordsList(cells, 0);
            itemEffectEditorEngine.loadEffectCoordsList(affectCoordsList, 2);
        }
    }, [cells, affectCoordsList])

    useEffect(() => {
        itemEffectEditorEngine.onPointerDown = onPointDown;
    }, [onPointDown])
    useEffect(() => {
        itemEffectEditorEngine.onEffectRemoved = onEffectRemoved
    }, [onEffectRemoved])

    useEffect(() => {
        if (!textureData) {
            console.warn("textureData is null!");
            return;
        }
        if (Object.keys(textureData).length !== 0) {
            const {textureMgr} = WonEngine.GetInstance().managers;
            const {textureName, coords, size} = textureData

            const textureKey = `${textureName}_${coords[0]}_${coords[1]}_${size[0]}_${size[1]}`;

            const newTexture = textureMgr.get(textureKeyType, textureKey);
            if (newTexture) {
                itemEffectEditorEngine.sprite.texture = newTexture;
                itemEffectEditorEngine.render();
            }
        }
    }, [textureData])

    return <div style={styles.ItemEffectEditor}>
        <button onClick={handleClickRegenerateCells.bind(this)}>Regenerate cells</button>
        <button onClick={handleClickClear.bind(this)}>Clear</button>
        <div ref={canvasWrapperRef}/>
    </div>
}

const styles = {
    ItemEffectEditor: {
        marginLeft: '3em',
    }
}
