import React from 'react';

export const Rarities = [
    {
        name: 'normal',
        color: "#FFFFFF"
        // color: 'darkGray',
    },
    {
        name: 'socket',
        color: "#A9A9A9"
        // color: 'darkGray',
    },
    {
        name: 'magic',
        color: "#87CEEB",

        // color: 'skyblue',
    },
    {
        name: 'rare',
        color: "#FFD700"

        // color: 'gold'
    },
    {
        name: 'set',
        color: "#90EE90"

        // color: 'lightGreen',
    },
    {
        name: 'unique',
        color: "#BDB76B",

        // color: 'darkKhaki',
    }
];

export default (props) => {
    const {label, value, onChange} = props;
    return <div>
        <div className={"control-label"}>
            {label}
        </div>
        <div style={{
            display: 'flex',
            flexDirection: 'row',
            cursor: 'pointer',
            // userSelect: 'none',
        }}>
            {
                Rarities.map((rarity, index) =>
                    <div key={rarity.name} style={Object.assign({}, {
                        userSelect: 'none',
                        width: '100px',
                        height: '40px',
                        display: 'flex',
                        justifyContent: 'center',
                        alignItems: 'center',
                        backgroundColor: rarity.color,
                        opacity: 0.3,
                        textShadow: '2px 2px 2px white',
                        fontWeight: 'bold',
                    }, value === index && {
                        opacity: 1,
                        outline: '2px solid black',
                    })} onClick={() => onChange(index)}>
                        {rarity.name}
                    </div>)
            }
        </div>
    </div>
}
