import {CLEAR_COLOR, RESOURCES_PATH} from "./Types";

let _instance = null;

class Basis {
    renderer: PIXI.Renderer;


    constructor() {
        _instance = this;
    }

    static GetInstance() {
        return _instance;
    }

    // {width, height,}: { width: number, height: number }
    _init(config): PIXI.Renderer {
        PIXI.utils.skipHello();
        PIXI.settings["ROUND_PIXELS"] = true;



        this.renderer = new PIXI.Renderer({
            width: config.width || document.documentElement.clientWidth,
            height: config.height || document.documentElement.clientHeight,
            backgroundColor: CLEAR_COLOR,
            // backgroundColor: 0x344a61,
            // backgroundColor: 0x000000,
            // backgroundColor: config.BACKGROUND_COLOR,
            antialias: false,
            // roundPixels: true,
            // view,
        });


        // document.body.appendChild(this.renderer.view);

        return this.renderer;
    }

    async loadResources() {
        return new Promise(resolve => {
            const loader = PIXI.Loader.shared;

            // 리소스가 이미 로딩되었을 경우.
            for (const [key, value] of Object.entries(RESOURCES_PATH)) {
                if (!loader.resources[key]) {
                    loader.add(key, value);
                }
            }

            loader.load(() => {
                for (const attr in loader.resources) {
                    if (!loader.resources[attr].texture) continue;
                    loader.resources[attr].texture.baseTexture.scaleMode = PIXI.SCALE_MODES.NEAREST;

                    console.log(`resource loaded : ${attr}`);
                }
                resolve(true);
            });
        });
    }

}

export default Basis;
