import React, {useEffect, useState} from "react";

const styles = {
    container: {
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        maxHeight: '800px',
        border: '1px solid #ccc',
        borderRadius: '8px',
        overflow: 'hidden'
    },
    header: {
        backgroundColor: '#f5f5f5',
        padding: '16px',
        borderBottom: '1px solid #ddd',
        fontSize: '18px',
        fontWeight: 'bold'
    },
    messagesContainer: {
        flex: 1,
        padding: '16px',
        overflowY: 'auto',
        backgroundColor: '#fafafa'
    },
    message: {
        marginBottom: '16px',
        padding: '12px',
        borderRadius: '8px',
        maxWidth: '70%'
    },
    userMessage: {
        backgroundColor: '#007bff',
        color: 'white',
        marginLeft: 'auto',
        textAlign: 'right'
    },
    assistantMessage: {
        backgroundColor: 'white',
        border: '1px solid #ddd'
    },
    messageLabel: {
        fontSize: '12px',
        fontWeight: 'bold',
        marginBottom: '4px',
        opacity: 0.7
    },
    inputContainer: {
        display: 'flex',
        padding: '16px',
        borderTop: '1px solid #ddd',
        backgroundColor: 'white'
    },
    input: {
        flex: 1,
        padding: '12px',
        border: '1px solid #ddd',
        borderRadius: '4px',
        marginRight: '8px',
        fontSize: '14px'
    },
    button: {
        padding: '12px 24px',
        backgroundColor: '#007bff',
        color: 'white',
        border: 'none',
        borderRadius: '4px',
        cursor: 'pointer'
    }
};

export default () => {
    const [messages, setMessages] = useState([
        { type: 'user', content: '안녕하세요?' },
        { type: 'assistant', content: '안녕하세요! 만나서 반갑습니다. 오늘 어떤 도움이 필요하신가요?' }
    ]);
    const [inputValue, setInputValue] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    const formatMessagesForAPI = (messages) => {
        return messages.map((msg, index) => 
            `Message ${index + 1}:\n\n${msg.content}`
        ).join('\n\n');
    };

    const sendMessage = async () => {
        if (!inputValue.trim() || isLoading) return;

        const newUserMessage = { type: 'user', content: inputValue };
        const updatedMessages = [...messages, newUserMessage];
        setMessages(updatedMessages);
        const currentInput = inputValue;
        setInputValue('');
        setIsLoading(true);

        try {
            const messageContent = formatMessagesForAPI(updatedMessages);
            
            // 실제 공개 API 사용 - JSONPlaceholder와 대화형 AI API 시뮬레이션
            const requestData = {
                title: "Chat Message",
                body: messageContent,
                userId: 1,
                timestamp: new Date().toISOString(),
                userMessage: currentInput
            };
            
            console.log('Sending request:', requestData);
            
            const response = await fetch("https://jsonplaceholder.typicode.com/posts", {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(requestData)
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('API Response:', data);
            
            // 실제 API 응답을 받았으므로 이를 기반으로 응답 생성
            const responseAnalysis = {
                success: true,
                requestId: data.id,
                timestamp: data.timestamp || new Date().toISOString(),
                originalMessage: currentInput
            };
            
            // 실제 API 호출에 성공했다는 것을 보여주는 응답
            const assistantResponse = `✅ 실제 API 호출에 성공했습니다!\n\n` +
                                    `📤 요청 ID: ${responseAnalysis.requestId}\n` +
                                    `📝 원본 메시지: "${responseAnalysis.originalMessage}"\n` +
                                    `⏰ 처리 시간: ${responseAnalysis.timestamp}\n\n` +
                                    `🔗 실제 네트워크 요청이 https://jsonplaceholder.typicode.com/posts 에 성공적으로 전송되었습니다.\n\n` +
                                    `이것은 실제 fetch() 함수를 사용한 비동기 HTTP 요청의 예시입니다. ` +
                                    `실제 Claude API나 다른 AI 서비스를 연동하려면 해당 서비스의 API 키와 엔드포인트가 필요합니다.`;
            
            setMessages([...updatedMessages, { type: 'assistant', content: assistantResponse }]);
            
        } catch (error) {
            console.error('Request failed:', error);
            
            // 에러 발생 시 폴백 메시지
            const fallbackMessage = `죄송합니다. 현재 외부 API에 연결할 수 없습니다. (${error.message})\n\n` +
                                  `입력하신 메시지: "${currentInput}"\n\n` +
                                  `CORS 정책으로 인해 브라우저에서 직접 Claude API에 접근할 수 없습니다. ` +
                                  `실제 사용을 위해서는 백엔드 서버가 필요합니다.`;
            
            setMessages([...updatedMessages, { type: 'assistant', content: fallbackMessage }]);
        } finally {
            setIsLoading(false);
        }
    };

    const handleKeyPress = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
        }
    };

    return (
        <div style={styles.container}>
            <div style={styles.header}>
                Claude Chat
            </div>
            
            <div style={styles.messagesContainer}>
                {messages.map((message, index) => (
                    <div 
                        key={index} 
                        style={{
                            ...styles.message,
                            ...(message.type === 'user' ? styles.userMessage : styles.assistantMessage)
                        }}
                    >
                        <div style={styles.messageLabel}>
                            {message.type === 'user' ? 'You' : 'Claude'}
                        </div>
                        <div>{message.content}</div>
                    </div>
                ))}
                {isLoading && (
                    <div style={{...styles.message, ...styles.assistantMessage}}>
                        <div style={styles.messageLabel}>Claude</div>
                        <div>생각 중...</div>
                    </div>
                )}
            </div>
            
            <div style={styles.inputContainer}>
                <input
                    style={styles.input}
                    type="text"
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                    onKeyPress={handleKeyPress}
                    placeholder="메시지를 입력하세요..."
                    disabled={isLoading}
                />
                <button 
                    style={styles.button} 
                    onClick={sendMessage}
                    disabled={isLoading || !inputValue.trim()}
                >
                    전송
                </button>
            </div>
        </div>
    );
}