import Entity from "../Entity";
import WonEngine from "../index";
import {LayerTypes, UNIT_SIZE} from "../Types";
import Rope from "../components/Rope";
import SpriteRenderer from "../components/SpriteRenderer";

const SPEED = 5;

export class Missile extends Entity {
    sprite = null;
    px = 0;
    py = 0;
    radian = 0;
    range = 500;

    stepRange = 0;
    movedDistance = 0;

    constructor(texture, targetX, targetY) {
        super({});

        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const {layers, globalMousePosition} = mapToolRenderer
        const mousePosition = mapToolRenderer.tileMap.toLocal(globalMousePosition);

        const dx = mousePosition.x - targetX;
        const dy = mousePosition.y - targetY;
        const radian = Math.atan2(dy, dx);
        const px = Math.cos(radian) * SPEED;
        const py = Math.sin(radian) * SPEED;

        this.x = targetX;
        this.y = targetY;
        this.px = px;
        this.py = py;
        this.stepRange = Math.sqrt(dx * dx + dy * dy);
        this.radian = radian;


        this.addComponent(
            new SpriteRenderer(),
            new Rope(this.x, this.y),
        );


        this.init();

        const sprite = this.getComponent(SpriteRenderer).sprite;
        sprite.texture = texture;
        sprite.width = 1 * UNIT_SIZE;
        sprite.height = 2 * UNIT_SIZE;
        sprite.rotation = radian + Math.PI * 0.5;
        sprite.anchor.set(0.5, 0.5);

        // this.getComponent(Rope).rope.rotation = radian + Math.PI * 0.5;
    }

    getCoords() {
        return {
            x: Math.floor(this.x / UNIT_SIZE),
            y: Math.floor(this.y / UNIT_SIZE),
        };
    }

    init() {
        super.init();

        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const {layers, globalMousePosition} = mapToolRenderer
        layers[LayerTypes.MISSILE].addChild(this);
    }

    update() {
        this.x += this.px;
        this.y += this.py;
        this.movedDistance += this.stepRange;

        this.getComponent(Rope).update();
    }

    release() {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const {layers} = mapToolRenderer;

        layers[LayerTypes.MISSILE].removeChild(this);

        this.getComponent(Rope).release();
    }
}
