import {TerrainTypes, TILE_SIZE} from "./Types";
import WonEngine from "./index";
import Component from "./components/Component";

export default class Entity extends PIXI.Container {
    data = null;
    target = null;
    id: number = -1;
    terrainType: string = TerrainTypes.NONE;
    components: any[] = [];

    constructor(props) {
        super();
        const {data, coordX, coordY} = props;
        this.x = coordX * TILE_SIZE || 0
        this.y = coordY * TILE_SIZE || 0
        this.data = data || {};
    }

    getComponents() {
        return this.components;
    }

    getComponent(componentType) {
        for (const component of this.components) {
            if (component instanceof componentType) {
                return <typeof componentType>component;
            }
        }
        return null;
    }

    addComponent(...components) {
        const {systemMgr} = WonEngine.GetInstance().managers;

        for (const component of components) {
            component.target = this;
            // systemMgr.addComponent(this, component);
        }

        this.components = [
            ...this.components,
            ...components,
        ];
    }

    init() {
        for (const component of this.components) {
            if (!component.initialized) {
                component.init();
                component.initialized = true;
            }
        }
    }

    release() {

        for (const component of this.components) {
            component.release();
        }
    }
}
