import Manager from "./Manager";
import WonEngine from "../index";
import {Key} from "../stageRenderers/MapToolRenderer";
import Weapon, {DEFAULT_WEAPON_OFFSET} from "../components/Weapon";
import SpriteRenderer from "../components/SpriteRenderer";
import {AttackTypes, EquipmentTypes} from "../Types";
import Rope from "../components/Rope";

export default class WeaponMgr extends Manager {
    textures: any = {};
    radian: number = 0;

    selectedItemIndex = 0;
    setSelectedItemIndex = null;

    isAiming = false;

    constructor() {
        super();
    }

    init() {
        const {items} = this.wonEngine;

        this.initTextures(items);
    }

    initTextures(items) {
        for (const [name, weaponData] of Object.entries(items)) {
            const [coordX, coordY] = weaponData['texture'].coords;
            const [width, height] = weaponData['texture'].size;
            this.textures[name] = WonEngine.GetTexture('weapons',
                new PIXI.Rectangle(coordX * 16, coordY * 16, width * 16, height * 16));
        }
    }

    getWeaponData() {
        const {items} = this.wonEngine;
        const weaponData: any = Object.entries(items)[this.selectedItemIndex]?.[1]

        return weaponData || null;
    }

    selectItem(selectedItemIndex) {
        const {characterMgr} = this.wonEngine.managers;
        const {items} = this.wonEngine;
        const hero = characterMgr.getHero();

        if (!hero) {
            return;
        }

        const weapon = hero.getComponent(Weapon);
        const weaponSprite = hero.getComponent(Weapon).sprite;

        this.selectedItemIndex = selectedItemIndex;

        const weaponData: any = Object.entries(items)[selectedItemIndex]?.[1]

        if (weaponData) {
            hero.equipments[EquipmentTypes.WEAPON] = weaponData;
            weapon.attackSpeed = weaponData['attackSpeed'];
            weaponSprite.visible = true;
            weaponSprite.texture = Object.entries(this.textures)[selectedItemIndex][1];

            if (weaponData.attackType === AttackTypes.SHOOT) {
                weapon.weaponOffset = DEFAULT_WEAPON_OFFSET * -1;
            }
        } else {
            hero.equipments[EquipmentTypes.WEAPON] = null;
            weaponSprite.visible = false;
        }
    }

    keyFrame() {
        let newSelectedItemIndex = null;
        for (let i = 1; i <= 8; i++) {
            if (Key.isDown(48 + i)) {
                newSelectedItemIndex = i - 1;

                if (this.selectedItemIndex !== newSelectedItemIndex) {
                    this.setSelectedItemIndex(newSelectedItemIndex);
                }
                break;
            }
        }

        this.isAiming = false;
        if (Key.isDown(Key.E)) {
            this.isAiming = true;
        }
    }

    update() {
        const {characterMgr} = this.wonEngine.managers;
        const {mapToolRenderer} = this.wonEngine.stageRenderers;
        const {globalMousePosition} = mapToolRenderer;
        const mousePosition = mapToolRenderer.tileMap.toLocal(globalMousePosition);

        const hero = characterMgr.getHero();
        if (!hero) return;

        const weapon = hero.getComponent(Weapon);
        const rope = hero.getComponent(Rope);

        const heroSprite = hero.getComponent(SpriteRenderer).sprite;

        // this.keyFrame();
        const weaponRange = 7;

        const heroWeapon = hero.equipments?.[EquipmentTypes.WEAPON];
        if (!heroWeapon) return;

        const isHolding = hero.equipments?.[EquipmentTypes.WEAPON].attackType === AttackTypes.SHOOT;

        if (isHolding) {
            weapon.sprite.anchor.set(0.5, 0.5);
        } else {
            weapon.sprite.anchor.set(0.5, 1);
        }

        let preWeaponOffset = weapon.weaponOffset;
        const t = weapon.elapsedAttackTime / weapon.attackSpeed;

        if (weapon.isAttacking) {
            preWeaponOffset = weapon.weaponOffset * (1 - t);
        }

        const dx = hero.x - mousePosition.x;
        const dy = hero.y - mousePosition.y;
        const dir = Math.sign(dx)
        const oriRadian = Math.atan2(dy, dx);

        this.radian = oriRadian * dir
            - (Math.PI * 0.3)
            - (weapon.weaponOffset * 0.5) + preWeaponOffset;
        this.radian *= dir;

        weapon.sprite.scale.set(-1, dir);
        heroSprite.scale.set(Math.sign(dx) * -1 || 1, 1);

        weapon.sprite.rotation = oriRadian
            + Math.PI * 0.2 * dir
            - Math.PI * 2 * t * dir
            * Math.sign(weapon.weaponOffset);

        weapon.sprite.position.set(
            Math.cos(this.radian) * weaponRange * -1,
            Math.sin(this.radian) * weaponRange * -1,
        );
        rope.rope.visible = !!weapon.isAttacking;
        // rope.update();
        // weapon.x -= 2 * dir;
        // weapon.y += 7;
    }
}
