import Component from "./Component";
import WonEngine from "../index";
import {CharState} from "../Types";
import SpriteRenderer from "./SpriteRenderer";
import Character from "../entities/Character";

export default class Movement extends Component {
    constructor() {
        super();
    }

    move(movement) {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const sprite = this.target.getComponent(SpriteRenderer).sprite;

        this.target.x += movement.x;
        this.target.y += movement.y;

        if (movement.x !== 0 || movement.y !== 0) {
            (<Character>this.target).state = CharState.RUN;
        }
    }

    update() {
    }
}
