import Component from "./Component";
import WonEngine from "../index";
import {AttackTypes, EquipmentTypes} from "../Types";

export const DEFAULT_WEAPON_OFFSET = -Math.PI * 0.7;

export default class Weapon extends Component {
    sprite: PIXI.Sprite = null;
    weaponAngle: PIXI.Graphics = new PIXI.Graphics;
    isAttacking: boolean = false;
    attackMotionIndex: number = 0;
    maxAttackMotionIndex: number = 1;
    elapsedAttackTime = 0;
    attackSpeed = 200;
    weaponOffset: number = DEFAULT_WEAPON_OFFSET;
    restingTime = 100;
    data = {};

    constructor() {
        super();
        this.weaponAngle.lineStyle(1, 0xFFFFFF, 1);
        this.weaponAngle.drawCircle(0, 0, 8);
        this.weaponAngle.visible = false;

        const {weaponMgr} = WonEngine.GetInstance().managers;
        const weapon = new PIXI.Sprite(PIXI.Texture.WHITE);
        weapon.visible = false;
        // weapon.anchor.set(0.5, 0.5);
        weapon.anchor.set(0.5, 1);

        this.sprite = weapon;
    }

    init() {
        this.target.addChild(this.sprite);
        this.target.addChild(this.weaponAngle);
    }

    update() {
        const {hero} = WonEngine.GetInstance();
        const {missileMgr} = WonEngine.GetInstance().managers;
        const ticker = PIXI.Ticker.shared;

        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;
        const {isDownedTileMapContainer} = mapToolRenderer.tileMap;

        if (this.restingTime <= 0) {
            if (isDownedTileMapContainer) {
                this.isAttacking = true;
            }
        }

        if (!this.isAttacking) {
            this.restingTime -= ticker.elapsedMS;
            return;
        }

        if (hero.equipments?.[EquipmentTypes.WEAPON].attackType === AttackTypes.SHOOT) {
            missileMgr.launch();
            this.isAttacking = false;
            this.restingTime = 300;

        } else {
            this.elapsedAttackTime += ticker.elapsedMS;
            if (this.elapsedAttackTime >= this.attackSpeed) {
                this.elapsedAttackTime = 0;
                this.isAttacking = false;
                this.weaponOffset *= -1;

                this.restingTime = 150;

                // if (this.attackMotionIndex++ >= this.maxAttackMotionIndex) {
                //     this.attackMotionIndex = 0;
                // }
            }
        }
    }
}
