import React, {useState, useEffect} from 'react';
import Cookies from 'js-cookie'
import ListIcon from "../../../www/res/icons/list.png";
import ThumbnailIcon from "../../../www/res/icons/thumbnail.png";
import PivotIcon from "../../../www/res/icons/pivot.png";

import Icon from "../../components/Icon";
import {DataKeyToEntityType, EntityTypes} from "../../WonEngine/Types";
import WonEngine, {RENDER_TYPE} from "../../WonEngine";
import MapToolItem from "./MapToolItem";
import SpriteRenderer from "../../WonEngine/components/SpriteRenderer";
import DiscardFilter from "../../WonEngine/filters/discard";

const discardFilter = new DiscardFilter();
const pivotContainerFilters = [discardFilter];

export default (props) => {
    const {
        selectedListType, setListType,
        gameData, characters, items, mapEntities
    } = props;
    const [showingPivot, showPivot] = useState(false);
    const [selectedItem, setSelectItem] = useState('');
    const wonEngine = WonEngine.GetInstance();

    const handleClickItem = (item, itemKey) => {
        setSelectItem({
            ...item,
            itemKey,
        })
    };

    useEffect(() => {
        Cookies.set('selectedListType', selectedListType);
    }, [selectedListType])

    useEffect(() => {
        wonEngine.stageRenderers[RENDER_TYPE.MAP_TOOL].selectItem(selectedItem);
    }, [selectedItem])

    useEffect(() => {
        const {mapToolRenderer} = wonEngine.stageRenderers;

        mapToolRenderer.layers["PIVOT"].renderable = showingPivot;

    }, [showingPivot])

    const handleClickPivot = () => {
        showPivot(!showingPivot);
    };

    // const filteredTiles = gameData.tiles.filter(item => item.itemType === "TILE");

    // const filteredTiles = Object.entries(gameData.tiles).filter(([key, value]) => value.itemType === "TILE");
    // const result = Object.fromEntries(filteredTiles);

    return <div style={styles.root}>
        <div style={styles.toolIcons}>
            {
                [ListIcon, ThumbnailIcon].map((item, index) =>
                    <Icon key={index} style={{
                        padding: '0.2em',
                    }} selected={selectedListType === index} src={item}
                          onClick={() => setListType(index)}/>)
            }
            {
                [PivotIcon].map((item, index) =>
                    <Icon key={index} style={{
                        padding: '0.2em',
                    }} selected={showingPivot} src={item}
                          onClick={() => handleClickPivot()}
                    />)
            }
        </div>
        <div style={{
            overflow: 'auto',
            overflowX: 'hidden',
        }}>
            <div>
                {
                    Object.entries({
                        tiles: mapEntities.filter(item => item.itemType === "TILE"),
                        objects: mapEntities.filter(item => item.itemType === "OBJECT"),
                        characters,
                        items
                    }).map(([key, items]) => <div style={styles.itemGroup} key={key}>
                        <div style={Object.assign({}, styles.itemToolBar)}>{key}</div>
                        <div style={Object.assign({}, styles.list, selectedListType === 1 && styles.thumbnail)}>
                            <MapToolItem uniqueKey={`${key}_${0}`} selectedListType={selectedListType} itemData={{
                                "name": "NONE",
                                "itemType": DataKeyToEntityType[key],
                                "index": 0
                            }} selectedItem={selectedItem} onClick={handleClickItem}/>

                            {
                                items.map((item, index) => {
                                    const uniqueKey = `${key}_${index + 1}`;
                                    return <MapToolItem key={uniqueKey} uniqueKey={uniqueKey} itemData={item}
                                                        selectedListType={selectedListType}
                                                        onClick={handleClickItem}
                                                        selectedItem={selectedItem}
                                    />
                                })
                            }
                        </div>
                    </div>)
                }
            </div>
        </div>
    </div>
}

const styles = {
    list: {
        flexWrap: 'wrap',
    },
    thumbnail: {
        display: 'flex',
        flexDirection: "row",
    },
    itemGroup: {
        display: 'flex',
        flexDirection: 'column',
    },
    root: {
        // position: 'absolute',
        display: 'flex',
        flexDirection: 'column',
        width: '200px',
        // height: '100%',
        // flex: 1,
        backgroundColor: 'lightgray',
        // border: '5px solid red',
        boxSizing: 'border-box',
    },

    toolIcons: {
        display: 'flex',
        margin: '0.3em',
        cursor: "pointer",
        borderBottom: '2px solid black',
        paddingBottom: '0.3em',
    },


    itemName: {
        marginLeft: '0.2em',
        fontSize: '1.5em',
        textShadow: '2px 2px 2px white',
    },

    itemToolBar: {
        fontSize: '1.5em',
        fontWeight: 'bold',
        textShadow: '2px 2px 2px white',
    },
}
