import Entity from "../Entity";
import WonEngine from "../index";
import {CONTAINER_SCALE, TILE_SIZE} from "../Types";
import Terrain from "../components/Terrain";
import Shadow from "../components/Shadow";
import SpriteRenderer from "../components/SpriteRenderer";

export default class Tile extends Entity {
    constructor(data, coordX, coordY, width = undefined, height = undefined) {
        super({data, coordX, coordY});

        this.id = data.id;
        this.terrainType = data.terrainType;

        this.addComponent(new SpriteRenderer(coordX, coordY, width, height));
        this.addComponent(new Terrain());

        this.getComponent(SpriteRenderer).sprite.addChild(this.getComponent(Terrain).textGraphic);

        if (data.hasShadow) {
            this.addComponent(new Shadow());
        }

        this.init();
    }
}
