import React, {useEffect, useRef, useState} from 'react';
import Form from "@rjsf/core";
import validator from "@rjsf/validator-ajv6";
import {v4 as uuidv4} from 'uuid';
import MonacoEditor from 'react-monaco-editor';
import ItemListView from "../ItemTool/ItemListView";
import {useFilterItems} from "../../hooks";
import {ToastContainer, toast} from 'react-toastify';
import Cookies from 'js-cookie'
import "./ToolTemplate.css";
import {GetGameDatabase, pullPlayerData} from "../../DataRequester";
import {SERVER_URL} from "../../config";
import {DEFAULT_FORM_DATA} from "../../jsonSchema/widgets/IntlInput";

const ItemWrapper = props => <div style={styles.toolBarWrapper}>{props.children}</div>

const schemas = [
    "FormData", "UI_schema",
]

export default (props) => {
    const {
        name,
        items, setItems,
        itemSchema, uiSchema, fields, widgets,
        onChange, onClickSave, onClickLoad,
        objectFieldTemplate, defaultFormData = {}, category,
    } = props;

    const [selectedItemKey, setSelectedItemKey] = useState(null);
    const [filteredItems, setFilteredItems] = useState({});
    const [formData, setFormData] = useState(null);

    const [isInitialized, setInitialized] = useState(false)

    const [selectedSchema, setSchema] = useState("FormData")

    useEffect(() => {
        const cookies = Cookies.get();
        let selectedItemId = cookies[`${name}_selectedItemId`];

        if (selectedItemId === null) {
            selectedItemId = items[0].id;
        }

        if (selectedItemId)
            setSelectedItemKey(selectedItemId);
        setInitialized(true);
    }, []);

    useFilterItems(items, category, setFilteredItems);

    // Select Item.
    useEffect(() => {
        let selectedItemData = items.find(item => item.id === selectedItemKey);
        Cookies.set(`${name}_selectedItemId`, selectedItemKey);

        // if(!selectedItemData) {
        //     if(Object.keys(items).length > 0) {
        //         selectedItemData = items[0];
        //     }
        // }

        if (selectedItemData) {
            // console.log(selectedItemData);
            setFormData({
                // ...defaultFormData,
                ...selectedItemData,
            });
        }
    }, [selectedItemKey])

    const handleClickNewItem = () => {
        setItems([
            ...items,
            {
                ...defaultFormData,
                name: `newItem ${items.length}`,
                id: uuidv4(),
            },
        ]);
    }
    const handleClickDeleteItem = () => {
        const deletedItemIndex = items.findIndex(item => item.id === selectedItemKey);

        if (deletedItemIndex !== -1) {
            const newItems = [...items];
            newItems.splice(deletedItemIndex, 1);
            setItems(newItems);


            // select first item.
            const firstItemIndex = newItems[0]?.id;
            if (firstItemIndex) {
                setSelectedItemKey(firstItemIndex);
            } else {
                setSelectedItemKey(null);
            }
        }
    }

    const handleClickUpdate = () => {
        const selectedItemIndex = items.findIndex(item => item.id === selectedItemKey);

        if (selectedItemIndex !== -1 && formData !== null) {
            const newItems = [...items];

            newItems[selectedItemIndex] = {
                ...formData,
            }

            setItems(newItems);
        }
    };

    const handleSubmit = ({formData}) => {
        let canSubmit = items.findIndex(item => item.name === formData.name);

        const newItem = {
            ...formData,
            id: uuidv4(),
        };

        if (canSubmit === -1) {
            setItems([
                ...items,
                newItem
            ]);
            setSelectedItemKey(newItem.id);
        }
    }

    const handleClickSelectItem = (key) => {
        setSelectedItemKey(key);
    };

    const handleClickDuplicateItem = () => {
        const selectedItemIndex = items.findIndex(item => item.id === selectedItemKey);

        if (selectedItemIndex !== -1) {
            const newItems = [...items];
            const newItem = {
                ...newItems[selectedItemIndex],
                id: uuidv4(),
                name: `${newItems[selectedItemIndex].name} copy`,
            };

            newItems.push(newItem);
            setItems(newItems);
            setSelectedItemKey(newItem.id);
        }
    }

    const handleOnChange = (e) => {
        // console.log(e.formData);
        setFormData(e.formData)

        if (items) {
            const newFormData = {...e.formData};
            const selectedItemIndex = items.findIndex(item => item.id === selectedItemKey);

            if (selectedItemIndex !== -1) {
                const newItems = [...items];

                newItems[selectedItemIndex] = {
                    ...newFormData,
                }
                setItems(newItems);
            }
        }
    };

    const mergedFormData = Object.assign({}, defaultFormData, formData);

    // console.log(mergedFormData);

    const handleClickSave = () => {

        // const newItems = items.map(item => {
        //     if (!item.localizedText) {
        //         item.localizedText = DEFAULT_FORM_DATA
        //     }
        //
        //     return item;
        // });

        setItems(items.map(item => {

            const newItem = {
                ...item,
                tier: 0,
                localizedText: !item.localizedText
                    ? DEFAULT_FORM_DATA
                    : item.localizedText,
            }

            if (newItem.description) {
                delete newItem.description;
            }

            return newItem;
        }))
        onClickSave();
    }

    const handleClickClearItems = () => {
        setItems([]);
    }

    const onPullPlayerData = () => {
        (async () => {
            // const playerData = await pullPlayerData();
            // var response = await request.post(`${SERVER_URL}\\${API}`).send(data || {});
        })()
    }

    const handleClickFetchItems = async () => {
        const result = await GetGameDatabase(true, ["playerDataList"]);


        setItems([...result.playerDataList]);
    }

    // if (!isInitialized) return null;

    return <div style={styles.itemTool}>
        <ItemListView name={name} filteredItems={filteredItems} setFilteredItems={setFilteredItems}
                      selectedItemKey={selectedItemKey}
                      onClickSelectItem={handleClickSelectItem}
                      setSelectedItemKey={setSelectedItemKey}
        />
        <div style={styles.view}>
            <div style={styles.toolBar}>
                <ItemWrapper>
                    <button onClick={handleClickFetchItems.bind(this)} style={styles.button}>Fetch Items</button>

                    <button onClick={handleClickClearItems} style={styles.button}>Clear Items</button>

                    <button onClick={handleClickNewItem} style={styles.button}>New Item</button>

                    <button onClick={handleClickSave} style={styles.button}>Save</button>
                    <button onClick={onClickLoad} style={styles.button}>Load</button>

                    <button onClick={onPullPlayerData} style={styles.button}>Pull PlayerData</button>

                </ItemWrapper>
            </div>


            <div style={styles.content}>
                <div style={styles.formWrapper}>
                    <div>
                        <div style={styles.submitButtonWrapper}>
                            <button style={styles.formButton} type="submit">Add Item</button>
                            <button style={styles.formButton} type="button"
                                    onClick={handleClickDuplicateItem.bind(this)}>Duplicate Item
                            </button>

                            <button style={styles.formButton} type="button"
                                    onClick={handleClickDeleteItem.bind(this)}>Delete Item
                            </button>
                            <button style={styles.formButton} type="button"
                                    onClick={handleClickUpdate.bind(this)}>Update Item
                            </button>
                        </div>

                        <Form
                            // showErrorList={false}
                            autoComplete="off"
                            validator={validator}

                            formData={mergedFormData}
                            fields={fields}
                            widgets={widgets}
                            schema={itemSchema}
                            uiSchema={uiSchema}
                            formContext={{rootData: formData}}
                            // ObjectFieldTemplate={objectFieldTemplate}
                            onChange={handleOnChange.bind(this)}
                            onSubmit={handleSubmit.bind(this)}
                        >

                        </Form>
                    </div>
                </div>

                <div style={{
                    // flex: 1,
                }}>
                    <div style={{
                        display: 'flex',
                    }}>
                        {
                            schemas.map(schema => <div key={schema}
                                                       style={Object.assign({}, styles.schemaLabel, selectedSchema === schema && {
                                                           color: 'black',
                                                       })}
                                                       onClick={() => setSchema(schema)}>{schema}</div>)
                        }
                    </div>
                    <MonacoEditor
                        width="800"
                        height="800"
                        language="json"
                        theme="vs"
                        value={
                            JSON.stringify(selectedSchema === "FormData" ? mergedFormData : uiSchema, null, '\t')
                        }
                        options={{
                            fontSize: 12,
                            readOnly: selectedSchema !== "FormData",
                            fontLigatures: true,
                        }}
                        onChange={(newValue) => {
                            let json;
                            try {
                                json = JSON.parse(newValue);
                            } catch (e) {
                                console.error(e.message);
                                toast.error(e.message, {});
                                return;
                            }
                            setFormData(json);
                        }}
                        // editorDidMount={::this.editorDidMount}
                        editorDidMount={(editor) => {
                            editor.updateOptions({
                                fontFamily: "monospace",  // 원하는 폰트 적용
                                fontWeight: "bold", // 볼드 적용
                            });

                            editor._themeService._knownThemes.get('vs').tokenColors = [
                                {
                                    "scope": ["source.json"],
                                    "settings": {
                                        "fontStyle": "bold"
                                    }
                                }
                            ];
                        }}
                    />
                </div>
            </div>
        </div>

    </div>
};


const styles = {
    schemaLabel: {
        fontWeight: 'bold',
        fontSize: '1.7em',

        color: '#cccccc',
        cursor: 'pointer',
        userSelect: 'none',
        marginLeft: '0.3em',
        marginRight: '0.3em',
    },
    submitButtonWrapper: {
        marginBottom: '1em',
    },
    content: {
        flex: 1,
        display: 'flex',
        flexDirection: 'row',
        // overflowY : 'true',

    },
    formWrapper: {
        // height : '100%',
        // flex: '1',
        height: '800px',
        width: '700px',

        // width: '40%',
        // border: '2px solid blue',
        padding: '1em',
        borderRight: '1px solid darkGray',
        overflowY: 'scroll',

    },
    view: {
        display: 'flex',
        // flex: 1,
        flexDirection: 'column',
    },
    toolBar: {
        display: 'flex',
        flexDirection: 'row',
        backgroundColor: '#f6f9f8',
        borderBottom: '1px solid darkGray',
        fontSize: '2em',
        textShadow: '2px 2px 2px white',
        userSelect: 'none',

        dark: {},
    },
    toolBarWrapper: {
        margin: '0.2em',
        // marginBottom: '1em'
    },
    button: {
        padding: '1em',
    },
    formButton: {
        width: '150px',
        padding: "1em",
    },
    itemTool: {
        boxSizing: 'border-box',
        display: 'flex',
        // height: '800px',

        // height: '100%',
    },
};
