import React, {useEffect} from 'react';
import Select, {components, MultiValueGenericProps} from 'react-select';
import WonEngine from "../WonEngine";
import {updateTexture} from "../hooks";

export const getItems = (itemType) => {
    switch (itemType) {
        case "Card":
            return WonEngine.GetInstance().cards;
        case "Skill":
            return WonEngine.GetInstance().skills;
        default:
            return WonEngine.GetInstance().items;
    }
}

export const getToolItemTexture = (itemData) => {
    // const wonEngine = WonEngine.GetInstance();
    // const {textureMgr} = wonEngine.managers;
    // const texture = textureMgr.getByTextureInfo(itemData.texture);
    // return wonEngine.extractToBase64(texture);

    try {
        const wonEngine = WonEngine.GetInstance();
        const {textureMgr} = wonEngine.managers;
        const texture = textureMgr.getByTextureInfo(itemData.texture);
        return wonEngine.extractToBase64(texture, itemData.texture);
    } catch (e) {
        // console.log(`can't get texture ${itemData.texture}`)
        return null;
    }
}
const itemsToLabels = (selectedItems, itemType) => {
    const items = getItems(itemType);

    return selectedItems.map(skill => {
        let skillData = items.find(skillData => skillData.id === skill);

        if (!skillData) {
            // skillData = null;
            // return null
        }

        return ({
            value: skill,
            label: skillData?.name || null,
        })
    })
}
const labelsToSkills = (labels) => labels.map(label => label.value);

const ItemTexture = (props) => {
    const {itemId, itemType} = props;
    const items = getItems(itemType);

    const imageSize = 30;
    let skillData = items.find(skillData => skillData.id === itemId);
    const itemTexture = getToolItemTexture(skillData);

    return <img style={Object.assign({}, styles.itemTexture, {
        objectFit: 'fill',
        height: `${imageSize}px`,
        width: `${imageSize}px`,
    })} src={itemTexture}/>
}

const MultiValueLabel = (props) => {
    const {data, itemType} = props;


    return <div style={{
        display: 'flex',
        flexFlow: 'column',
        alignItems: 'center',
    }}>
        {/*<div>{JSON.stringify(data)}</div>*/}
        <ItemTexture itemId={data.value} itemType={itemType}/>
        <div style={{
            fontWeight: 'bold',
            textShadow: '2px 2px 2px #bbb',
        }}>{data.label || "null"}</div>
        {/*<components.MultiValueLabel {...props} />*/}
    </div>
};

const Option = (props) => {
    const {data, itemType} = props;
    return <div style={{
        display: 'flex',
    }}>
        <ItemTexture itemId={data.value} itemType={itemType}/>
        <components.Option {...props} />
    </div>
};

export default (props) => {
    const {isMulti, value, onChange, options, itemType} = props;

    useEffect(() => {
        const items = getItems(itemType);
        updateTexture(items);
    }, [])

    return <Select
        components={{
            MultiValueLabel: ({children, ...props}) => (
                <MultiValueLabel {...props} itemType={itemType}>
                    {children}
                    {/*<span style={{ color: 'blue' }}>{children}</span> /!* 예시로 스타일 추가 *!/*/}
                </MultiValueLabel>
            ),
            Option: ({children, ...props}) => (
                <Option {...props} itemType={itemType}>
                    {children}
                    {/*<span style={{ color: 'blue' }}>{children}</span> /!* 예시로 스타일 추가 *!/*/}
                </Option>
            )
        }}

        // components={{MultiValueLabel: <MultiValueLabel itemType={itemType}/>, Option}}
        isMulti={isMulti}
        // styles={{
        //     control: (baseStyles, state) => ({
        //         ...baseStyles,
        //         // width: '200px',
        //         // borderColor: state.isFocused ? 'grey' : 'red',
        //     }),
        //     multiValue: (styles, {data, isDisabled, isFocused, isSelected}) => ({
        //         display: 'flex',
        //         border: '11px solid blue',
        //     })
        // }}
        // defaultValue={}
        value={itemsToLabels(value, itemType)}
        onChange={(e) => onChange(labelsToSkills(e))}

        options={options}
    />
}

const styles = {
    itemTexture: {
        // flex: 1,
        imageRendering: 'pixelated',
    },
}
