import React from 'react'
import {
    CHARACTER_HEIGHT,
    CHARACTER_SHEET_HEIGHT,
    CHARACTER_SHEET_WIDTH,
    CHARACTER_WIDTH
} from "../containers/CharacterTool/config";

export default (props) => {
    const {character} = props;
    const scaleValue = 2;

    let colorStyle = {
        backgroundColor: 'white',
    };

    if (character.type !== undefined) {
        colorStyle.backgroundColor = character.type === 0 ? 'skyblue' : 'Firebrick';
    }

    return <div style={{
        border: '2px solid black',
        backgroundImage: `url(${character.dataURL})`,
        backgroundSize: `${CHARACTER_SHEET_WIDTH * scaleValue}px ${CHARACTER_SHEET_HEIGHT * scaleValue}px`,
        width: `${CHARACTER_WIDTH * scaleValue}px`,
        height: `${CHARACTER_HEIGHT * scaleValue}px`,
        imageRendering: 'pixelated',
        ...colorStyle,
    }}/>
}

