import React, {useEffect, useRef, useState} from "react";
import Select from 'react-select';
import Range from "./components/Range";
import WonEngine from "../../../WonEngine";

export default (props) => {
    const {formData, onChange, socketPart} = props;
    const [options, setOptions] = useState(null);
    const [partOptions, setPartOptions] = useState(null);

    const [selectedOption, setSelectedOption] = useState(null);

    useEffect(() => {
        const wonEngine = WonEngine.GetInstance();
        const newOptions = wonEngine.stats.map(stat => ({
            value: stat.name,
            label: stat.name,
        }))

        setOptions(newOptions);
    }, [])

    const handleRemoveStat = (stat, index) => {
        const newStatList = [
            ...formData,
        ]
        newStatList.splice(index, 1)

        onChange(newStatList);
    }

    const handleAddStat = (selectedNewStat) => {

        const foundStatIndex = formData.findIndex(stat => stat.type === selectedNewStat)

        // 중복된 아이템 추가 방지.
        if (!selectedNewStat || foundStatIndex !== -1) {
            return;
        }

        const newStatList = [
            ...formData,
            {
                type: selectedNewStat,
                value: 0,
                socketPart
            }
        ];

        onChange(newStatList);
    }

    return options && <div>

        <div style={{
            overflowY: 'auto',
            maxHeight: '150px',
        }}>
            <div>
                {formData.map((stat, index) => <div key={`${stat.value}_${index}`} style={{
                        display: 'flex',
                        flexDirection: 'column',
                    }}>
                        <Range stat={stat} index={index}
                               statList={formData} setStatList={onChange}
                               onRemove={handleRemoveStat.bind(this)}/>
                    </div>
                )}
            </div>
        </div>

        <div style={{
            display: 'flex',
        }}>
            <Select
                styles={{
                    control: (baseStyles, state) => ({
                        ...baseStyles,
                        width: '200px',
                        // borderColor: state.isFocused ? 'grey' : 'red',
                    }),
                }}
                defaultValue={selectedOption}
                onChange={(e) => setSelectedOption(e)}
                options={options}
            />
            <button style={styles.Button} onClick={handleAddStat.bind(this, selectedOption?.value ?? null)}>Add
                Stat
            </button>

        </div>
    </div>
}


const styles = {
    Button: {
        // userSelect: 'none',
        marginLeft: '1em',
        // height: '3em',
        // width: '150px',
        // height: '70px',
    },
    statLabel: {
        fontSize: "1.2em",
        margin: '0.3em',
        cursor: 'pointer',
        userSelect: 'none',
        padding: '0.3em',
        width: '150px',
        borderBottom: '1px dotted black',
    },
    selectedStatLabel: {
        backgroundColor: 'orange'
    }
}

