import {StageRenderer} from "../StageRenderer";
import WonEngine from "../index";


export default class EffectRenderer extends StageRenderer {
    axis: PIXI.Graphics = new PIXI.Graphics()
    mouseGraphic: PIXI.Graphics = new PIXI.Graphics();

    effectTrajectory: PIXI.Graphics = new PIXI.Graphics();

    AnchorPointA: PIXI.Graphics = new PIXI.Graphics();
    AnchorPointB: PIXI.Graphics = new PIXI.Graphics();

    constructor() {
        super();
    }

    _load() {
        console.log(`EffectRenderer loaded`);

        const lineLength = 50;
        this.axis.lineStyle(2, 0x00FF00, 1);
        this.axis.moveTo(-lineLength, 0);
        this.axis.lineTo(lineLength, 0);
        this.axis.moveTo(0, -lineLength);
        this.axis.lineTo(0, lineLength);

        const {renderer} = this.wonEngine;
        this.stage.x = renderer.width * 0.5;
        this.stage.y = renderer.height * 0.5;

        this.mouseGraphic.lineStyle(2, 0xFFFFFF, 1);
        this.mouseGraphic.drawRect(0, 0, 10, 10);
        this.mouseGraphic.pivot = new PIXI.Point(
            this.mouseGraphic.width * 0.5,
            this.mouseGraphic.height * 0.5);

        this.AnchorPointA.lineStyle(2, 0xFFFFFF, 1);
        this.AnchorPointA.drawCircle(0, 0, 50);
        this.AnchorPointB.lineStyle(2, 0xFFFFFF, 1);
        this.AnchorPointB.drawCircle(0, 0, 50);

        this.stage.addChild(this.AnchorPointA)
        this.stage.addChild(this.AnchorPointB)

        this.stage.addChild(this.axis);
        this.stage.addChild(this.effectTrajectory);
        this.stage.addChild(this.mouseGraphic);
    }

    render() {
        const globalMousePosition = WonEngine.GetInstance().renderer.plugins.interaction.mouse.global;
        const mousePosition = this.stage.toLocal(globalMousePosition);

        // this.effectTrajectory.lineStyle(2, 0xFFFFFF, 1);
        // this.effectTrajectory.moveTo(0, 0);
        // this.effectTrajectory.lineTo(
        //     mousePosition.x,
        //     mousePosition.y,
        // );

        this.mouseGraphic.position.copyFrom(mousePosition);
        this.AnchorPointB.position.copyFrom(mousePosition);
    }
}
