import Manager from "./Manager";
import {TextureKeyTypes, TILE_SIZE} from "../Types";
import WonEngine from "../index";


export default class TextureMgr extends Manager {

    textures = {};

    add(type, textureName, texture : PIXI.Texture) {
        const key = `${type}_${textureName}`;
        // console.log(`${key}`, texture);
        this.textures[key] = texture;
    }

    getByTextureInfo(textureInfo) {
        const {textureName, coords, size} = textureInfo;
        const textureKey = `${textureName}_${coords[0]}_${coords[1]}_${size[0]}_${size[1]}`;

        return this.get(TextureKeyTypes.ITEM, textureKey);
    }

    getTextureByData(entityData) {
        const {textureMgr} = this.wonEngine.managers;
        let texture;

        if (entityData.name === "NONE") return PIXI.Texture.WHITE;

        if (entityData.itemType === "OBJECT" || entityData.itemType === "TILE") {
            texture = textureMgr.getByTextureInfo(entityData.texture);
        } else {
            try {
                texture = new PIXI.Texture(this.wonEngine.getTexture(entityData.texture.textureName),
                    new PIXI.Rectangle(
                        entityData.coords[0] * TILE_SIZE,
                        entityData.coords[1] * TILE_SIZE,
                        TILE_SIZE, TILE_SIZE));
            } catch (e) {
                console.warn(e);
            }

        }
        return texture;
    }

    get(type, textureName) {
        if (this.textures[`${type}_${textureName}`]) {
            return this.textures[`${type}_${textureName}`];
        }
        return null;
    }

    delete(type, textureName) {
        if (this.textures[`${type}_${textureName}`]) {
            delete this.textures[`${type}_${textureName}`];
        }
    }

    init() {

    }
}
