import * as vertex from "./shadow.vert";
import * as fragment from "./shadow.frag";


export const MAX_TILE_HEIGHT = 50;

export const TILE_SIZE = 32;
export const TILE_HALF_SIZE = TILE_SIZE * 0.5;

export const MAX_SCALE = 5;
export const MIN_SCALE = 0;

export const SHADOW_DIST = 100;


export default class ShadowFilter extends PIXI.Filter {
    cachedPrograms = new Map();

    constructor() {
        // @ts-ignore
        super(vertex, fragment.replace(/%SHADOW_DIST%/gi, '' + SHADOW_DIST));
        this.uniforms.uXYAngle = 0.5;
        this.uniforms.uZAngle = 0.5;
        this.uniforms.uTexStep = 1.0 / 2048;
        // this.uniforms.uTexStep = 1.0 / (TILE_SIZE * MAX_TILE_HEIGHT);

        // this.autoFit = true;


        // this.cachedPrograms = new Map();
        this.generatePrograms();
    }

    generateProgram(key) {
        // @ts-ignore
        const program = PIXI.Program.from(vertex, fragment.replace(/%SHADOW_DIST%/gi, '' + key));
        return program;
    }

    generatePrograms() {
        for (let scaleValue = MIN_SCALE; scaleValue <= MAX_SCALE; scaleValue += 1) {
            const key = SHADOW_DIST * scaleValue;
            const program = this.generateProgram(key);
            this.cachedPrograms.set(key, program);
        }
    }

    setShadowDist(value) {
        let cachedProgram = this.cachedPrograms.get(value);
        if (!cachedProgram) {
            // console.error(`error`);
            cachedProgram = this.generateProgram(value);
            this.cachedPrograms.set(value, cachedProgram);
            // cachedProgram = PIXI.Program.from(vertex, fragment.replace(/%SHADOW_DIST%/gi, '' + value));
            // this.cachedPrograms.set(value, cachedProgram);
        }
        this.program = cachedProgram;
    }

    apply(filterManager, input, output) {
        // console.log(input.width);
        // this.uniforms.uXYAngle -= 0.01;
        this.uniforms.uXYAngle -= 0.001;
        // this.uniforms.uZAngle -= 0.001;
        filterManager.applyFilter(this, input, output);
    }
}
