import React, {useEffect, useRef, useState} from 'react';

export default (props) => {
    const properties = props.properties.filter(p => p.name !== "texture");
    const texture = props.properties.filter(p => p.name === "texture");


    return <div style={styles.root}>
        <div style={styles.content}>
            {properties.map(element => <div style={styles.property} key={element.name}>{element.content}</div>)}
        </div>
        <div style={styles.property}>
            {texture[0].content}
        </div>
    </div>
}

const styles = {
    root: {
        display: 'flex',
        flexDirection: 'row',
        flex: 1,
    },
    content: {
        width: '50%',
    },
    property: {
        margin: '0.3em',
    }
}
