import React, {useEffect, useState} from 'react';
import Select, {components} from 'react-select'
import WonEngine from "../../WonEngine";


const getAttackEffects = () => {
    const skills = WonEngine.GetInstance().skills
    return skills
        .filter(item => item.skillType === "ACTIVE")
        .map(skillData => ({
            value: skillData.id,
            label: skillData.name
        }));
}

const MaterialSelector = (props) => {
    const {
        name,
        itemType,
        formData,
        value,
        onChange
    } = props;
    const [options, setOptions] = useState([]);
    const [selectedOption, setSelectedOption] = useState();

    useEffect(() => {
        const attackEffects = getAttackEffects();

        setOptions(attackEffects)
    }, [])

    useEffect(() => {
        // const options = toOptions(formData);
        // setOptions(options);

        const foundItem = options.find(option => option.value === value) || null
        console.log(foundItem)
        setSelectedOption(foundItem)
    }, [value]);

    const handleOnChange = (selectedOptions, actionMeta) => {
        onChange(selectedOptions?.value)
    };

    return <div style={styles.LootSelector}>
        {/*<div className={"control-label"}>{name}</div>*/}
        <Select style={styles.select}
                isSearchable={true}
                isClearable={true}
                options={options}
                value={selectedOption}
                onChange={handleOnChange}
        />
    </div>
}

export default MaterialSelector;

const styles = {
    select: {
        width: '3em',
    },
    lootItemWrapper: {
        display: 'flex',
    },
    lootItem: {
        margin: 0,
        padding: 0,
        width: '40px',
        height: '100%',
        boxSizing: 'border-box',
    },
    button: {
        padding: "1em",
    },
};
