import React, {useState} from 'react';
import CanvasRenderer, {PALETTE_COLORS} from "./CanvasRenderer";
import {ANIMATIONS, PARTS_CONFIG} from "./config";
import {defaultFormData} from "./CharacterSchemas";


export const generateRandomCharacter = (index) => {
    const newFormData = {};

    if (index !== undefined) {
        newFormData.name = `Character ${index}`;
    }

    ["eyes", "body", "hair", "suit", "item"]
        .forEach(part => newFormData[part] = parseInt(PALETTE_COLORS.ISLAND_JOY_16.length * Math.random()));

    ["base", "head", "face",]
        .forEach(part => newFormData[part] = parseInt(PARTS_CONFIG[part].max * Math.random()))

    return newFormData;
}

export default (props) => {
    const {formData} = props;
    const [ani, setAni] = useState(ANIMATIONS[0]);

    const handleClickAni = (newAnimation) => {
        setAni(newAnimation);
        CanvasRenderer.GetInstance().changeAnimation(newAnimation);
    };

    const handleClickRandomized = () => {


        props.setFormData({
            ...formData,
            ...generateRandomCharacter(),
        });
    }

    return <div>
        <div style={styles.animationWrapper}>
            {
                ANIMATIONS.map(aniItem => <div key={aniItem} style={Object.assign({},
                    styles.button, (ani === aniItem) && styles.animationSelect)}
                                               onClick={handleClickAni.bind(this, aniItem)}>
                    {aniItem}
                </div>)
            }

            <div style={Object.assign({}, styles.button, {marginLeft: '1em',})}
                 onClick={handleClickRandomized.bind(this)}
            >
                Randomized
            </div>

            <div style={Object.assign({}, styles.button, {marginLeft: '1em',})}
                 onClick={() => {
                     props.setFormData(defaultFormData);
                 }}
            >
                Reset
            </div>
        </div>
    </div>
}

const styles = {
    animationWrapper: {
        display: 'flex',
        flexDirection: 'row',
        margin: '1em',
    },

    button: {
        padding: '1em',
        margin: "-1px 0 0 -1px",
        border: '1px solid black',

        display: 'flex',
        alignItems: 'center',
        justifyContent: "center",
        boxSizing: 'border-box',
        cursor: "pointer",
    },
    animationSelect: {
        outline: '2px solid black',
        zIndex: 1,
    },
}
