import {ANIMATIONS, defaultPaletteState, defaultPartState, PARTS_CONFIG} from "./config";
import {productionMode, SERVER_URL} from "../../config";

export const CANVAS_WIDTH = 16;
export const CANVAS_HEIGHT = 24;
export const CANVAS_SCALE = 10;

export const PALETTE_COLORS = {
    ISLAND_JOY_16: ["#ffffff", "#6df7c1", "#11adc1", "#606c81", "#1e8875", "#5bb361", "#a1e55a", "#f7e476", "#f99252", "#cb4d68", "#6a3771", "#c92464", "#f48cb6", "#f7b69e", "#9b9c82",],
};

// import base from '/www/res/character/base.png';
// import faces from '/www/res/character/faces.png';
// import heads from '/www/res/character/heads.png';
// const localImages = {
//     base, faces, heads,
// }

const aniData = {
    "head": {
        "no": [0],
        "run": [-1, -2, 0, 1],
        "idle": [0, 1, 2, 1]
    },
    "face": {
        "no": [0],
        "run": [-1, -2, 0, 1],
        "idle": [0, 1, 2, 1]
    }
}

const fromColors = {
    "outline": {
        color: [255, 255, 0],
    },

    "eyes": {
        color: [255, 0, 0],
    },

    "body": {
        color: [0, 255, 0],
        shadow: [0, 136, 0],
    },

    "hair": {
        color: [0, 255, 255],
        shadow: [0, 136, 136],
    },

    "item": {
        // color : "#FF00FF";
        color: [255, 0, 255],
        shadow: [136, 0, 136],
    },

    "suit": {
        color: [0, 0, 255],
        shadow: [0, 0, 136],
    },
};

const pad2 = (n) => ("000" + n).slice(-2);
const b2Hex = (r, g, b) => ("#" +
    pad2(r.toString(16)) +
    pad2(g.toString(16)) +
    pad2(b.toString(16))
);
const hex2R = (hex) => parseInt(hex.slice(1, 3), 16);
const hex2G = (hex) => parseInt(hex.slice(3, 5), 16);
const hex2B = (hex) => parseInt(hex.slice(5, 7), 16);
const hex2Arr = (h) => [hex2R(h), hex2G(h), hex2B(h)];

const isSame = (x, y) => x === y || x === y - 1 || x === y + 1;

const isAboutSameRgb = (col, r, g, b) => isSame(col[0], r) && isSame(col[1], g) && isSame(col[2], b);

let _Instance = null;

export default class CanvasRenderer {
    constructor() {
        this.canvas = null;
        this.tempCanvas = null;
        this.ctx = null
        this.initialized = false;
        this.images = {
            "base": null,
            "faces": null,
            "heads": null,
        };

        this.partState = defaultPartState;
        this.paletteState = defaultPaletteState;
        this.preAnimation = ANIMATIONS[0];
        _Instance = this;
    }

    static GetInstance() {
        return _Instance;
    }

    async loadImage(url) {
        let response = await fetch(url);
        const imageBlob = await response.blob();
        const imageObjectURL = URL.createObjectURL(imageBlob);

        const image = document.createElement('img');
        image.src = imageObjectURL;
        await image.decode();

        return image;
    }


    replaceColorIfSameRGB(data, i, srcColor, newColor) {
        if (isAboutSameRgb(srcColor, data[i + 0], data[i + 1], data[i + 2])) {
            data[i + 0] = hex2R(newColor);
            data[i + 1] = hex2G(newColor);
            data[i + 2] = hex2B(newColor);
        }
    }

    recolor(paletteState, ctx) {
        const imd = ctx.getImageData(0, 0, 16, 24);
        const data = imd.data;
        const fc = fromColors;

        const outlineColor = "#302c2e";

        for (let i = 0; i < data.length * 4; i += 4) {

            if (isAboutSameRgb(fromColors.outline.color, data[i + 0], data[i + 1], data[i + 2])) {
                data[i + 0] = hex2R(outlineColor);
                data[i + 1] = hex2G(outlineColor);
                data[i + 2] = hex2B(outlineColor);
            }

            for (const [partName, partColor] of Object.entries(fromColors)) {
                if (partName === "outline") continue;

                const paletteColors = PALETTE_COLORS.ISLAND_JOY_16[paletteState[partName]];

                if (isAboutSameRgb(partColor.color, data[i + 0], data[i + 1], data[i + 2])) {
                    data[i + 0] = hex2R(paletteColors);
                    data[i + 1] = hex2G(paletteColors);
                    data[i + 2] = hex2B(paletteColors);
                }

                if (partColor.shadow) {
                    if (isAboutSameRgb(partColor.shadow, data[i + 0], data[i + 1], data[i + 2])) {
                        data[i + 0] = hex2R(paletteColors) * 0.5;
                        data[i + 1] = hex2G(paletteColors) * 0.5;
                        data[i + 2] = hex2B(paletteColors) * 0.5;
                    }
                }
            }
        }

        ctx.putImageData(imd, 0, 0);
    }

    changePart(newParts) {
        this.partState = newParts;
    }

    changePalette(newPaletteState) {
        this.paletteState = newPaletteState;
    }

    changeAnimation(animation) {
        this.preAnimation = animation;
    }

    randomizedPalettes() {

    }

    renderAll(frame, characterData, canvas, offsetX = 0, offsetY = 0, clear = true) {
        const character = characterData || {
            preAnimation: this.preAnimation,
            partState: this.partState,
            paletteState: this.paletteState,
        }
        // this.ctx.drawImage(this.images["base"], 0, 0);
        const ctx = canvas ? canvas.getContext('2d', {
            willReadFrequently: true,
        }) : this.ctx;

        clear && ctx.clearRect(0, 0, 16, 24);

        const bodyXOffset = {
            no: 0,
            idle: 2,
            run: 7,
        };

        const newFrame = (character.preAnimation === "no") ? 0 : frame;

        for (const [key, partConfig] of Object.entries(PARTS_CONFIG)) {
            let dx = 0, dy = 0;
            if (key === "base") {
                dx = (16 * bodyXOffset[character.preAnimation]) + (16 * newFrame);
                dy = character.partState[key] * 24;
            } else {
                dx = character.partState[key] * 16;
                dy = aniData[key][character.preAnimation][newFrame] * -1;
            }
            ctx.drawImage(this.images[partConfig.imageName], offsetX + dx * -1, offsetX + dy * -1);
            this.recolor(character.paletteState, ctx);
        }
    }

    async loadImages() {
        for (const part of Object.keys(this.images)) {
            this.images[part] = await this.loadImage(`./res/character/${part}.png`);
        }
    }

    async init(config) {

        await this.loadImages();

        this.tempCanvas = document.createElement('canvas');
        this.tempCanvas.width = CANVAS_WIDTH;
        this.tempCanvas.height = CANVAS_HEIGHT;
        this.canvas = document.createElement('canvas');
        this.canvas.width = CANVAS_WIDTH;
        this.canvas.height = CANVAS_HEIGHT;

        this.ctx = this.canvas.getContext("2d", {
            willReadFrequently: true,
        });
        this.initialized = true;
    }

    run() {
        const f = parseInt((Date.now() / 110)) % 4;

        if (this.initialized) {
            this.renderAll(f);
        }
        requestAnimationFrame(this.run.bind(this));
    }
}
