import React, {useRef, useState, useEffect, useLayoutEffect} from 'react';
import {UNIT_SIZE} from "../../../WonEngine/Types";
import WonEngine from "../../../WonEngine";
import {STAGE_SCALE, TextureSelectorEngine} from "./TextureSelectorEngine";
import {CANVAS_HEIGHT, CANVAS_SCALE, CANVAS_WIDTH} from "../../../containers/CharacterTool/CanvasRenderer";
import ItemEffectEditor from "../ItemEffectEditor/ItemEffectEditor";
import ColorSelector from "../../widgets/ColorSelector";
import Select from 'react-select';

const TEXTURES = ["weapons", "skill-icons", "spritesheet_16x16", "64x64"];
export const TextureSelectMode = {
    DEFAULT: "DEFAULT",
    AUTO_TILE: "AUTO_TILE",
}

const defaultFormData = {
    coords: [0, 0],
    size: [1, 1],
    textureName: "",
    affectCoordsList: [],
    cells: [],
};

const addTexture = (textureName, textureData, textureKeyType) => {
    const wonEngine = WonEngine.GetInstance();
    const {textureMgr} = wonEngine.managers;

    const textureKey = `${textureName}_${
        textureData.coords[0]}_${textureData.coords[1]}_${
        textureData.size[0]}_${textureData.size[1]}`;
    let texture = textureMgr.get(textureKeyType, textureKey);

    if (!texture) {
        texture = WonEngine.GetTexture(textureName,
            new PIXI.Rectangle(
                textureData.coords[0] * UNIT_SIZE, textureData.coords[1] * UNIT_SIZE,
                textureData.size[0] * UNIT_SIZE, textureData.size[1] * UNIT_SIZE
            ));
        console.log(`add texture : ${textureKey}`);
        textureMgr.add(textureKeyType, textureKey, texture);
    }
    return texture;
}

export default (props) => {
    const wonEngine = WonEngine.GetInstance();
    const {textureMgr} = wonEngine.managers;
    const {name, formData, selectMode, value, onKeyChange, schema, uiSchema, onChange} = props;
    const {coords, size} = formData || defaultFormData;
    const [showSelector, setShowSelector] = useState(false);
    const textureRef = useRef(null);
    const canvasWrapperRef = useRef(null);
    const textureSelector = useRef(null);
    const {textureKeyType, useTextureEffectEditor, tintColor} = uiSchema['ui:options'];
    const [texture, setTexture] = useState(null);
    const [canvasWrapperSize, setCanvasWrapperSize] = useState([0, 0]);
    const [selectedOption, setSelectedOption] = useState(null);

    const [textureName, setTextureName] = useState(schema.textureName || uiSchema['ui:options'].textureName);

    // const textureName = schema.textureName || uiSchema['ui:options'].textureName;
    const newTextureName = schema.textureName;

    useEffect(() => {
        setTextureName(schema.textureName);
    }, [schema.textureName]);

    const onPointerDown = (pos, size) => {
        const textureData = {
            textureName,
            coords: [pos.x / UNIT_SIZE, pos.y / UNIT_SIZE],
            size: [size.x / UNIT_SIZE, size.y / UNIT_SIZE],
        }

        // const textureKey = `${textureName}_${
        //     textureData.coords[0]}_${textureData.coords[1]}_${
        //     textureData.size[0]}_${textureData.size[1]}`;
        // let texture = textureMgr.get(textureKeyType, textureKey);
        //
        // if (!texture) {
        //     texture = WonEngine.GetTexture(textureName,
        //         new PIXI.Rectangle(
        //             textureData.coords[0] * UNIT_SIZE, textureData.coords[1] * UNIT_SIZE,
        //             textureData.size[0] * UNIT_SIZE, textureData.size[1] * UNIT_SIZE
        //         ));
        //     console.log(`add texture : ${textureKey}`);
        //     textureMgr.add(textureKeyType, textureKey, texture);
        // }

        const texture = addTexture(textureName, textureData, textureKeyType);

        onChange(textureData);
        setTexture(texture);
    }

    const handleClickOutside = (event) => {
        if (canvasWrapperRef.current &&
            !canvasWrapperRef.current.contains(event.target) &&
            !textureRef.current.contains(event.target)
        ) {
            setShowSelector(false);
        }
    }

    // 처음에 아이템이 선택되지않아서 formData = null
    // useEffect(()=> {
    //     const textureData = formData?.itemData?.texture;
    //     if(textureData) {
    //         const texture = textureMgr.getByTextureInfo(formData?.itemData?.texture);
    //         if(texture) {
    //             setTexture(texture)
    //         }
    //     }
    // },[])

    useEffect(() => {
        let textureSelectorEngine = TextureSelectorEngine.GetInstance();

        if (!textureSelectorEngine) {
            textureSelectorEngine = new TextureSelectorEngine({
                container: canvasWrapperRef.current,
                // view: canvasRef.current,
                textureName,
            });
        }
        textureSelectorEngine.onPointerDown = onPointerDown;
        textureSelectorEngine.changeTexture(textureName);
        setCanvasWrapperSize([
            textureSelectorEngine.sprite.texture.width * STAGE_SCALE,
            textureSelectorEngine.sprite.texture.height * STAGE_SCALE,
        ]);

        if (!textureSelector.current) {
            textureSelector.current = textureSelectorEngine;
        }

        canvasWrapperRef.current.appendChild(textureSelectorEngine.renderer.view);

        Object.assign(textureSelectorEngine.renderer.view.style, {
            width: `${textureSelectorEngine.renderer.width}px`,
            height: `${textureSelectorEngine.renderer.height}px`,
        })

        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        }
    }, [textureName])

    useEffect(() => {
        if (coords && size && formData) {
            textureSelector.current.select(coords[0], coords[1], size[0], size[1]);
            const textureKey = `${formData.textureName}_${coords[0]}_${coords[1]}_${size[0]}_${size[1]}`;

            const newTexture = textureMgr.get(textureKeyType, textureKey);
            if (newTexture) {
                setTexture(newTexture);
            }
        }
    }, [formData])

    const handleClickTexture = () => {
        setShowSelector(!showSelector);
    };

    const handleChangeTexture = (e) => {
        setSelectedOption(e);
        setTextureName(e.value)
        // setTexture()
    }

    const base64Img = wonEngine.extractToBase64(texture);

    const textureOptions = TEXTURES.map(textureName => ({
        value: textureName,
        label: textureName,
    }))

    return <div style={styles.textureSelector}>
        <div className={"control-label"}
            // style={styles.name}
        >{`${name} [${textureName}.png]`}</div>
        <div style={{
            display: 'flex',
            flexDirection: 'row',
        }}>

            <div>
                <img ref={textureRef} src={base64Img} style={styles.img} onClick={handleClickTexture.bind(this)}/>

                <div style={{
                    width: '150px',
                }}>
                    textureSelector
                    <Select options={textureOptions}
                            defaultValue={selectedOption}
                            onChange={handleChangeTexture.bind(this)}
                        // value={"value"}
                    />
                </div>
                {
                    <div ref={canvasWrapperRef} style={Object.assign({}, styles.canvasWrapper, {
                        width: `${canvasWrapperSize[0]}px`,
                        height: `${canvasWrapperSize[1]}px`,
                        display: showSelector === true ? 'flex' : 'none',
                    })}>
                    </div>
                }
                {/*{*/}
                {/*    tintColor && <div>*/}
                {/*        tintColor*/}
                {/*        <ColorSelector/>*/}
                {/*    </div>*/}
                {/*}*/}
            </div>
            {
                useTextureEffectEditor &&
                <ItemEffectEditor textureData={formData}
                                  textureKeyType={textureKeyType}
                                  onChange={onChange}/>
            }

        </div>
    </div>
}

const styles = {
    textureSelector: {
        position: "relative",
        userSelect: 'none',
    },
    img: {
        width: `${16 * 4}px`,
        height: `${16 * 4}px`,
        border: '1px solid black',
        cursor: 'pointer',
        imageRendering: 'pixelated',
    },
    canvasWrapper: {
        position: 'absolute',
        overflow: 'scroll',
        zIndex: '9',
    },
    name: {
        display: 'flex',
        width: '200px',
    }
}
