import React, {useEffect, useLayoutEffect, useState, useRef} from 'react';
import WonEngine, {RENDER_TYPE} from "../WonEngine";
import {Unity, UnityContext, useUnityContext} from "react-unity-webgl";
import WeaponSelector from "./WeaponSelector";
import {loadDatabase} from "../DataRequester";


const appendGameView = (canvasContainerRef, props) => {
    const wonEngine = WonEngine.GetInstance();

    wonEngine.renderer.resize(
        canvasContainerRef.current.clientWidth,
        canvasContainerRef.current.clientHeight
    )
    canvasContainerRef.current.append(wonEngine.renderer.view);

    wonEngine.setRenderType(props.renderType);
    wonEngine.load(props);
};

export default (props) => {
    const wonEngine = WonEngine.GetInstance();
    const canvasContainerRef = useRef(null);
    const {
        unityContext, renderType, selectedModeItem,
        isUnityMounted, mountUnity
    } = props;

    const {isLoaded, sendMessage, loadingProgression} = unityContext || {};
    useLayoutEffect(() => {


    }, [])

    useEffect(() => {
        wonEngine.setRenderType(renderType);
    }, [renderType])

    useEffect(() => {
        (async () => {
            if (selectedModeItem === "EDIT") {
                if (isUnityMounted && unityContext) {
                    await unityContext.unload();
                    mountUnity && mountUnity(false);
                }
                // console.log(unityContext);
                appendGameView(canvasContainerRef, props);
            }
            if (selectedModeItem === "PLAY") {
                mountUnity && mountUnity(true);
            }
        })();
    }, [selectedModeItem])

    useEffect(() => {
        if (isLoaded && isUnityMounted) {
            // console.log("isLoaded")
            // sendMessage("GameManager", "Say");
            // sendMessage("GameManager", "Say");

            (async () => {
                // const database = await loadDatabase();
                const wonEngine = WonEngine.GetInstance();
                const mapData = WonEngine.GetInstance().saveData({
                    isUnityCoord: true
                });

                // Todo 서버 코드랑 통합.
                const newDatabase = {
                    autoTiles: wonEngine.autoTileData,
                    gameData: {
                        tiles: wonEngine.tiles,
                        objects: wonEngine.objects,
                        characters: wonEngine.characters.map(character => {
                            const newCharacter = {...character};
                            newCharacter.shape = newCharacter.body;
                            delete newCharacter.body;
                            return newCharacter;
                        }),
                        items: wonEngine.items,
                    },
                    // ...WonEngine.GetInstance().database,
                    mapData: mapData.mapData,
                }
                console.log(newDatabase.gameData.characters);
                sendMessage("GameManager", "LoadGameData", JSON.stringify(newDatabase));
            })()

        }
    }, [isLoaded]);

    return (<div style={styles.EngineView}>
        {
            props.children
        }
        {/*{*/}
        {/*    isUnityMounted && loadingProgression !== 1 &&*/}
        {/*    <div style={{*/}
        {/*        // fontSize: '3em',*/}
        {/*        position: 'absolute',*/}
        {/*        color: "white",*/}
        {/*    }}>Loading {Math.floor(loadingProgression * 100)}%</div>*/}
        {/*}*/}
        {
            isUnityMounted && unityContext ? <Unity
                    unityProvider={unityContext.unityProvider}
                    style={{
                        // display: 'flex',
                        // height: "100%",
                        width: "100%",
                    }}
                />
                : <div style={styles.EngineView} ref={canvasContainerRef}/>
        }
    </div>)
}

const styles = {
    EngineView: {
        width: '100%',
        height: '100%',
    },
}
