import React from 'react';
import Cookies from 'js-cookie'

export default (props) => {
    const {
        components, setCurrentMenuItem, currentMenuItem,
        unityContext,
        isUnityMounted, mountUnity
    } = props;

    const selectMenuItem = (selectedMenuItem) => {
        setCurrentMenuItem(selectedMenuItem);
        Cookies.set(`currentMenuItem`, selectedMenuItem);
    }

    const handleClickMenuItem = async (selectedMenuItem) => {

        if (isUnityMounted) {
            // (async () => {
            //
            // })();
            await unityContext.unload();
            mountUnity(false);
            selectMenuItem(selectedMenuItem);
        } else {
            selectMenuItem(selectedMenuItem);
        }
    }

    return <div style={styles.topMenu}>
        {
            Object.keys(components).map(menuItem => <div style={Object.assign({},
                styles.menuItem, {
                    color: currentMenuItem === menuItem ? "skyblue" : "white",
                })} key={menuItem} onClick={handleClickMenuItem.bind(this, menuItem)}>
                {menuItem}
            </div>)
        }

        {/*<div style={styles.menuItem} onClick={()=>{*/}
        {/*    window.history.pushState({}, '', '/fantasyduel');*/}
        {/*    window.location.reload();*/}
        {/*}}>FantasyDuel</div>*/}
    </div>
}

const styles = {
    topMenu: {
        // height: '500px',
        // width: '100%',
        userSelect: 'none',
        // flex : 1,
        display: 'flex',
        flexFlow: 'row',

        color: 'white',
        backgroundColor: 'black'
    },
    menuItem: {
        fontSize: '1.5em',
        margin: '0.2em',
        cursor: 'pointer',
        fontWeight: 'bold'

    },
}
