import Entity from "../Entity";
import WonEngine from "../index";
import {CONTAINER_SCALE} from "../Types";
import Component from "./Component";
import SpriteRenderer from "./SpriteRenderer";
import AutoTileRenderer from "../stageRenderers/AutoTileRenderer/AutoTileRenderer";

export default class Terrain extends Component {
    bit: number = 0;
    data = null;
    textGraphic: PIXI.Text = new PIXI.Text('', {
        fontSize: 12,
        fill: 0xFFFFFF,
        fontWeight: 'bold',
        stroke: '#000000',
        strokeThickness: 3,
        align: 'left'
    });
    shadow = null;

    updateTextureByBit() {
        const {autoTileRenderer} = WonEngine.GetInstance().stageRenderers;

        let newBit = this.bit;

        let bitTile;

        // 좌상
        if (newBit & 128) {
            if (!((newBit & 1) && (newBit & 64))) {
                newBit &= ~128;
            }
        }
        // 우상
        if (newBit & 2) {
            if (!((newBit & 1) && (newBit & 4))) {
                newBit &= ~2;
            }
        }
        // 좌하
        if (newBit & 32) {
            if (!((newBit & 64) && (newBit & 16))) {
                newBit &= ~32;
            }
        }
        // 우하
        if (newBit & 8) {
            if (!((newBit & 4) && (newBit & 16))) {
                newBit &= ~8;
            }
        }

        bitTile = autoTileRenderer.bitTiles[newBit];

        const entityData = this.target.data;
        const sprite = this.target.getComponent(SpriteRenderer).sprite;

        if (bitTile) {
            const textureIndex =AutoTileRenderer.GetAutoTileMapIndex(entityData);
            sprite.texture = autoTileRenderer.splitTileTextureList[textureIndex][`${newBit}`];
        } else {
            sprite.texture = PIXI.Texture.WHITE;
        }
    }


    bitMask(value, isRemoving = false) {
        if (!isRemoving) {
            this.bit |= value;
        } else {
            this.bit &= ~value;
        }
        this.textGraphic.text = `${this.bit}`;
    }

    constructor(scale = CONTAINER_SCALE) {
        super();
        this.textGraphic.visible = true;
        this.textGraphic.text = `${this.bit}`;
        this.textGraphic.scale.x /= scale;
        this.textGraphic.scale.y /= scale;

        // const sprite = this.target.getComponent(SpriteRenderer).sprite;
        // this.Entity(this.textGraphic);
    }
}
