import {FragmentTypeTable} from "../../Types";

export default class GeneratedTile extends PIXI.Container {
    fragments = [];
    coords = new PIXI.Point();
    generatedAutoTileView = null;

    constructor(generatedAutoTileView, coordX, coordY) {
        super();
        this.generatedAutoTileView = generatedAutoTileView;
        this.coords.set(coordX, coordY);
        this.x = 16 * coordX;
        this.y = 16 * coordY;
        this.interactive = true;
        this.hitArea = new PIXI.Rectangle(0, 0, 16, 16);
        this.on('pointerdown', this.handlePointerDown);

        for (let dy = 0; dy < 2; dy++) {
            for (let dx = 0; dx < 2; dx++) {
                const fragmentSprite = new PIXI.Sprite(PIXI.Texture.WHITE);
                fragmentSprite.x = 8 * dx;
                fragmentSprite.y = 8 * dy;
                fragmentSprite.width = 8;
                fragmentSprite.height = 8;
                fragmentSprite.alpha = 0.8;
                // @ts-ignore
                fragmentSprite.fragmentType =
                    FragmentTypeTable[coordY * 8 + coordX][dy * 2 + dx];

                this.fragments.push(fragmentSprite);
                this.addChild(fragmentSprite);
            }
        }
    }

    handlePointerDown(e) {
        const localPos = this.toLocal(e.data.global);
        const fragmentIndex = Math.floor((localPos.y / 8)) * 2 + Math.floor((localPos.x / 8));
        const selectedFragment = this.fragments[fragmentIndex];
        if (!selectedFragment) {
            return;
        }

        this.generatedAutoTileView.replaceAllAutoTiles(this.coords.x, this.coords.y, selectedFragment);
    }
}
