import React, {useState, useEffect, useLayoutEffect} from 'react';


export default (props) => {
    const {label, schema, onChange, value} = props;
    const {style = {}, items} = props.options;


    const handleOnClick = (item, index) => {
        onChange(schema.type === 'number' ? index : item.name);
    };

    return <div style={styles.itemSelector}>
        {/*<div style={styles.label}>*/}
        {/*    {label}*/}
        {/*</div>*/}
        <div style={{
            // marginTop: '1em',
            display: 'flex',
            flexDirection: 'row',
        }}>
            {
                items.map((item, index) => {
                    const isSelected = schema.type === 'number'
                        ? (value === index)
                        : (value === item.name);

                    return <div key={index} style={Object.assign({},
                        styles.item, style, item.style, isSelected && styles.itemSelect)}
                                onClick={handleOnClick.bind(this, item, index)}>{item.name}
                    </div>
                })
            }
        </div>
    </div>
}

const styles = {
    itemSelector: {
        userSelect: 'none',
        display: 'flex',
        flexDirection: 'column',
        // margin: '1em 0 1em',
    },
    label: {
        marginBottom: "0.5em",
        display: 'flex',
        width: '100px',
    },
    item: {
        width: '100px',
        height: '40px',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        cursor: 'pointer',

        backgroundColor: 'lightGray',
        opacity: 0.3,
        textShadow: '2px 2px 2px white',
        fontWeight: 'bold',

        padding: '0.5em',
        boxSizing: 'border-box',
        margin: "-1px 0 0 -1px",
        border: '1px solid black',
    },
    itemSelect: {
        opacity: 1,
        outline: '2px solid black',
        color: 'black',
        zIndex: 1,
    }
}
