import TileGrid from "../../WonEngine/Grid";
import WonEngine from "../../WonEngine";
import wonEngine from "../../WonEngine";
import {TextureKeyTypes, UNIT_SIZE} from "../../WonEngine/Types";

const MAX_WIDTH = 10, MAX_HEIGHT = 10;
const TILE_SIZE = 16;
const STAGE_WIDTH = MAX_WIDTH * TILE_SIZE;
const STAGE_HEIGHT = MAX_HEIGHT * TILE_SIZE
const CELL_SIZE = 10

const STAGE_SCALE = 2;


export class BackPackEditorEngine {
    stage
    itemContainer = new PIXI.Container()
    renderer
    isInitialized = false

    constructor(props = {}) {
        const {
            width = 256 * STAGE_SCALE,
            height = 256 * STAGE_SCALE,
            textureName
        } = props;
        const renderer = new PIXI.Renderer({
            width: CELL_SIZE * TILE_SIZE * STAGE_SCALE,
            height: CELL_SIZE * TILE_SIZE * STAGE_SCALE,
            backgroundColor: 0x1099bb,
            antialias: false,
            // roundPixels: true,
            // view,
        });

        const stage = new PIXI.Container();
        stage.scale.set(STAGE_SCALE, STAGE_SCALE);

        const grid = new TileGrid(STAGE_WIDTH, STAGE_HEIGHT, TILE_SIZE,
            // graphics => graphics.lineStyle(0.5, 0xFFFFFF, 0.3)
        );

        stage.addChild(grid)
        stage.addChild(this.itemContainer)

        renderer.render(stage)

        this.stage = stage;
        this.renderer = renderer;
    }

    clearItems() {
        this.itemContainer.removeChildren()
        this.renderer.render(this.stage);
    }

    getItemData(itemDataId) {
        const itemDatabase = WonEngine.GetInstance().cards || []

        const itemDataIndex = itemDatabase.findIndex(itemData =>
            itemData.id === itemDataId)

        if (itemDataIndex === -1) {
            console.log(`itemData[${itemDataId}] is null.`)
            return null;
        }

        return itemDatabase[itemDataIndex]
    }

    // match preDirection:
    //     0:
    // spriteOffset = Vector2(spriteSize.x, spriteSize.y)
    // 1:
    //     spriteOffset = Vector2(spriteSize.y, spriteSize.x)
    // 2:
    //     spriteOffset = Vector2(spriteSize.x, spriteSize.y)
    // 3:
    //     spriteOffset = Vector2(spriteSize.y, spriteSize.x)
    // 4:
    //     spriteOffset = Vector2(spriteSize.x, spriteSize.y)
    getItemOffset(preDirection, spriteSize) {
        let spriteOffset = spriteSize;
        switch (preDirection) {
            case 0:
            case 2:
            case 4:
                spriteOffset = new PIXI.Point(spriteSize.x, spriteSize.y);
                break;
            case 1:
            case 3:
                spriteOffset = new PIXI.Point(spriteSize.y, spriteSize.x);
                break;
        }

        return spriteOffset
    }

    addItems(items) {
        const {cards: itemDatabase = []} = WonEngine.GetInstance();
        const {textureMgr} = wonEngine.GetInstance().managers;

        items.forEach(item => {
            const itemData = itemDatabase.find(data => data.id === item.itemDataId);
            if (!itemData) {
                console.log(`itemData[${item.id}] is null.`);
                return;
            }

            const {textureName, coords, size} = itemData.texture;
            const textureKey = `${textureName}_${coords.join("_")}_${size.join("_")}`;
            let texture = textureMgr.get(TextureKeyTypes.ITEM, textureKey) ||
                WonEngine.GetTexture(textureName, new PIXI.Rectangle(
                    coords[0] * UNIT_SIZE, coords[1] * UNIT_SIZE,
                    size[0] * UNIT_SIZE, size[1] * UNIT_SIZE
                ));

            const itemSprite = new PIXI.Sprite(texture);
            itemSprite.anchor.set(0.5);
            itemSprite.rotation = item.preDirection * Math.PI / 2;

            const itemOffset = this.getItemOffset(item.preDirection,
                new PIXI.Point(size[0] * TILE_SIZE, size[1] * TILE_SIZE));
            itemSprite.x = item.itemCoords[0] * TILE_SIZE + itemOffset.x * 0.5;
            itemSprite.y = item.itemCoords[1] * TILE_SIZE + itemOffset.y * 0.5;

            this.itemContainer.addChild(itemSprite);
        });

        this.renderer.render(this.stage);
    }

    init(items) {
        // this.addItems(items);
        this.isInitialized = true;
    }
}
