import React from 'react'
import {TextureKeyTypes, TILE_SIZE, UNIT_SIZE} from "../WonEngine/Types";
import WonEngine from "../WonEngine";
import AutoTileRenderer from "../WonEngine/stageRenderers/AutoTileRenderer/AutoTileRenderer";

const textureSize = 32;
const whiteTexture = new PIXI.Texture(PIXI.Texture.WHITE, new PIXI.Rectangle(0, 0, 8, 8));

export default (props) => {
    const {item} = props;
    const wonEngine = WonEngine.GetInstance();

    let base64Texture;
    let imageWidth = TILE_SIZE;
    let imageHeight = TILE_SIZE;

    const getItemTexture = (item) => {
        const {autoTileRenderer} = WonEngine.GetInstance().stageRenderers;
        let defaultTexture;

        if (item.index === 0) {
            defaultTexture = whiteTexture;
        } else {
            if (AutoTileRenderer.IsAutoTile(item)) {
                const autoTileIndex = AutoTileRenderer.GetAutoTileMapIndex(item);
                defaultTexture = autoTileRenderer.splitTileTextureList[autoTileIndex]['0'];
            } else {
                if (item.itemType === "ITEM") {
                    defaultTexture = WonEngine.GetTexture(item.texture.textureName, new PIXI.Rectangle(
                        item.texture.coords[0] * UNIT_SIZE,
                        item.texture.coords[1] * UNIT_SIZE,
                        item.texture.size[0] * 16,
                        item.texture.size[1] * 16
                    ))
                    imageWidth = item.texture.size[0] * 16;
                    imageHeight = item.texture.size[1] * 16;
                } else {
                    defaultTexture = wonEngine.managers.textureMgr.getByTextureInfo(item.texture);
                }
            }
            return wonEngine.extractToBase64(defaultTexture, item.texture);

        }

        return wonEngine.extractToBase64(defaultTexture);
    };

    return <img style={styles.itemTexture} src={getItemTexture(item, imageWidth, imageHeight)}/>
}

const styles = {
    itemTexture: {
        border: '2px solid black',
        width: `${textureSize}px`,
        height: `${textureSize}px`,
        imageRendering: 'pixelated',
    },
}
