import WonEngine from "../index";
import {MAX_TILE_HEIGHT, MAX_TILE_WIDTH} from "../Types";
import Manager from "./Manager";

const packetTypes = {
    GAME_DATA: "GAME_DATA",
    CONNECT: "CONNECT",
}

enum clientType {
    UNKNOWN,
    WEB_MASTER,
    UNITY_CLIENT,
}

export default class SocketMgr extends Manager {
    ws: WebSocket = null;

    constructor() {
        super();
    }

    init() {
        const wonEngine = WonEngine.GetInstance();
        // wonEngine.mapToolRenderer

        this.ws = new WebSocket("ws://localhost:9001");

        this.ws.onopen = (ws) => {
            // console.log('onopen');
            this.ws.send(JSON.stringify({
                clientType: clientType.WEB_MASTER,
                type: packetTypes.CONNECT,
            }))
        };

        this.ws.onmessage = () => {
            // console.log('connected to server.');
        }

        this.ws.onerror = (err) => {
            // console.log(err);
        }

        this.ws.onclose = (er) => {
            // console.log('onclose');
        }
    }

    connect() {

    }
}
