import React, {useEffect, useRef} from 'react';
import {BackPackEditorEngine} from "./BackPackEditorEngine";

const backPackEditorEngine = new BackPackEditorEngine()

export default props => {
    const {name, formData = [], selectMode, value, onKeyChange, schema, uiSchema, onChange} = props;
    const canvasWrapperRef = useRef(null);

    useEffect(() => {

        backPackEditorEngine.clearItems();
        if (formData.length > 0) {
            const sortedItems = [
                ...formData,
            ]
            sortedItems.sort((a, b) => {
                const itemDataA = backPackEditorEngine.getItemData(a.itemDataId);
                const itemDataB = backPackEditorEngine.getItemData(b.itemDataId);

                const isA_Bag = itemDataA.cardType === "BAG";
                const isB_Bag = itemDataB.cardType === "BAG";

                if (isA_Bag && !isB_Bag) return -1; // A가 Bag이면 A를 앞으로
                if (!isA_Bag && isB_Bag) return 1;  // B가 Bag이면 B를 앞으로
                return 0; // 둘 다 같거나 둘 다 Bag 아님 → 순서 유지
            });

            backPackEditorEngine.addItems(sortedItems);
        }
    }, [formData])

    useEffect(() => {
        if (!backPackEditorEngine.isInitialized) {
            backPackEditorEngine.init()
        }
        canvasWrapperRef.current.appendChild(backPackEditorEngine.renderer.view);
    }, [])

    return <div>
        <div className={"control-label"}>BackPackEditor</div>
        <div ref={canvasWrapperRef}/>
    </div>
}
