import Manager from "./Manager";
import {EntityTypes, ItemTypes, LayerTypes, UNIT_SIZE} from "../Types";
import WonEngine from "../index";
import {Missile} from "../entities/Missile";


export default class MissileMgr extends Manager {
    entities: Set<Missile> = new Set();
    arrowItems = {};
    arrowItemArray = [];
    textures = {};

    init() {
        const {items} = WonEngine.GetInstance();

        const arrowItems = items.filter(item => item.itemType === ItemTypes.ARROW);
        this.arrowItemArray = arrowItems;
        arrowItems.forEach(arrow => {
            this.textures[arrow.name] = WonEngine.GetTextureByData(arrow.texture);
            this.arrowItems[arrow.name] = arrow;
        })
    }

    launch() {
        const defaultArrowTexture = this.textures['arrow'];
        const {hero} = this.wonEngine;

        const missile = new Missile(defaultArrowTexture, hero.x, hero.y);
        this.entities.add(missile)
    }

    update() {
        const {entityMgr} = WonEngine.GetInstance().managers;
        for (const entity of this.entities) {
            entity.update();

            const entityCoords = entity.getCoords();

            for (const [key, object] of Object.entries(entityMgr.entityMap[EntityTypes.OBJECT])) {
                const objectCoords = key.split('_').map(value => Number(value));

                if (entity.movedDistance >= 5000 ||
                    objectCoords[0] === entityCoords.x && objectCoords[1] === entityCoords.y) {
                    entity.release();
                    this.entities.delete(entity);
                }
            }
        }
    }
}
