import React, {useEffect} from 'react';

export default props => {
    const {stat, onRemove, index, statList, setStatList} = props;
    const {value} = stat;

    useEffect(() => {

    }, [value])
    const handleChanged = (e) => {
        const newValue = parseInt(e.target.value);

        const newStatList = [
            ...statList,

        ];

        newStatList[index] = {
            ...newStatList[index],
            value: newValue
        }

        setStatList(newStatList)
    }

    return <div style={{
        display: 'flex',
        flexFlow: 'column',
    }}>
        <div style={{
            display: 'flex',
            textAlign: 'left',
            marginRight: '0.5em',
        }}>{stat.type}</div>
        <div style={{
            display: 'flex',
        }}>
            <input type={"range"} style={{
                width: "300px",
            }} value={value} min={-10} max={30} onChange={handleChanged.bind(this)}/>
            <div style={{
                display: 'flex',
                justifyContent: 'center',
                margin: '1em',
                width: "70px",
            }}>{value}</div>
            <button style={{
                padding: '0.5em',
            }} onClick={() => onRemove(stat, index)}>Remove
            </button>
        </div>
    </div>
}
