import React, {useState, useEffect} from 'react';
import WonEngine from "../WonEngine";
import {Rarities} from "../jsonSchema/widgets/RaritySelector";

const itemBoxes = new Array(8).fill(null);
const ITEM_SIZE = 100;
const ITEM_SCALE = 2;
const UNIT_SIZE = 16;

export default (props) => {
    const {items} = props
    const [heroItems, setHeroItems] = useState([]);
    const [selectedItemIndex, setSelectedItemIndex] = useState(0);

    const wonEngine = WonEngine.GetInstance();
    const {weaponMgr} = wonEngine.managers;

    useEffect(() => {
        const newHeroItems = Object.entries(weaponMgr.textures).map(kv => kv[0]);
        setHeroItems([...newHeroItems]);
        weaponMgr.setSelectedItemIndex = setSelectedItemIndex;

        return () => {
            console.log("removed");
            weaponMgr.selectItem(-1);
        }
    }, []);

    useEffect(() => {
        weaponMgr.selectItem(selectedItemIndex);
    }, [selectedItemIndex])

    return <div style={styles.weaponSelector}>
        <div style={styles.itemWrapper}>
            {
                itemBoxes.map((item, index) => {
                    const {weaponMgr} = wonEngine.managers;
                    const texture = PIXI.Texture.WHITE;
                    let imgSrc = wonEngine.extractToBase64(texture, ITEM_SIZE, ITEM_SIZE);

                    let weaponImg = null;

                    const weaponName = heroItems[index];

                    if (weaponName) {
                        imgSrc = wonEngine.extractToBase64(weaponMgr.textures[heroItems[index]]);
                        weaponImg = <img style={{
                            imageRendering: 'pixelated',
                            width: `${items[weaponName]?.texture?.size[0] * UNIT_SIZE * ITEM_SCALE}px`,
                            height: `${items[weaponName]?.texture?.size[1] * UNIT_SIZE * ITEM_SCALE}px`,
                        }} src={imgSrc}/>
                    }

                    return <div key={index} style={Object.assign({}, {
                            // backgroundColor: Rarities[items[weaponName]].color,
                        }, styles.item,
                        selectedItemIndex === index && styles.selectedItem)}>
                        {
                            weaponImg
                        }
                    </div>
                })
            }
        </div>
    </div>
}

const styles = {
    weaponSelector: {
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
    },
    item: {
        margin: '5px',
        width: '100px',
        height: '100px',
        backgroundColor: 'lightgray',
        boxSizing: 'border-box',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
    },
    selectedItem: {
        outline: '5px solid blue',
    },
    itemWrapper: {
        position: 'absolute',
        bottom: '0.5em',
        display: 'flex',
        flexDirection: 'row',
    }
}
