import React, {useEffect, useState} from 'react';

export const DefaultOptions = [
    {
        label: "KR",
        value: "KR"
    },
    {
        label: "EN",
        value: "EN",
    }
]

export const DEFAULT_FORM_DATA = {
    "name_kr": "아이템 한국어 이름",
    "name_en": "item english name",
    "desc_kr": "한국어 설명",
    "desc_en": "English description",
    // "materials" : "아이템 재료 배열 []",
    // "skills" : "아이템 스킬 배열 []"
}


export const generateDefaultInputValue = (options) => {
    const inputValue = {};

    for (const lang of options) {
        inputValue[lang.value] = "";
    }

    return inputValue;
}

const TextareaField = React.memo(({label, value, onChange}) => {
    return (
        <div style={{marginBottom: '1em'}}>
            <div>{label}</div>
            <textarea
                style={{
                    fontSize: '1em',
                    // height: '1.5em'
                }}
                className="form-control"
                value={value}
                onChange={onChange}
            />
        </div>
    );
});

const parseJSONCode = async (result, onChange) => {
    // const json = await result.json();

    // 코드블록 내부만 정규식으로 추출
    // const match = content.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    const match = result.match(/```json\s*([\s\S]*?)\s*```/);

    // const match = result.choices[0].message.content.match(/```json\s*([\s\S]*?)\s*```/);

    if (match) {
        try {
            const _json = JSON.parse(match[1]);

            // console.log(_json)

            const localizedText = {
                ...DEFAULT_FORM_DATA,
            }

            for (const key of Object.keys(localizedText)) {
                localizedText[key] = _json[key];
            }

            onChange({
                ...localizedText
            })

        } catch (err) {
            console.error("JSON 파싱 에러:", err);
        }
    } else {
        console.error("JSON 코드블록을 찾지 못했습니다.");
    }
}

export default (props) => {
    const {
        label, name, schema, formData,
        onChange, value, formContext
    } = props;

    const [content, setContent] = useState("");
    const [temperature, setTemperature] = useState(0.7);
    const [additionalMessages, setAdditionalMessages] = useState("");

    const handleInputChange = (lang, e) => {
        onChange({
            ...formData,
            [lang]: e.target.value
        });
    };

    const handleClickGenerate = async () => {

        const rootData = formContext?.rootData

        if (!rootData) {
            console.log("!rootData");
        }

        const messages = [
            {
                role: "system", content: `rpg 게임의 아이템 정보를 생성합니다. 다음 형식의 올바른 JSON으로만 응답해 주세요:
${JSON.stringify(DEFAULT_FORM_DATA)}`
            },
            {role: "user", content: `${rootData.name}의 아이템 정보를 한개 생성한다. {}형식`}
        ]
        messages.push({
            role: "system", content: additionalMessages
        })

        // messages.push(additionalMessages)

        const result = await fetch("http://localhost:1234/api/v0/chat/completions", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify({
                model: "gemma-3-12b-it",
                // model: "qwen3-14b",
                // model : "phi-4",
                messages,
                temperature,
                "max_tokens": -1,
                "stream": true
            })
        });

        if (!result.ok) {
            console.error("HTTP 오류!", result.status);
            return null;
        }

        const decoder = new TextDecoder("utf-8");
        const reader = result.body.getReader();
        let textContent = ""
        let buffer = "";
        while (true) {
            const {value, done} = await reader.read();
            if (done) break;

            buffer += decoder.decode(value, {stream: true});
            const lines = buffer.split("\n");
            buffer = lines.pop(); // 마지막 줄 덜 끝난 거 다시 버퍼에 보존

            for (const line of lines) {
                if (!line.trim().startsWith("data:")) continue;
                const jsonStr = line.replace("data: ", "").trim();
                if (jsonStr === "[DONE]") break;

                try {
                    const data = JSON.parse(jsonStr);
                    const delta = data.choices?.[0]?.delta;
                    const finish = data.choices?.[0]?.finish_reason;

                    if (finish === "stop") break;

                    if (delta?.content) {
                        textContent += delta.content
                        setContent(textContent);
                        // console.log(textContent)

                        // parseJSONCode(textContent, onChange);

                        // outputEl.textContent += delta.content;
                    }
                } catch (e) {
                    console.error("JSON 파싱 실패:", e, jsonStr);
                }
            }
        }

        await parseJSONCode(textContent, onChange);
    }

    const handleClickClear = () => {
        onChange({
            ...DEFAULT_FORM_DATA
        })
    }

    return <div>
        <div className={"control-label"}>{name}</div>
        <div style={{
            display: 'flex',
            flexDirection: 'column',
            // justifyContent: 'center',
            // alignItems: 'center',
        }}>
            <button onClick={handleClickClear.bind(this)}>clear</button>
            <button onClick={handleClickGenerate.bind(this)}>생성</button>
            {/*<Select options={DefaultOptions} value={selectedOption}*/}
            {/*        onChange={handleOptionChange.bind(this)}/>*/}

            <label htmlFor="slider">temperature: {temperature}</label>
            <input
                id="slider"
                type="range"
                min="0"
                max="3"
                step="0.1"
                value={temperature}
                onChange={(e) => {
                    setTemperature(Number(e.target.value));
                }}
            />
            <textarea
                style={{
                    fontSize: '1em',
                    // height : '5em',
                    height: '5em'
                }}
                // className="form-control"
                value={additionalMessages}
                onChange={(e) => setAdditionalMessages(e.target.value)}
            />
            {/*setAdditionalMessages*/}
            <div style={{
                marginBottom: '0.5em',
            }}>{content}</div>
            {
                Object.keys(DEFAULT_FORM_DATA).map((key) => (<TextareaField
                    key={key}
                    label={key}
                    value={formData[key]}
                    onChange={(e) => handleInputChange(key, e)}
                />))
            }
        </div>
    </div>
}
