import TileGrid from "../../../WonEngine/Grid";

let _instance = null;

export const STAGE_SCALE = 2;

export class TextureSelectorEngine {
    renderer;
    selectionGraphic;
    stage;
    sprite;
    onPointerDown = null;

    grid;

    static GetInstance() {
        return _instance;
    }

    constructor(props) {
        _instance = this;
        const {width = 256 * STAGE_SCALE, height = 256 * STAGE_SCALE, textureName} = props;
        const renderer = new PIXI.Renderer({
            width: 256 * STAGE_SCALE,
            height: 256 * STAGE_SCALE,
            backgroundColor: 0x1099bb,
            antialias: false,
            // roundPixels: true,
            // view,
        });


        // selectionGraphic.
        const selectionGraphic = new PIXI.Graphics();
        selectionGraphic.lineStyle(1, 0xFFFFFF, 1);
        selectionGraphic.drawRect(0, 0, 16, 16);
        selectionGraphic.setSize = (width, height) => {
            const lineWeight = 1;
            selectionGraphic.clear();
            selectionGraphic.lineStyle(1, 0xFFFFFF, 1);
            selectionGraphic.drawRect(lineWeight, lineWeight, width - lineWeight, height - lineWeight);
        };
        this.selectionGraphic = selectionGraphic;


        const texture = PIXI.Loader.shared.resources[textureName].texture;
        const sprite = new PIXI.Sprite(texture);
        sprite.interactive = true;

        this.sprite = sprite;
        this.grid = new TileGrid(sprite.width, sprite.height, 16,
            graphics => graphics.lineStyle(0.5, 0xFFFFFF, 0.3));

        const stage = new PIXI.Container();
        stage.addChild(sprite);
        stage.addChild(this.grid);

        stage.addChild(selectionGraphic);
        stage.scale.set(STAGE_SCALE, STAGE_SCALE);
        renderer.render(stage);

        let isResizing = false;
        const startedPosition = new PIXI.Point();
        const size = new PIXI.Point();
        sprite.on('pointerdown', e => {
            const pointer = stage.toLocal(e.data.global);
            const coords = new PIXI.Point(
                Math.floor(pointer.x / 16),
                Math.floor(pointer.y / 16)
            );

            size.set(16, 16);
            selectionGraphic.position.set(coords.x * 16, coords.y * 16);
            selectionGraphic.setSize(16, 16);

            startedPosition.copyFrom(selectionGraphic.position);
            renderer.render(stage);

            isResizing = true;
        });
        sprite.on('pointermove', e => {
            const pointer = stage.toLocal(e.data.global);
            pointer.x = Math.floor(pointer.x / 16) * 16;
            pointer.y = Math.floor(pointer.y / 16) * 16;

            if (isResizing) {
                const minX = Math.min(startedPosition.x, pointer.x);
                const minY = Math.min(startedPosition.y, pointer.y);
                const maxX = Math.max(startedPosition.x, pointer.x) + 16;
                const maxY = Math.max(startedPosition.y, pointer.y) + 16;

                size.set(maxX - minX, maxY - minY);
                selectionGraphic.position.set(minX, minY);
                selectionGraphic.setSize(size.x, size.y);
            }
            renderer.render(stage);
        });

        const selectionFinish = () => {
            isResizing = false;
            renderer.render(stage);

            this.onPointerDown && this.onPointerDown(selectionGraphic.position, size);
        }

        sprite.on('pointerup', selectionFinish);
        // sprite.on('pointerout', selectionFinish);

        // if (coords && size) {
        //     selectionGraphic.position.set(coords.x * 16, coords.y * 16);
        //     selectionGraphic.setSize(size.x * 16, size.y * 16);
        // }

        this.stage = stage;
        this.renderer = renderer;
    }

    changeTexture(textureName) {
        // Todo
        if(!textureName) {
            return;
        }

        const texture = PIXI.Loader.shared.resources[textureName].texture;
        if(texture) {
            this.sprite.texture = texture;

            this.grid.setGrid(this.sprite.texture.width, this.sprite.texture.height, 16,
                graphics => graphics.lineStyle(0.5, 0xFFFFFF, 0.3))

            this.renderer.resize(texture.width * STAGE_SCALE, texture.height * STAGE_SCALE);
        }
    }

    select(x, y, width, height) {
        this.selectionGraphic.position.set(x * 16, y * 16);
        this.selectionGraphic.setSize(width * 16, height * 16);
        this.renderer.render(this.stage);
    }

    release() {
        // this.selectionGraphic.destroy();
        // this.selectionGraphic = null;
        // this.stage.destroy()
        // this.stage = null;
        // this.renderer.destroy();
        // this.renderer = null;
    }
}
