import React from 'react';
import {AttackTypes, ItemTypes} from "../../WonEngine/Types";

const itemTypes = [
    {
        name: 'sword',
        value: ItemTypes.SWORD,
    },
    {
        name: 'axe',
        value: ItemTypes.AXE,
    },
    {
        name: 'hammer',
        value: ItemTypes.HAMMER,
    },
    {
        name: 'arrow',
        value: ItemTypes.ARROW,
    },
];

export default (props) => {
    const {label, value, onChange} = props;
    return <div>
        {label}
        <div style={{
            display: 'flex',
            flexDirection: 'row',
            cursor: 'pointer',
            // userSelect: 'none',
        }}>
            {
                itemTypes.map((itemType, index) =>
                    <div key={itemType.name} style={Object.assign({}, styles.name,
                        value === itemType.value && styles.selected)} onClick={() => onChange(itemType.value)}>
                        {itemType.name}
                    </div>)
            }
        </div>
    </div>
}

const styles = {
    name: {
        userSelect: 'none',
        width: '100px',
        height: '40px',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: 'lightGray',
        opacity: 0.3,
        textShadow: '2px 2px 2px white',
        fontWeight: 'bold',
    },
    selected: {
        opacity: 1,
        outline: '2px solid black',
        color: 'orange',
    }
}
