import React, {useEffect, useState} from 'react';
import {PALETTE_COLORS} from "../../containers/CharacterTool/CanvasRenderer";

const getIndex = (value, useString) => {
    if (useString) {
        const index = PALETTE_COLORS.ISLAND_JOY_16.findIndex(color => color === value);
        if (index !== -1) {
            return index
        }
    }

    return value
}

export default (props) => {
    const {label, value, options, onChange} = props;
    const {useString} = options;

    const handleOnChange = (index) => {
        if (useString) {
            onChange(PALETTE_COLORS.ISLAND_JOY_16[index]);
        } else {
            onChange(index);
        }
    }

    return <div key={label} style={styles.paletteWrapper}>
        <div className={"control-label"} style={{
            marginRight: '1em',
        }}>
            {label}
        </div>
        {/*<div style={styles.partLabel}>{label}</div>*/}
        {
            PALETTE_COLORS.ISLAND_JOY_16.map((palette, index) =>
                <div key={palette} style={Object.assign({}, styles.palette, {
                    backgroundColor: palette,
                }, (getIndex(value, !!useString) === index) && styles.paletteSelect)}
                     onClick={() => handleOnChange(index)}/>)
        }
    </div>

    // return (
    //     <input type="text"
    //            className="custom"
    //            value={props.value}
    //            required={props.required}
    //            onChange={(event) => props.onChange(event.target.value)}/>
    // );
};

const styles = {
    palette: {
        cursor: 'pointer',
        margin: "-1px 0 0 -1px",
        border: '1px solid black',
        width: "25px",
        height: "25px",
        boxSizing: 'border-box',
    },
    paletteSelect: {
        outline: '2px solid black',
        zIndex: 1,
    },
    paletteWrapper: {
        marginTop: '1em',
        display: 'flex',
        alignItems: 'center',
        // flexDirection: 'row',
    },
    partLabel: {
        display: 'flex',
        justifyContent: "center",
        width: '100px',
    },
}
