import Rectangle from "../../geom/Rectangle";
import WonEngine from "../../index";
import {CharState, CONTAINER_SCALE, MAX_TILE_HEIGHT, MAX_TILE_WIDTH, TILE_SIZE} from "../../Types";
import {Key} from "../MapToolRenderer";
import Movement from "../../components/Movement";
import SpriteRenderer from "../../components/SpriteRenderer";
import ActionBase from "./ActionBase";

export class PlayAction extends ActionBase {
    position = new PIXI.Point();
    oldPosition = new PIXI.Point();

    selectionRectangle: Rectangle = new Rectangle();

    clearSelectionGraphic() {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;

        this.selectionRectangle.copyFrom(PIXI.Rectangle.EMPTY);
        mapToolRenderer.selectionGraphic.clear();
        mapToolRenderer.selectionGraphic.visible = true;
    }

    drawSelectionGraphic() {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;

        this.selectionRectangle.x = Math.min(this.oldPosition.x, this.position.x);
        this.selectionRectangle.y = Math.min(this.oldPosition.y, this.position.y);
        this.selectionRectangle.width = Math.abs(this.oldPosition.x - this.position.x);
        this.selectionRectangle.height = Math.abs(this.oldPosition.y - this.position.y);

        mapToolRenderer.selectionGraphic.clear();
        mapToolRenderer.selectionGraphic.lineStyle(3, 0xFFFFFF, 1);
        mapToolRenderer.selectionGraphic.drawRect(this.selectionRectangle.x, this.selectionRectangle.y, this.selectionRectangle.width, this.selectionRectangle.height);
    }

    onPointerDown() {
        this.oldPosition.copyFrom(this.position);
        this.clearSelectionGraphic();
    }

    onPointerUp() {
        const {mapToolRenderer} = WonEngine.GetInstance().stageRenderers;

        mapToolRenderer.selectionGraphic.visible = false;
    }

    onPointerMove(event) {
        const {mapToolRenderer, autoTileRenderer} = WonEngine.GetInstance().stageRenderers;
        this.position = event.data.getLocalPosition(mapToolRenderer.stage);
        // console.log(this.position);
    }


    render() {
        const {renderer, hero, stageRenderers} = WonEngine.GetInstance();
        const {characterMgr} = WonEngine.GetInstance().managers;
        const {mapToolRenderer} = stageRenderers;
        const wheelValue = mapToolRenderer.wheelValue;
        const cameraTarget = characterMgr.cameraTarget;
        // console.log(`hero.x : ${hero.x} hero.y : ${hero.y}`);

        mapToolRenderer.container.position.set(
            +TILE_SIZE * MAX_TILE_WIDTH * wheelValue * 0.5
            - cameraTarget.x * wheelValue
            + renderer.width * 0.5
            - 16 * wheelValue * 0.5
            ,
            +TILE_SIZE * MAX_TILE_HEIGHT * wheelValue * 0.5
            - cameraTarget.y * wheelValue
            + renderer.height * 0.5
            - 24 * wheelValue * 0.5
            ,
        );

        // this.drawSelectionGraphic();
    }
}
