import * as PIXI from 'pixi.js';
import 'pixi-layers';

import {v4 as uuidv4} from 'uuid';
import Basis from './Basis';
import {StageRenderer} from "./StageRenderer";
import AutoTileRenderer from "./stageRenderers/AutoTileRenderer/AutoTileRenderer";
import MapToolRenderer from "./stageRenderers/MapToolRenderer";
import EntityMgr from "./Managers/EntityMgr";
import {
    ActionTypes, CameraTargetTypes,
    EntityTypes,
    EntityTypeToDataKey,
    LayerTypes,
    MAX_TILE_HEIGHT,
    MAX_TILE_WIDTH,
    UNIT_SIZE
} from "./Types";
import AutoTileGenerator from "./stageRenderers/AutoTileRenderer/AutoTileGenerator";
import EffectRenderer from "./stageRenderers/EffectRenderer";
import Entity from "./Entity";
import SocketMgr from "./Managers/SocketMgr";
import GameObject from "./GameObject";
import CharacterMgr from "./Managers/CharacterMgr/CharacterMgr";
import InGameRenderer from "./stageRenderers/InGameRenderer";
import WeaponMgr from "./Managers/WeaponMgr";
import Manager from "./Managers/Manager";
import MovementSystem from "./systems/MovementSystem";
import AttackSystem from "./systems/AttackSystem";
import TextureMgr from "./Managers/TextureMgr";
import MissileMgr from "./Managers/MissileMgr";
import ItemMgr from "./Managers/ItemMgr";
import GameInstanceMgr from "./Managers/InstanceGameMgr/GameInstanceMgr";
import RoomMgr from "./Managers/RoomMgr";

export const RENDER_TYPE = {
    NONE: 'none',
    PLAY: 'inGameRenderer',
    MAP_TOOL: 'mapToolRenderer',
    AUTO_TILE_TOOL: 'autoTileRenderer',
    EFFECT_TOOL: 'effectRenderer',
}

class WonEngine extends Basis {
    gameObjects: GameObject[] = [];
    characters: any;
    database: any;
    autoTileData: any;
    items: any;
    objects: any;
    tiles: any;
    cards: any;

    skills: any;

    stats: any;
    base64TextureCaches: any = {}

    stageRenderers: { [key: string]: any } = {
        inGameRenderer: new InGameRenderer(),
        mapToolRenderer: new MapToolRenderer(),
        autoTileRenderer: new AutoTileRenderer(),
        effectRenderer: new EffectRenderer(),
    };

    autoTileGenerator = new AutoTileGenerator();

    renderType: string = RENDER_TYPE.NONE;
    renderType2: string = RENDER_TYPE.NONE;
    // renderType2 : string = "renderType2";

    loadedData: any = null;

    // managers: { [key: string]: Manager } = {
    managers: { [key: string]: any } = {
        roomMgr: new RoomMgr(),
        textureMgr: new TextureMgr(),
        characterMgr: new CharacterMgr(),
        entityMgr: new EntityMgr(),
        socketMgr: new SocketMgr(),
        weaponMgr: new WeaponMgr(),
        missileMgr: new MissileMgr(),
        itemMgr: new ItemMgr(),
        gameInstanceMgr: new GameInstanceMgr(),
    }

    systems: { [key: string]: any } = {
        attackSystem: new AttackSystem,
        movementSystem: new MovementSystem,
    }

    hero: Entity = null;

    ticker: PIXI.Ticker = PIXI.Ticker.shared;

    constructor() {
        super();
        // this.ticker.autoStart = false;
    }

    static GetTexture(textureName, frame = null) {
        if (!textureName)
            return null

        const loader = PIXI.Loader.shared;
        const texture = loader.resources[textureName]?.texture;
        if (frame) {
            return new PIXI.Texture(texture.baseTexture, frame);
        }
        return texture;
    }

    static GetTextureByData(textureData) {
        const loader = PIXI.Loader.shared;
        const texture = loader.resources[textureData.textureName]?.texture;
        return new PIXI.Texture(texture.baseTexture,
            new PIXI.Rectangle(
                textureData.coords[0] * UNIT_SIZE, textureData.coords[1] * UNIT_SIZE,
                textureData.size[0] * UNIT_SIZE, textureData.size[1] * UNIT_SIZE));
    }


    init(config) {
        super._init(config);

        this.database = config.database;
        this.autoTileData = config.autoTileData;

        this.tiles = config.tiles;
        this.objects = config.objects;
        this.characters = config.characters;
        this.items = config.items;
        this.cards = config.cards;
        this.skills = config.skills;
        this.stats = config.stats;

        for (const [key, manager] of Object.entries(this.managers)) {
            manager.init();
        }

        for (const [key, renderer] of Object.entries(this.stageRenderers)) {
            renderer.init();
        }

        document.addEventListener("keydown", function (e) {
            if (e.keyCode === 83 && (navigator.platform.match("Mac") ? e.metaKey : e.ctrlKey)) {
                e.preventDefault();
                // Process event...
            }
        }, false);
    }

    changeUserAction(selectedActionType) {
        const {characterMgr} = this.managers;
        const {mapToolRenderer} = this.stageRenderers;
        mapToolRenderer['selectedAction'] = selectedActionType;

        switch (selectedActionType) {

            case ActionTypes.PLAY:
                this.hero = characterMgr.getHero();
                characterMgr.setTarget(CameraTargetTypes.HERO);
                mapToolRenderer.selectLayer();
                break;
            case ActionTypes.MONITOR:
                characterMgr.setTarget(CameraTargetTypes.OBSERVER);
                mapToolRenderer.selectLayer();
                break;
            case ActionTypes.EDIT:
                this.hero = null;
                mapToolRenderer.selectLayer(LayerTypes.OLD);
                characterMgr.setTarget();
                break;
        }
    }

    filterCharacterData(characters = []) {
        return characters.map(character => {
            const filteredCharacter = {...character};
            delete filteredCharacter['dataURL'];
            delete filteredCharacter['textureId'];
            return (filteredCharacter)
        })
    }

    saveData(config = {
        isUnityCoord: false
    }) {
        const {entityMgr} = this.managers;
        const mapData = {
            tiles: {},
            objects: {},
            characters: {},
            items: {},
        };

        Object.entries(entityMgr.entityMap).forEach(([key, entities]) => {
            const dataKey = EntityTypeToDataKey[key];
            if (dataKey) {
                mapData[dataKey] = Object.entries(entities).map(([entityKey, entity]) => {

                    let coords = entityKey.split('_').map(s => Number(s))

                    if (config.isUnityCoord) {
                        coords[1] = MAX_TILE_HEIGHT - coords[1] - 1
                    }

                    return ({
                        id: entity.id,
                        coords,
                        type: key,
                    })
                });
            }
        });

        return {
            mapData: {
                ...mapData,
                width: MAX_TILE_WIDTH,
                height: MAX_TILE_HEIGHT,
            },
        };
    }

    addUUID(items) {
        const {entityMgr} = this.managers;
        for (const item of items) {
            if (!item.id) {
                item.id = uuidv4();
            }

            entityMgr.entityMapById[item.id] = item;
        }
    }

    loadData(loadedData = null) {
        const loadedDataArray = [
            "tiles",
            // "upperTiles",
            "items",
            "objects",
            "characters",
        ];
        const {entityMgr, roomMgr, characterMgr, itemMgr} = this.managers;
        if (loadedData) {
            this.database = loadedData;
        }
        const {width, height, ...mapData} = this.database.mapData;
        const wonEngine = WonEngine.GetInstance();
        const {mapToolRenderer, autoTileRenderer} = wonEngine.stageRenderers;

        mapToolRenderer.clear();

        let oldSelectedItem = mapToolRenderer.selectedItem;

        for (const [key, items] of Object.entries(mapData)) {

            if (!loadedDataArray.includes(key)) continue;
            console.log(`loaded Data : ${key}`);

            for (const item of items as Array<any>) {
                const [x, y] = item.coords;

                const entityData = entityMgr.getEntityDataById(item.id);
                if (!entityData) {
                    console.warn(`entityData data doesn't exist.`);
                    continue;
                }

                switch (key) {
                    case "characters":
                        characterMgr.add(entityData, x, y);
                        break;
                    case "items":
                        itemMgr.add(entityData, x, y);
                        break;
                    case "tiles":
                    case "objects":
                        const textureIndex = AutoTileRenderer.GetAutoTileMapIndex(entityData);
                        mapToolRenderer.selectedItem = entityData;
                        autoTileRenderer.setRenderingBitTextures(textureIndex);
                        mapToolRenderer.renderItem(item.coords[0], item.coords[1]);
                        break;
                    default :

                }
            }
        }

        mapToolRenderer.selectedItem = oldSelectedItem;

        // const room = roomMgr.generate();
    }

    extractToBase64(texture, textureInfo) {
        try {
            const sprite = new PIXI.Sprite(texture);
            const {textureName, coords, size} = textureInfo;
            const textureKey = `${textureName}_${coords[0]}_${coords[1]}_${size[0]}_${size[1]}`;

            let base64 = null;

            // console.log(textureKey)
            if (!this.base64TextureCaches[textureKey]) {
                base64 = this.renderer.extract.base64(sprite);
                this.base64TextureCaches[textureKey] = base64
            }

            return this.base64TextureCaches[textureKey];
        } catch (e) {
            return null;
        }
    };

    generateTexture(displayObject) {
        return this.renderer.generateTexture(displayObject, null, PIXI.SCALE_MODES.NEAREST);
    }


    setRenderType(newRenderType) {
        this.renderType = newRenderType;

        for (const [key, stageRenderer] of Object.entries(this.stageRenderers)) {
            stageRenderer.isActive = key === newRenderType;

            if (stageRenderer.isActive) {
                stageRenderer['enabled'] && stageRenderer['enabled']();
            }
        }
    }

    load(props) {
        const currentStageRenderer = this.stageRenderers[this.renderType];

        if (currentStageRenderer) {
            currentStageRenderer.load(props);
        }
    }

    render() {
        const {
            weaponMgr,
            characterMgr
        } = this.managers;
        const currentStageRenderer = this.stageRenderers[this.renderType];

        this.ticker.update(performance.now());

        for (const gameObject of this.gameObjects) {
            gameObject.update();
        }

        for (const [systemName, system] of Object.entries(this.systems)) {
            system.update();
        }

        for (const [systemName, manager] of Object.entries(this.managers)) {
            manager.update();
        }

        if (currentStageRenderer && currentStageRenderer.isActive) {
            currentStageRenderer.render();
            this.renderer.render(currentStageRenderer.stage);
        }

        requestAnimationFrame(this.render.bind(this));
    }
}

export default WonEngine;
