import {
    CONTAINER_SCALE,
    EntityTypes,
    fragTileSize,
    AUTO_TILE_RENDERING_SIZE,
    TILE_SIZE,
    MAX_TILE_WIDTH,
    MAX_TILE_HEIGHT
} from "./Types";
import WonEngine, {RENDER_TYPE} from "./index";
import Entity from "./Entity";
import AutoTileRenderer from "./stageRenderers/AutoTileRenderer/AutoTileRenderer";
import Tile from "./entities/Tile";
import Terrain from "./components/Terrain";
import SpriteRenderer from "./components/SpriteRenderer";
import Shadow from "./components/Shadow";
import {Stage} from "pixi-layers"
import Grid from "./Grid";

const directions = [
    [-1, -1, 128],
    [0, -1, 1],
    [1, -1, 2],

    [-1, 0, 64],
    [0, 0, 0],
    [1, 0, 4],

    [-1, 1, 32],
    [0, 1, 16],
    [1, 1, 8],
]

function getBitDirection(coordX: number, coordY: number) {
    const currentBitDirection = directions.find((bitDirection) =>
        bitDirection[0] === coordX && bitDirection[1] === coordY);

    return currentBitDirection ? currentBitDirection[2] : null;
}


class TileMap extends PIXI.display.Stage {
    wonEngine = WonEngine.GetInstance();
    tiles: Object = {};
    isDownedTileMapContainer: boolean = false;

    backgroundSprite: PIXI.Sprite = new PIXI.Sprite(PIXI.Texture.WHITE);
    bounds: PIXI.Rectangle = null;

    constructor(width, height) {
        super();

        this.bounds = new PIXI.Rectangle(0, 0, width, height);

        // this.scale.set(CONTAINER_SCALE, CONTAINER_SCALE);
        this.interactive = true;
        // this.tileMapContainer.x += this.container.width + 10;
        // this.y = 50;
        this.on("pointerdown", () => {
            this.isDownedTileMapContainer = true;
        });
        this.on("pointerup", () => {
            this.isDownedTileMapContainer = false;
        });
        // this.on("mouseleave ", () => {
        //     this.isDownedTileMapContainer = false;
        // });
        // this.tileMapContainer.addChild(new TileGrid(texture.width, texture.height, fragTileSize));

        // this.hitArea = new PIXI.Rectangle(0, 0, width, height);


        this.backgroundSprite = new PIXI.Sprite(PIXI.Texture.WHITE);
        this.backgroundSprite.width = width;
        this.backgroundSprite.height = height;
        // backgroundSprite.width = texture.width * CONTAINER_SCALE;
        // backgroundSprite.height = texture.height * CONTAINER_SCALE;
        this.backgroundSprite.alpha = 0.5;


        this.addChild(this.backgroundSprite);

    }

    applyNeighbors(tile: Tile, entityType, coordX, coordY) {
        const {entityMgr} = WonEngine.GetInstance().managers;

        for (const [px, py] of directions) {
            const neighborCoordX = coordX + px;
            const neighborCoordY = coordY + py;
            const neighborTile: Tile = entityMgr.getEntity(entityType, coordX + px, coordY + py);

            if (!AutoTileRenderer.IsAutoTile(neighborTile?.data)) {
                continue;
            }

            if (neighborTile) {
                const neighborTileBit = getBitDirection(
                    coordX - neighborCoordX,
                    coordY - neighborCoordY
                );

                neighborTile.getComponent(Terrain).bitMask(neighborTileBit, !tile);
                neighborTile.getComponent(Terrain).updateTextureByBit();

                if (tile) {
                    const tileBit = getBitDirection(
                        neighborCoordX - coordX,
                        neighborCoordY - coordY
                    );
                    tile.getComponent(Terrain).bitMask(tileBit);
                    tile.getComponent(Terrain).updateTextureByBit();
                }
            }
        }
    }

    paintTile(coordX, coordY) {
        const {roomMgr, entityMgr, textureMgr} = WonEngine.GetInstance().managers;
        const selectedItemData = WonEngine.GetInstance().stageRenderers.mapToolRenderer.selectedItem;
        const entityType = selectedItemData.itemType;
        const {size} = selectedItemData.texture;

        if (entityMgr.getEntity(entityType, coordX, coordY)) {
            return;
        }
        const tile = new Tile(selectedItemData, coordX, coordY);

        entityMgr.setEntity(entityType, tile, coordX, coordY);

        if (AutoTileRenderer.IsAutoTile(selectedItemData)) {
            this.applyNeighbors(tile, entityType, coordX, coordY);
        } else {
            const spriteRenderer = tile.getComponent(SpriteRenderer);
            const texture = textureMgr.getTextureByData(selectedItemData);
            if(!texture) {
                console.log("texture null");
            }
            tile.getComponent(SpriteRenderer).setTexture(texture);
            const yOffset = (size[1] - 1) * TILE_SIZE;

            spriteRenderer.pivotSprite.y = yOffset;
            spriteRenderer.sprite.y -= yOffset;
            spriteRenderer.sprite.width = size[0] * TILE_SIZE;
            spriteRenderer.sprite.height = size[1] * TILE_SIZE;


            const shadowComponent = tile.getComponent(Shadow);
            if (shadowComponent) {
                tile.getComponent(Shadow).resize(size[0] * TILE_SIZE, size[1] * TILE_SIZE);
                tile.getComponent(Shadow).sprite.y += spriteRenderer.sprite.y;
                tile.getComponent(Shadow).sprite.texture = texture;
            }

        }

        // if (entityType === EntityTypes.OBJECT) {
        //     roomMgr.setDirty(true);
        // }
    }
}

export default TileMap;
