import {fragTileSize} from "./Types";

class TileGrid extends PIXI.Graphics {
    constructor(width: number, height: number, tileSize: number, styleCAllBack = null) {
        super();
        this.setGrid(width, height, tileSize, styleCAllBack);
    }

    setGrid(width: number, height: number, tileSize: number, styleCAllBack = null) {
        const textureMaxCoordX = width / tileSize;
        const textureMaxCoordY = height / tileSize;
        const color = 0xFFFFFF;
        const lineSize = 0.5;

        this.clear();
        // draw Lines
        for (let y = 0; y <= textureMaxCoordY; y++) {
            if (styleCAllBack) {
                styleCAllBack(this);
            } else {
                this.lineStyle(lineSize, 0xFFFFFF, 1);
            }
            this.moveTo(0, y * tileSize);
            this.lineTo(width, y * tileSize);
        }

        for (let x = 0; x <= textureMaxCoordX; x++) {
            if (styleCAllBack) {
                styleCAllBack(this);
            } else {
                this.lineStyle(lineSize, 0xFFFFFF, 1);
            }
            this.moveTo(x * tileSize, 0);
            this.lineTo(x * tileSize, height);
        }
    }
}

export default TileGrid;
