import React, {useState} from "react";

export default ({
                    width = "250px",
                    defaultState,
                    children,
                    onClick
                }) => {
    const [selectedItemIndex, selectItem] = useState(defaultState);

    const handleSelectItem = (index) => {
        selectItem(index);
        onClick && onClick(index);
    };

    return <div style={Object.assign({}, styles.listView, {
        width
    })}>
        {
            children && children.map((item, index) =>
                <div key={index} style={Object.assign({}, styles.characterListItem,
                    (selectedItemIndex === index) && styles.characterSelect)}
                     onClick={handleSelectItem.bind(this, index)}>
                    {`item ${index}`}
                </div>)
        }
    </div>
};

const styles = {
    listView: {
        display: 'flex',
        flexDirection: 'column',
        userSelect: "none",
        backgroundColor: 'lightgray',
        width: '250px',
        // overflow: 'scroll',
    },
    characterListItem: {
        display: 'flex',
        backgroundColor: 'white',
        margin: '0.2em',
        padding: '0.2em',
        border: '1px solid #bbb',
        fontWeight: 'bold',
        textShadow: '2px 2px 2px #bbb',
        cursor: "pointer",
    },
    characterSelect: {
        color: 'orange',
    }
};
