import Component from "./Component";
import ShadowFilter from "../filters/shadow";
import {EntityTypes, TILE_SIZE} from "../Types";
import BlackFilter from "../filters/black";
import WonEngine from "../index";
import SpriteRenderer from "./SpriteRenderer";
import AutoTileRenderer from "../stageRenderers/AutoTileRenderer/AutoTileRenderer";

const blackFilter = new BlackFilter();

export default class Shadow extends Component {
    sprite = null;

    constructor() {
        super();
    }

    init() {
        const {layers} = WonEngine.GetInstance().stageRenderers['mapToolRenderer'];

        this.sprite = new PIXI.Sprite(PIXI.Texture.WHITE);
        this.sprite.filters = [blackFilter];
        // this.sprite.filterArea = new PIXI.Rectangle(0, 0, TILE_SIZE, TILE_SIZE);

        this.sprite.x = this.target.x;
        this.sprite.y = this.target.y;
        this.sprite.width = TILE_SIZE;
        this.sprite.height = TILE_SIZE;

        const spriteRenderer = this.target.getComponent(SpriteRenderer);
        // if (!AutoTileRenderer.IsAutoTile(this.target.data) &&
        //     this.target.data.itemType === EntityTypes.OBJECT) {
        //     this.sprite.y += spriteRenderer.sprite.y
        //     this.sprite.width = this.target.data.texture.size[0] * TILE_SIZE;
        //     this.sprite.height = this.target.data.texture.size[1] * TILE_SIZE;
        // }

        const itemType = this.target.data.itemType;

        if (itemType != EntityTypes.OBJECT &&
            itemType != EntityTypes.CHARACTER) {
            this.sprite.visible = false;
        }

        layers['SHADOW'].addChild(this.sprite);

        // tile.getComponent(Shadow).resize(size[0] * TILE_SIZE, size[1] * TILE_SIZE);

        // tile.getComponent(Shadow).sprite.y += spriteRenderer.sprite.y;
        // tile.getComponent(Shadow).sprite.texture = texture;
    }

    resize(width, height) {
        this.sprite.width = width;
        this.sprite.height = height;
    }

    release() {
        super.release();

        const {layers} = WonEngine.GetInstance().stageRenderers['mapToolRenderer'];

        layers['SHADOW'].removeChild(this.sprite);
    }
}
